// TCP Quant Terminal: one file for the Cloudflare dashboard (Edit code, paste, Deploy).
// Built by terminal/build.mjs from terminal/src; edit those files, not this one.

// Pure functions, no dependencies. Times are Unix seconds (UTC); bars are
// { t, o, h, l, c } with t the bar's open time, oldest first.
//
// These are standard, public reference levels (previous day and week, opens,
// session ranges, round numbers) and a probability engine built on a plain,
// stated model: price as a trendless random walk with each market's own
// hour-by-hour volatility. It forecasts reach, not direction, and it checks
// itself against history (calibrate). No strategy rules live here: the algo's
// own zones join the terminal only after they pass their forward test.

const MARKETS = {
  XAUUSD: { symbol: 'XAUUSD', name: 'Gold', digits: 2, contract: 100, day: 'ny', round: 50 },
  BTCUSD: { symbol: 'BTCUSD', name: 'Bitcoin', digits: 2, contract: 1, day: 'utc', round: 1000 },
};

// Forex sessions in local time, Monday to Friday.
const SESSIONS = [
  { id: 'sydney', name: 'Sydney', tz: 'Australia/Sydney', open: 7, close: 16 },
  { id: 'tokyo', name: 'Tokyo', range: 'Asia', tz: 'Asia/Tokyo', open: 9, close: 18 },
  { id: 'london', name: 'London', range: 'London', tz: 'Europe/London', open: 8, close: 17 },
  { id: 'newyork', name: 'New York', range: 'New York', tz: 'America/New_York', open: 8, close: 17 },
];

// ------------------------------------------------------------ time zones
const formatters = {};
function zoned(ts, tz) {
  formatters[tz] ||= new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, hourCycle: 'h23', weekday: 'short',
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
  });
  const p = {};
  for (const { type, value } of formatters[tz].formatToParts(new Date(ts * 1000))) p[type] = value;
  return { y: +p.year, m: +p.month, d: +p.day, h: +p.hour, min: +p.minute, s: +p.second, wd: p.weekday };
}

// The UTC time of a wall-clock time in a time zone (DST-aware).
function wallToUtc(tz, y, m, d, h = 0, min = 0) {
  const wall = Date.UTC(y, m - 1, d, h, min) / 1000;
  let ts = wall;
  for (let i = 0; i < 3; i++) {
    const z = zoned(ts, tz);
    const offset = Date.UTC(z.y, z.m - 1, z.d, z.h, z.min, z.s) / 1000 - ts;
    const next = wall - offset;
    if (next === ts) break;
    ts = next;
  }
  return ts;
}

// New York time without Intl, for loops over thousands of bars (a Worker on the free
// plan gets 10 ms of CPU per request). US daylight saving runs from the second Sunday
// in March, 02:00 local (07:00 UTC), to the first Sunday in November, 02:00 local (06:00 UTC).
function nthSunday(y, month, n, hourUtc) {
  const first = new Date(Date.UTC(y, month - 1, 1)).getUTCDay();
  return Date.UTC(y, month - 1, 1 + ((7 - first) % 7) + 7 * (n - 1), hourUtc) / 1000;
}
const usDst = {};
function nyOffset(ts) {
  // The year only picks the daylight-saving window, and both windows sit far from New
  // Year, so the average Gregorian year (365.2425 days) is exact enough and needs no Date.
  const y = 1970 + Math.floor(ts / 31556952);
  const [from, to] = (usDst[y] ||= [nthSunday(y, 3, 2, 7), nthSunday(y, 11, 1, 6)]);
  return ts >= from && ts < to ? -4 * 3600 : -5 * 3600;
}
const DAY = 86400;
const nyHour = (ts) => Math.floor(((((ts + nyOffset(ts)) % DAY) + DAY) % DAY) / 3600);

// The same yes/no as marketStatus(market, ts).open, fast enough for thousands of bars:
// gold shuts from Friday 17:00 to Sunday 18:00 New York, and from 17:00 to 18:00 each day.
function marketOpen(ts, market) {
  if (market.day === 'utc') return true;
  const local = ts + nyOffset(ts);
  const days = Math.floor(local / DAY);
  const hour = (local - days * DAY) / 3600;
  const weekday = (((days + 4) % 7) + 7) % 7; // 0 is Sunday: 1 January 1970 was a Thursday
  if (hour >= 17 && hour < 18) return false;
  return !(weekday === 6 || (weekday === 0 && hour < 18) || (weekday === 5 && hour >= 17));
}

// A trading day as a whole number of days since 1970 (fast; dayKey gives the same day as text).
function dayIndex(ts, market) {
  if (market.day === 'utc') return Math.floor(ts / DAY);
  const i = Math.floor((ts + nyOffset(ts) + 7 * 3600) / DAY);
  const wd = (i + 4) % 7; // 1 January 1970 was a Thursday; 0 is Sunday
  return wd === 6 ? i + 2 : wd === 0 ? i + 1 : i;
}

const iso = (y, m, d) => `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
const addDays = (key, n) => new Date(Date.parse(key + 'T00:00:00Z') + n * 86400e3).toISOString().slice(0, 10);
const weekdayOf = (key) => new Date(key + 'T00:00:00Z').getUTCDay(); // 0 Sunday ... 6 Saturday
const mondayOf = (key) => addDays(key, -((weekdayOf(key) + 6) % 7));

// The trading day a moment belongs to. Gold's day ends at 17:00 New York (as on
// broker charts), and a weekend belongs to the Monday after it; Bitcoin uses UTC days.
const keyOf = (index) => new Date(index * DAY * 1000).toISOString().slice(0, 10);
const dayKey = (ts, market) => keyOf(dayIndex(ts, market));

// ------------------------------------------------------------------- bars
// Merge bars (or days) that share a key into one bar per key.
function groupBars(bars, keyOf) {
  const out = [];
  for (const b of bars) {
    const key = keyOf(b);
    const last = out[out.length - 1];
    if (last && last.key === key) {
      last.h = Math.max(last.h, b.h);
      last.l = Math.min(last.l, b.l);
      last.c = b.c;
    } else {
      out.push({ key, t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });
    }
  }
  return out;
}

function toDays(bars, market) {
  const days = [];
  let index = null;
  for (const b of bars) {
    const i = dayIndex(b.t, market);
    const last = days[days.length - 1];
    if (last && i === index) {
      last.h = Math.max(last.h, b.h);
      last.l = Math.min(last.l, b.l);
      last.c = b.c;
    } else {
      index = i;
      days.push({ key: keyOf(i), t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });
    }
  }
  return days;
}

// Wilder's average true range over completed days.
function atr(days, period = 14) {
  if (days.length < period + 1) return null;
  const tr = days.slice(1).map((d, i) => Math.max(d.h - d.l, Math.abs(d.h - days[i].c), Math.abs(d.l - days[i].c)));
  let value = tr.slice(0, period).reduce((a, b) => a + b, 0) / period;
  for (const x of tr.slice(period)) value = (value * (period - 1) + x) / period;
  return value;
}

function rangeOf(bars, from, to) {
  const inside = bars.filter((b) => b.t >= from && b.t < to);
  if (!inside.length) return null;
  return { high: Math.max(...inside.map((b) => b.h)), low: Math.min(...inside.map((b) => b.l)) };
}

// Session windows on a trading day's date, in UTC.
function sessionWindow(session, key) {
  const [y, m, d] = key.split('-').map(Number);
  return { from: wallToUtc(session.tz, y, m, d, session.open), to: wallToUtc(session.tz, y, m, d, session.close) };
}

// ---------------------------------------------------------------- snapshot
// days: daily bars (the last may be today's, still forming); intraday: 15-minute bars.
function snapshot(market, days, intraday, now) {
  const today = dayKey(now, market);
  const done = days.filter((d) => d.key < today);
  let current = days.find((d) => d.key === today) || null;
  const fresh = intraday.filter((b) => dayKey(b.t, market) === today);
  if (fresh.length) {
    current = {
      key: today, t: current ? current.t : fresh[0].t, o: current ? current.o : fresh[0].o,
      h: Math.max(current ? current.h : -Infinity, ...fresh.map((b) => b.h)),
      l: Math.min(current ? current.l : Infinity, ...fresh.map((b) => b.l)),
      c: fresh[fresh.length - 1].c,
    };
  }
  const prev = done[done.length - 1] || null;
  const price = intraday.length ? intraday[intraday.length - 1].c : current ? current.c : prev ? prev.c : null;

  const thisWeek = mondayOf(today);
  const weeks = groupBars(done, (d) => mondayOf(d.key));
  const prevWeek = [...weeks].reverse().find((w) => w.key < thisWeek) || null;
  const weekOpenDay = days.find((d) => mondayOf(d.key) === thisWeek) || null;

  const averageRange = atr(done);
  const todayRange = current ? current.h - current.l : 0;

  const levels = [];
  const add = (id, name, value) => { if (Number.isFinite(value)) levels.push({ id, name, price: value }); };
  if (prev) { add('pdh', 'Previous day high', prev.h); add('pdl', 'Previous day low', prev.l); }
  if (prevWeek) { add('pwh', 'Previous week high', prevWeek.h); add('pwl', 'Previous week low', prevWeek.l); }
  if (current) add('do', 'Day open', current.o);
  if (weekOpenDay) add('wo', 'Week open', weekOpenDay.o);

  const sessions = {};
  for (const s of SESSIONS.filter((x) => x.range)) {
    const { from, to } = sessionWindow(s, today);
    const r = from <= now ? rangeOf(intraday, from, Math.min(to, now + 1)) : null;
    sessions[s.id] = r && { ...r, from, to, done: now >= to };
    if (r) { add(`${s.id}_h`, `${s.range} high`, r.high); add(`${s.id}_l`, `${s.range} low`, r.low); }
  }
  if (Number.isFinite(price)) {
    const below = Math.floor(price / market.round) * market.round;
    add('round_up', 'Round number', below + market.round);
    add('round_down', 'Round number', below === price ? below - market.round : below);
  }
  levels.sort((a, b) => b.price - a.price);

  return {
    symbol: market.symbol, name: market.name, digits: market.digits, day: today,
    price,
    dayOpen: current ? current.o : null,
    dayHigh: current ? current.h : null,
    dayLow: current ? current.l : null,
    change: current && Number.isFinite(price) ? price - current.o : null,
    changePct: current && Number.isFinite(price) ? ((price - current.o) / current.o) * 100 : null,
    atr: averageRange,
    todayRange,
    rangePct: averageRange ? (todayRange / averageRange) * 100 : null,
    levels,
    sessions,
  };
}

// ------------------------------------------------------------ session clock
// Which sessions are open at `now`, and when each next opens or closes.
function sessionClock(now) {
  return SESSIONS.map((s) => {
    const z = zoned(now, s.tz);
    const base = iso(z.y, z.m, z.d);
    let open = null;
    let next = null;
    for (let i = -1; i <= 7 && !next; i++) {
      const key = addDays(base, i);
      const wd = weekdayOf(key);
      if (wd === 0 || wd === 6) continue;
      const w = sessionWindow(s, key);
      if (w.from <= now && now < w.to) open = w;
      else if (w.from > now && !next) next = w;
    }
    return open
      ? { id: s.id, name: s.name, open: true, closesIn: open.to - now, until: open.to }
      : { id: s.id, name: s.name, open: false, opensIn: next ? next.from - now : null, at: next && next.from };
  });
}

// Gold closes from Friday 17:00 to Sunday 18:00 New York, with a daily break
// from 17:00 to 18:00; Bitcoin never closes.
function marketStatus(market, now) {
  if (market.day === 'utc') return { open: true };
  const z = zoned(now, 'America/New_York');
  const key = iso(z.y, z.m, z.d);
  const wd = weekdayOf(key);
  const hour = z.h + z.min / 60;
  const at = (dayOffset, h) => {
    const [y, m, d] = addDays(key, dayOffset).split('-').map(Number);
    return wallToUtc('America/New_York', y, m, d, h);
  };
  if (wd === 6) return { open: false, reason: 'weekend', opensAt: at(1, 18) };
  if (wd === 0 && hour < 18) return { open: false, reason: 'weekend', opensAt: at(0, 18) };
  if (wd === 5 && hour >= 17) return { open: false, reason: 'weekend', opensAt: at(2, 18) };
  if (hour >= 17 && hour < 18) return { open: false, reason: 'daily break', opensAt: at(0, 18) };
  const closeDay = hour >= 18 ? 1 : 0;
  return { open: true, closesAt: at(closeDay, 17), weekendClose: weekdayOf(addDays(key, closeDay)) === 5 };
}

// ------------------------------------------------------------------- risk
// usdPerUnit: the US-dollar value of one unit of the account currency
// (1 for USD accounts; about 1.3 for GBP). Lots round down to the broker's step.
function lotSize({ balance, riskPct, entry, stop, contract, usdPerUnit = 1, step = 0.01, min = 0.01 }) {
  const riskMoney = (balance * riskPct) / 100;
  const distance = Math.abs(entry - stop);
  const riskPerLot = (distance * contract) / usdPerUnit; // account currency lost at the stop, per 1.00 lot
  if (!(riskMoney > 0) || !(riskPerLot > 0)) return null;
  const lots = Math.floor(riskMoney / riskPerLot / step + 1e-9) * step;
  const rounded = Math.round(lots * 100) / 100;
  const side = entry > stop ? 'long' : 'short';
  const r = (k) => (side === 'long' ? entry + k * distance : entry - k * distance);
  return {
    side, riskMoney, distance, riskPerLot,
    lots: rounded,
    tooSmall: rounded < min,
    actualRisk: rounded * riskPerLot,
    perPoint: (rounded * contract) / usdPerUnit, // account currency per $1 move
    targets: [1, 2, 3].map((k) => ({ r: k, price: r(k), profit: k * rounded * riskPerLot })),
  };
}

// ------------------------------------------------------------- formatting
const fmtNum = (v, digits = 2) =>
  Number.isFinite(v) ? v.toLocaleString('en-GB', { minimumFractionDigits: digits, maximumFractionDigits: digits }) : '—';

function fmtDuration(seconds) {
  if (!Number.isFinite(seconds)) return '—';
  const m = Math.max(0, Math.round(seconds / 60));
  const d = Math.floor(m / 1440);
  const h = Math.floor((m % 1440) / 60);
  if (d) return `${d}d ${h}h`;
  return h ? `${h}h ${m % 60}m` : `${m % 60}m`;
}

// ------------------------------------------------------- probability engine
// The model: over the rest of the trading day, log price moves like a trendless
// random walk whose variance follows the market's own hour-of-day pattern (gold is
// quiet in Asia and busy at the London and New York opens). Under that model the
// reflection principle gives the chance of touching a level before the close.
// calibrate() replays history out of sample to show how honest the numbers are.

// Standard normal CDF (Abramowitz and Stegun 7.1.26, error below 1.5e-7).
function normCdf(x) {
  const z = Math.abs(x) / Math.SQRT2;
  const t = 1 / (1 + 0.3275911 * z);
  const erf = 1 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-z * z);
  return x >= 0 ? (1 + erf) / 2 : (1 - erf) / 2;
}

// Variance of hourly log returns for each hour of the day (New York time), from
// hourly bars. Thin hours are pulled towards the all-hours average.
function volProfile(hourly, shrink = 5) {
  const sums = new Array(24).fill(0);
  const counts = new Array(24).fill(0);
  for (let i = 1; i < hourly.length; i++) {
    const a = hourly[i - 1];
    const b = hourly[i];
    if (b.t - a.t !== 3600 || !(a.c > 0) || !(b.c > 0)) continue; // skip breaks and weekends
    const r = Math.log(b.c / a.c);
    const h = nyHour(b.t);
    sums[h] += r * r;
    counts[h] += 1;
  }
  const n = counts.reduce((a, b) => a + b, 0);
  const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;
  return sums.map((s, h) => (s + shrink * overall) / (counts[h] + shrink));
}

// Expected variance of log price between two moments, hour by hour.
function varianceBetween(profile, from, to) {
  let v = 0;
  for (let t = from; t < to;) {
    const next = Math.min(to, (Math.floor(t / 3600) + 1) * 3600);
    v += (profile[nyHour(t)] * (next - t)) / 3600;
    t = next;
  }
  return v;
}

// When the current trading day ends: 17:00 New York for gold, midnight UTC for Bitcoin.
function dayEnd(key, market) {
  const [y, m, d] = key.split('-').map(Number);
  if (market.day === 'utc') return Date.UTC(y, m - 1, d + 1) / 1000;
  const naive = Date.UTC(y, m - 1, d, 17) / 1000;
  return naive - nyOffset(naive);
}

// Chance of touching `level` before the close, with `variance` of log price left.
function touchProb(price, level, variance) {
  if (!(price > 0) || !(level > 0)) return null;
  if (!(variance > 0)) return price === level ? 1 : 0;
  const z = Math.abs(Math.log(level / price)) / Math.sqrt(variance);
  return Math.min(1, 2 * (1 - normCdf(z)));
}

// Chance of closing beyond `level`, on its side of the price.
function beyondProb(price, level, variance) {
  if (!(variance > 0)) return 0;
  return 1 - normCdf(Math.abs(Math.log(level / price)) / Math.sqrt(variance));
}

// The band that holds the close with a given probability (k = 1: 68%, k = 2: 95%).
const band = (price, variance, k) => [price * Math.exp(-k * Math.sqrt(variance)), price * Math.exp(k * Math.sqrt(variance))];

// The widening cone from now to the close, every `step` seconds.
function cone(price, profile, from, to, step = 900) {
  const points = [];
  let v = 0;
  for (let t = from; t < to;) {
    const next = Math.min(to, (Math.floor(t / step) + 1) * step);
    v += varianceBetween(profile, t, next);
    t = next;
    const [l1, u1] = band(price, v, 1);
    const [l2, u2] = band(price, v, 2);
    points.push({ t, l1, u1, l2, u2 });
  }
  return points;
}

// Probabilities for each level that can still be reached today. Levels inside
// today's range have already been touched.
function levelOdds(levels, price, high, low, variance) {
  return levels.map((l) => {
    const touched = Number.isFinite(high) && Number.isFinite(low) && l.price <= high && l.price >= low;
    return { ...l, side: l.price >= price ? 'above' : 'below', touched,
      touch: touched ? 1 : touchProb(price, l.price, variance),
      close: beyondProb(price, l.price, variance) };
  });
}

// Descriptive state of the market from hourly bars: trend efficiency over the last
// 24 hours (0 = choppy, 1 = one-way), momentum in standard deviations over 1, 4 and
// 24 hours, and where the last 24 hours' volatility ranks against the history.
function marketState(hourly, profile) {
  const n = hourly.length;
  if (n < 50) return null;
  const closes = hourly.map((b) => b.c);
  const last = closes[n - 1];
  const window = closes.slice(-25);
  let path = 0;
  for (let i = 1; i < window.length; i++) path += Math.abs(window[i] - window[i - 1]);
  const efficiency = path ? Math.abs(window[window.length - 1] - window[0]) / path : 0;
  const hourVar = profile.reduce((a, b) => a + b, 0) / 24;
  const momentum = (h) => Math.log(last / closes[n - 1 - h]) / Math.sqrt(hourVar * h);
  const sq = [0];
  for (let i = 1; i < n; i++) sq.push(sq[i - 1] + Math.log(closes[i] / closes[i - 1]) ** 2);
  const rv = (i) => sq[i] - sq[i - 24];
  const now = rv(n - 1);
  const past = [];
  for (let i = 24; i < n - 24; i += 6) past.push(rv(i));
  const rank = past.filter((x) => x < now).length / past.length;
  return { efficiency, momentum: { h1: momentum(1), h4: momentum(4), h24: momentum(24) }, volRank: rank, vol24: Math.sqrt(now) };
}

// Out-of-sample check of the touch probabilities on the previous day's high and low.
// For each past day: a volatility profile from the `lookback` days before it only,
// then at every hourly bar a forecast for each level not yet touched, scored against
// what happened by the close.
// One pass over the bars (it runs inside the Worker's CPU budget): the profile rolls
// forward a day at a time, and the variance left to the close is a suffix sum.
function calibrate(hourly, market, lookback = 20) {
  const days = [];
  for (let i = 0; i < hourly.length; i++) {
    const b = hourly[i];
    const a = hourly[i - 1];
    const day = dayIndex(b.t, market);
    const r2 = a && b.t - a.t === 3600 && a.c > 0 && b.c > 0 ? Math.log(b.c / a.c) ** 2 : null;
    const bar = { ...b, hour: nyHour(b.t), r2 };
    const last = days[days.length - 1];
    if (last && last.day === day) last.bars.push(bar);
    else days.push({ day, bars: [bar] });
  }
  const sums = new Array(24).fill(0);
  const counts = new Array(24).fill(0);
  const tally = (bars, sign) => {
    for (const b of bars) if (b.r2 !== null) { sums[b.hour] += sign * b.r2; counts[b.hour] += sign; }
  };
  const pairs = [];
  for (let d = 0; d < days.length - 1; d++) {
    if (d > lookback) {
      const n = counts.reduce((a, b) => a + b, 0);
      const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;
      const profile = sums.map((s, h) => (s + 5 * overall) / (counts[h] + 5));
      const prev = days[d - 1].bars;
      let pdh = -Infinity;
      let pdl = Infinity;
      for (const b of prev) { pdh = Math.max(pdh, b.h); pdl = Math.min(pdl, b.l); }
      const bars = days[d].bars;
      const k = bars.length;
      const highAfter = new Array(k);
      const lowAfter = new Array(k);
      const varAfter = new Array(k);
      for (let i = k - 1; i >= 0; i--) {
        highAfter[i] = Math.max(bars[i].h, i + 1 < k ? highAfter[i + 1] : -Infinity);
        lowAfter[i] = Math.min(bars[i].l, i + 1 < k ? lowAfter[i + 1] : Infinity);
        varAfter[i] = profile[bars[i].hour] + (i + 1 < k ? varAfter[i + 1] : 0);
      }
      let high = -Infinity;
      let low = Infinity;
      for (let i = 0; i < k; i++) {
        const price = bars[i].o;
        if (high < pdh && price < pdh) pairs.push([touchProb(price, pdh, varAfter[i]), highAfter[i] >= pdh ? 1 : 0]);
        if (low > pdl && price > pdl) pairs.push([touchProb(price, pdl, varAfter[i]), lowAfter[i] <= pdl ? 1 : 0]);
        high = Math.max(high, bars[i].h);
        low = Math.min(low, bars[i].l);
      }
    }
    // Roll the profile's window forward: this day in, the day `lookback` back out.
    tally(days[d].bars, 1);
    if (d - lookback >= 0) tally(days[d - lookback].bars, -1);
  }
  if (pairs.length < 50) return null;
  const rate = pairs.reduce((a, [, o]) => a + o, 0) / pairs.length;
  const brier = pairs.reduce((a, [p, o]) => a + (p - o) ** 2, 0) / pairs.length;
  const reference = rate * (1 - rate); // always forecasting the average rate
  const bins = [];
  for (let k = 0; k < 5; k++) {
    const lo = k / 5;
    const hi = (k + 1) / 5;
    const inside = pairs.filter(([p]) => p >= lo && (k === 4 ? p <= hi : p < hi));
    if (!inside.length) continue;
    bins.push({ lo, hi, n: inside.length,
      predicted: inside.reduce((a, [p]) => a + p, 0) / inside.length,
      observed: inside.reduce((a, [, o]) => a + o, 0) / inside.length });
  }
  return { days: days.length - 2 - lookback, n: pairs.length, brier, skill: reference ? 1 - brier / reference : 0, bins };
}

// Baseline odds for a trade on a trendless market: the chance the target comes
// before the stop, and the typical time until one of them is hit.
function tradeOdds(entry, stop, target, hourVar) {
  const risk = Math.abs(entry - stop);
  const reward = Math.abs(target - entry);
  if (!(risk > 0) || !(reward > 0)) return null;
  const sigma2 = hourVar * entry * entry; // price variance per hour
  return { targetFirst: risk / (risk + reward), hours: sigma2 > 0 ? (risk * reward) / sigma2 : null };
}

// TCP Quant Terminal: the Playbook's maths, shared by the Worker and the page.
// Pure functions, nothing stored. Times are Unix seconds (UTC); bars are
// { t, o, h, l, c } with t the bar's open time, oldest first.
//
// A setup is a trade plan logged before its result: gold or Bitcoin, buy or sell,
// a market, limit or stop order, an entry, a stop and one target, the reasons, and
// the engine's read of the market at that moment. advanceSetup() walks it through
// the bars that followed the way the orders would have filled, and settles every
// doubt against the setup, so the record can only look worse than the truth:
//   - a limit order fills at its price, never better;
//   - a stop order, or a stop, that the market gaps through fills at the open;
//   - on the bar an order fills, its stop counts and its target doesn't;
//   - when one bar reaches both the stop and the target, the stop came first.
// Results are in R, as the signal publisher counts them: the move from the fill to
// the exit over the planned risk, |entry - stop|.
//
// Judging the record. If the market moves at random, a trade's expected result is
// zero before costs, whatever its stop, target or management; its target comes
// before its stop with odds risk / (risk + reward), the "no-edge odds". So an edge
// is an average result, after costs, above zero by more than luck explains. The
// band around the average is where the true average sits with 95% confidence
// (Student's t), and the record gets a verdict only after PLAYBOOK.firstRead results.

const PLAYBOOK = {
  spread: { XAUUSD: 0.3, BTCUSD: 20 }, // assumed round-trip cost, in price, taken off every result
  scratch: 0.05, // a result within 0.05R of zero is a scratch, neither won nor lost
  firstRead: 20, // results before the record gets a verdict
  tagRead: 5, // results with a reason, market or session before it gets its own average
  maxTags: 6,
  minNote: 8,
  maxNote: 400,
  expiry: [4, 24, 168], // hours a limit or stop order can wait for its price
  rr: [0.3, 20], // the target's distance, in R, that a plan may use
};

const pbRound = (v, d) => Math.round(v * 10 ** d) / 10 ** d;

// A result in R for posts and the page: +2.0R, −1.0R (a true minus sign).
const fmtR = (v, d = 1) => (Number.isFinite(v) ? (v > 0 ? '+' : v < 0 ? '−' : '') + fmtNum(Math.abs(v), d) + 'R' : '—');

// ------------------------------------------------------------------ the plan
// Tidies a plan and checks that it makes sense and, given the live `quote`
// ({ price, atr, open }), that it's honest: a market order at the price now, a
// limit or stop order on the right side of it. Returns { plan } or { error, field }.
function checkPlan(input, quote) {
  const p = input || {};
  const market = MARKETS[p.symbol];
  if (!market) return { error: 'Pick gold or Bitcoin.', field: 'symbol' };
  if (p.side !== 'buy' && p.side !== 'sell') return { error: 'Pick buy or sell.', field: 'side' };
  if (!['market', 'limit', 'stop'].includes(p.kind)) return { error: 'Pick a market, limit or stop order.', field: 'kind' };
  const price = (v) => pbRound(typeof v === 'string' ? parseFloat(v.replace(/,/g, '')) : Number(v), market.digits);
  const [entry, sl, tp] = [p.entry, p.sl, p.tp].map(price);
  for (const [field, v, name] of [['entry', entry, 'entry'], ['sl', sl, 'stop'], ['tp', tp, 'target']]) {
    if (!(v > 0)) return { error: `Enter the ${name} price.`, field };
  }
  const buy = p.side === 'buy';
  if (buy ? !(sl < entry) : !(sl > entry)) return { error: `For a ${p.side}, the stop goes ${buy ? 'below' : 'above'} the entry.`, field: 'sl' };
  if (buy ? !(tp > entry) : !(tp < entry)) return { error: `For a ${p.side}, the target goes ${buy ? 'above' : 'below'} the entry.`, field: 'tp' };
  const rr = Math.abs(tp - entry) / Math.abs(entry - sl);
  if (rr < PLAYBOOK.rr[0] || rr > PLAYBOOK.rr[1]) {
    return { error: `The target is ${fmtNum(rr, 1)}R away: keep it between ${PLAYBOOK.rr[0]}R and ${PLAYBOOK.rr[1]}R.`, field: 'tp' };
  }
  const tags = [];
  for (const raw of Array.isArray(p.tags) ? p.tags : []) {
    const tag = String(raw).replace(/\s+/g, ' ').trim().slice(0, 24).trim();
    if (!tag || tags.some((t) => t.toLowerCase() === tag.toLowerCase())) continue;
    if (!/^[\p{L}\p{N}][\p{L}\p{N} &+./'-]*$/u.test(tag)) return { error: `"${tag}": a reason is a few words (letters, numbers, & + . / ' -).`, field: 'tags' };
    tags.push(tag);
  }
  if (tags.length > PLAYBOOK.maxTags) return { error: `Up to ${PLAYBOOK.maxTags} reasons.`, field: 'tags' };
  const note = String(p.note || '').replace(/\s+/g, ' ').trim();
  if (note.length < PLAYBOOK.minNote) return { error: 'Say why, in a sentence: it goes out with the setup.', field: 'note' };
  if (note.length > PLAYBOOK.maxNote) return { error: `Keep the why under ${PLAYBOOK.maxNote} characters.`, field: 'note' };
  const pending = p.kind !== 'market';
  const expiry = pending ? Number(p.expiry ?? 24) : null;
  if (pending && !(Number.isInteger(expiry) && expiry >= 1 && expiry <= 168)) return { error: 'Pick how long the order waits for its price.', field: 'expiry' };
  const plan = { symbol: market.symbol, side: p.side, kind: p.kind, entry, sl, tp, tags, note, expiry };
  if (!quote || !(quote.price > 0)) return { plan };

  const live = quote.price;
  const f = (v) => fmtNum(v, market.digits);
  if (p.kind === 'market') {
    if (quote.open === false) return { error: `${market.name} is closed: use a limit or stop order, or wait for the open.`, field: 'kind' };
    const tolerance = Math.max((quote.atr || 0) * 0.1, live * 0.0005);
    if (Math.abs(entry - live) > tolerance) {
      return { error: `The live price is ${f(live)}. A market order is logged at the price now; for another price, use a limit or stop order.`, field: 'entry' };
    }
    const pastStop = buy ? live <= sl : live >= sl;
    const pastTarget = buy ? live >= tp : live <= tp;
    if (pastStop || pastTarget) return { error: `The live price (${f(live)}) is already past the ${pastStop ? 'stop' : 'target'}.`, field: pastStop ? 'sl' : 'tp' };
  } else {
    // A buy limit or a sell stop waits below the price; a sell limit or a buy stop above it.
    const want = (p.kind === 'limit') === buy ? 'below' : 'above';
    if (entry === live || (want === 'below') !== entry < live) {
      return { error: `A ${p.side} ${p.kind} goes ${want} the live price (${f(live)}).`, field: 'entry' };
    }
  }
  return { plan };
}

// With no edge, the chance the target comes before the stop.
function noEdgeOdds(s) {
  const risk = Math.abs(s.entry - s.sl);
  return risk / (risk + Math.abs(s.tp - s.entry));
}

// ------------------------------------------------------------------ the setup
// A setup from a checked plan, logged at `at`. A market order is filled at once, at its
// entry. The minute it was logged in isn't scanned: its prices may come from before it.
function openSetup(plan, at) {
  const market = plan.kind === 'market';
  return {
    symbol: plan.symbol, side: plan.side, kind: plan.kind, entry: plan.entry, sl: plan.sl, tp: plan.tp,
    tags: plan.tags, note: plan.note, stop: plan.sl, created: at,
    expires: market ? null : at + plan.expiry * 3600,
    status: market ? 'open' : 'pending',
    filled: market ? at : null, fill: market ? plan.entry : null,
    closed: null, exit: null, r: null, reason: null,
    checked: Math.ceil(at / 60) * 60,
  };
}

const isActive = (s) => s.status === 'pending' || s.status === 'open';

// A result in R: from the fill to the exit, over the planned risk.
function planR(s, exit) {
  const move = s.side === 'buy' ? exit - s.fill : s.fill - exit;
  return pbRound(move / Math.abs(s.entry - s.sl), 2);
}

function settleSetup(s, at, exit, reason) {
  s.closed = at;
  s.exit = exit;
  s.r = planR(s, exit);
  s.reason = reason;
  s.status = s.r > PLAYBOOK.scratch ? 'won' : s.r < -PLAYBOOK.scratch ? 'lost' : 'scratch';
  return { type: reason, at, price: exit, r: s.r };
}

// Which stop was hit: the planned one, one moved to the fill (breakeven), or one trailed elsewhere.
const stopReason = (s) => (s.stop === s.sl ? 'sl' : s.stop === s.fill ? 'be' : 'trail');

// The price a pending order fills at on bar `b`, or null.
function fillOf(s, b) {
  const buy = s.side === 'buy';
  if (s.kind === 'limit') return (buy ? b.l <= s.entry : b.h >= s.entry) ? s.entry : null;
  if (buy) return b.h >= s.entry ? Math.max(s.entry, b.o) : null;
  return b.l <= s.entry ? Math.min(s.entry, b.o) : null;
}

function expireSetup(s) {
  s.status = 'expired';
  s.closed = s.expires;
  return { type: 'expired', at: s.expires };
}

// Walks a pending or open setup through `bars` of `step` seconds, from where it was last
// checked up to the last bar that has finished by `now`. A coarser bar that started before
// the last check still counts: nothing in its earlier part had touched anything, or the
// setup would have closed then. Returns the setup as it now stands and what happened.
function advanceSetup(setup, bars, now, step = 60) {
  const s = { ...setup };
  const events = [];
  const buy = s.side === 'buy';
  for (const b of bars) {
    if (!isActive(s)) break;
    if (b.t + step <= s.checked) continue;
    if (b.t + step > now) break;
    if (s.status === 'pending') {
      if (s.expires != null && b.t >= s.expires) {
        events.push(expireSetup(s));
        break;
      }
      const fill = fillOf(s, b);
      if (fill != null) {
        s.status = 'open';
        s.filled = b.t;
        s.fill = fill;
        events.push({ type: 'filled', at: b.t, price: fill });
        if (buy ? b.l <= s.stop : b.h >= s.stop) events.push(settleSetup(s, b.t, s.stop, stopReason(s)));
      }
    } else if (buy ? b.l <= s.stop : b.h >= s.stop) {
      const gapped = buy ? b.o < s.stop : b.o > s.stop;
      events.push(settleSetup(s, b.t, gapped ? b.o : s.stop, stopReason(s)));
    } else if (buy ? b.h >= s.tp : b.l <= s.tp) {
      events.push(settleSetup(s, b.t, s.tp, 'tp'));
    }
    s.checked = b.t + step;
  }
  return { setup: s, events };
}

// A pending order whose time is up while its market was shut, so it can't have filled.
function expireIfDue(setup, now) {
  const s = { ...setup };
  if (s.status !== 'pending' || s.expires == null || s.expires > now) return { setup: s, events: [] };
  return { setup: s, events: [expireSetup(s)] };
}

// By hand: close an open setup at `price`, move its stop, or cancel an order that hasn't filled.
function closeSetup(setup, at, price) {
  const s = { ...setup };
  return { setup: s, events: [settleSetup(s, at, price, 'manual')] };
}
function moveSetupStop(setup, at, price) {
  return { setup: { ...setup, stop: price }, events: [{ type: 'stop', at, price }] };
}
function cancelSetup(setup, at) {
  return { setup: { ...setup, status: 'cancelled', closed: at }, events: [{ type: 'cancelled', at }] };
}

// Where an open setup stands at `price`, in R.
function setupLiveR(s, price) {
  if (s.status !== 'open' || !(price > 0)) return null;
  return (s.side === 'buy' ? price - s.fill : s.fill - price) / Math.abs(s.entry - s.sl);
}

// ----------------------------------------------------------------- the record
const DONE = ['won', 'lost', 'scratch'];
const isResult = (s) => DONE.includes(s.status);

// A result after the assumed round-trip spread.
const netR = (s) => s.r - (PLAYBOOK.spread[s.symbol] || 0) / Math.abs(s.entry - s.sl);

// The 97.5th percentile of Student's t with `df` degrees of freedom: a 95% two-sided band.
const T975 = [12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.16, 2.145, 2.131,
  2.12, 2.11, 2.101, 2.093, 2.086, 2.08, 2.074, 2.069, 2.064, 2.06, 2.056, 2.052, 2.048, 2.045, 2.042];
function t975(df) {
  if (df <= T975.length) return T975[df - 1];
  const z = 1.959964; // beyond the table, the Cornish-Fisher expansion (exact to 3 decimals)
  return z + (z ** 3 + z) / (4 * df) + (5 * z ** 5 + 16 * z ** 3 + 3 * z) / (96 * df * df);
}

// The 95% band for a true average, from `n` results with this mean and sum of squared deviations.
function meanBand(n, mean, ss) {
  if (n < 3) return null;
  const half = t975(n - 1) * Math.sqrt(ss / (n - 1) / n);
  return [mean - half, mean + half];
}

// Wilson's 95% band for a proportion, k of n.
function wilsonBand(k, n) {
  if (!n) return null;
  const z = 1.959964;
  const p = k / n;
  const z2 = z * z;
  const mid = (p + z2 / (2 * n)) / (1 + z2 / n);
  const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / (1 + z2 / n);
  return [Math.max(0, mid - half), Math.min(1, mid + half)];
}

function groupResults(done, keysOf) {
  const groups = new Map();
  for (const s of done) {
    for (const label of keysOf(s)) {
      const key = String(label).toLowerCase();
      const g = groups.get(key) || { key: label, n: 0, sum: 0, won: 0, lost: 0 };
      g.n += 1;
      g.sum += netR(s);
      if (s.status === 'won') g.won += 1;
      if (s.status === 'lost') g.lost += 1;
      groups.set(key, g);
    }
  }
  return [...groups.values()]
    .map((g) => ({ key: g.key, n: g.n, avg: pbRound(g.sum / g.n, 3), won: g.won, lost: g.lost }))
    .sort((a, b) => b.n - a.n || String(a.key).localeCompare(String(b.key)));
}

// The record, from every setup: counts, the average after costs with its band, the
// verdict, the curve of how the average settled as results came in, target-before-stop
// against the no-edge odds, and averages by reason, market and session.
function recordStats(setups) {
  const done = setups.filter(isResult).sort((a, b) => a.closed - b.closed || a.n - b.n);
  const curve = [];
  let n = 0;
  let mean = 0;
  let ss = 0;
  let total = 0;
  let peak = 0;
  let drawdown = 0;
  for (const s of done) {
    const x = netR(s);
    n += 1;
    const d = x - mean;
    mean += d / n;
    ss += d * (x - mean);
    total += x;
    peak = Math.max(peak, total);
    drawdown = Math.max(drawdown, peak - total);
    const band = meanBand(n, mean, ss);
    curve.push({ n: s.n, r: pbRound(x, 3), mean: pbRound(mean, 3), band: band && band.map((v) => pbRound(v, 3)), status: s.status });
  }
  const band = meanBand(n, mean, ss);
  const clean = done.filter((s) => s.reason === 'tp' || s.reason === 'sl');
  const hits = clean.filter((s) => s.reason === 'tp').length;
  const count = (status) => setups.filter((s) => s.status === status).length;
  return {
    setups: setups.length,
    open: count('open'),
    pending: count('pending'),
    results: n,
    won: count('won'),
    lost: count('lost'),
    scratch: count('scratch'),
    avg: n ? pbRound(mean, 3) : null,
    total: pbRound(total, 2),
    band: band && band.map((v) => pbRound(v, 3)),
    drawdown: pbRound(drawdown, 2),
    firstRead: PLAYBOOK.firstRead,
    verdict: n < PLAYBOOK.firstRead || !band ? 'collecting' : band[0] > 0 ? 'ahead' : band[1] < 0 ? 'behind' : 'unclear',
    targetFirst: {
      n: clean.length,
      hits,
      band: wilsonBand(hits, clean.length),
      noEdge: clean.length ? pbRound(clean.reduce((a, s) => a + noEdgeOdds(s), 0) / clean.length, 3) : null,
    },
    byTag: groupResults(done, (s) => s.tags || []),
    byMarket: groupResults(done, (s) => [s.symbol]),
    bySession: groupResults(done, (s) => (s.engine && s.engine.sessions) || []),
    curve,
  };
}

// One line for posts: where the record stands.
function recordLine(st) {
  if (!st || !st.results) return 'The first result starts the record.';
  return `Record: ${st.results} result${st.results === 1 ? '' : 's'} · ${st.won} won · ${st.lost} lost` +
    `${st.scratch ? ` · ${st.scratch} scratch` : ''} · average ${fmtR(st.avg, 2)} after costs`;
}

// TCP Quant Terminal: session briefs, the maths shared by the Worker and the page.
//
// Before each session opens, Lewis sends TCP AI his charts. It reads them and drafts the zones
// to watch and a plan; Lewis checks and edits the draft, and only then does it post. After the
// session, what price did at each zone is measured, and the record says which zones matter:
//   reach  how often price got to a zone, against the engine's odds of it getting there if it
//          moved at random (a zone that draws price in beats them);
//   turn   from the bar that reached a zone, how far price went back the way it came against
//          how far it went on through, in average daily ranges. Both are measured from that
//          bar's close over the same bars, so on a random walk they are equal on average: a zone
//          that holds price back shows a turn above zero.
// Zones are prices Lewis chooses; nothing here says how to find them.

const BRIEF = {
  sessions: [
    { id: 'asia', name: 'Asia', city: 'Tokyo', session: 'tokyo', icon: '🌏' },
    { id: 'london', name: 'London', city: 'London', session: 'london', icon: '🌍' },
    { id: 'newyork', name: 'New York', city: 'New York', session: 'newyork', icon: '🌎' },
  ],
  timeframes: ['5M', '15M', '30M', '1H', '4H'], // asked for before each session
  weekly: '1D', // and the daily chart before the week's first session
  kinds: { demand: 'Demand', supply: 'Supply', liquidity: 'Liquidity', level: 'Level' },
  maxCharts: 6,
  maxZones: 6,
  lead: 45, // minutes before the open that the reminder goes out
  leads: [30, 45, 60],
  late: 3600, // a new brief is for a session that opened this recently, or else the next
  firstRead: 20, // zones reached before the record gives a verdict
  text: { headline: 120, reason: 240, plan: 900, note: 600, label: 40, why: 200, lesson: 400, guide: 6000 },
};

const brRound = (v, d = 2) => (Number.isFinite(v) ? Math.round(v * 10 ** d) / 10 ** d : null);
const briefClip = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const brKey = (z) => `${z.y}-${String(z.m).padStart(2, '0')}-${String(z.d).padStart(2, '0')}`;
const brShift = (key, n) => new Date(Date.parse(key + 'T00:00:00Z') + n * 864e5).toISOString().slice(0, 10);
const brWeekday = (key) => new Date(key + 'T00:00:00Z').getUTCDay(); // 0 Sunday ... 6 Saturday
const briefSession = (id) => BRIEF.sessions.find((s) => s.id === id) || null;

// ------------------------------------------------------------------ schedule
// A session's window on a date never changes, so each is worked out once (the time-zone
// arithmetic is the slow part, and the Worker has 10 ms of CPU a request).
const brKnown = new Map();
function brSessionWindow(s, key) {
  const id = `${s.id}|${key}`;
  let w = brKnown.get(id);
  if (!w) {
    if (brKnown.size > 400) brKnown.clear();
    brKnown.set(id, (w = sessionWindow(s, key)));
  }
  return w;
}

// Each session's windows from yesterday to `days` ahead, Monday to Friday in its own city
// (the terminal's session clock). The week's first is Asia on Monday: its brief also asks
// for the daily chart.
function briefWindows(now, days = 8) {
  const out = [];
  for (const b of BRIEF.sessions) {
    const s = SESSIONS.find((x) => x.id === b.session);
    const today = brKey(zoned(now, s.tz));
    for (let i = -1; i <= days; i++) {
      const key = brShift(today, i);
      const wd = brWeekday(key);
      if (wd === 0 || wd === 6) continue;
      const { from, to } = brSessionWindow(s, key);
      out.push({ id: b.id, name: b.name, key, open: from, close: to, weekly: b.id === 'asia' && wd === 1 });
    }
  }
  return out.sort((a, b) => a.open - b.open);
}

// The session a new brief is for: one that opened in the last hour, or else the next to open.
const briefDefault = (now) => briefWindows(now).find((w) => w.open > now - BRIEF.late) || null;

// A named session's window for a brief made now: the one running, or else the next.
const briefWindow = (id, now) => briefWindows(now).find((w) => w.id === id && w.close > now) || null;

// Sessions whose reminder (`lead` minutes before the open) fell due in the last `span` seconds.
// The check runs every 5 minutes; the Worker keeps each reminder to one send.
function briefReminders(now, lead = BRIEF.lead, span = 900) {
  return briefWindows(now, 2).filter((w) => w.open - lead * 60 <= now && w.open - lead * 60 > now - span);
}

// The charts to ask for before a session.
const briefAsk = (w) => (w && w.weekly ? [...BRIEF.timeframes, BRIEF.weekly] : [...BRIEF.timeframes]);

// --------------------------------------------------------------------- zones
// Checks zones from TCP AI or the poster before they're kept: a known kind, real prices within
// eight average days of the market, low below high (a single price is a level), rounded to the
// market's decimals, no wider than three average days, no repeats, and at most maxZones, the
// nearest to the price. Returns them highest first, with what was dropped and why.
function cleanZones(list, { symbol, price, atr }) {
  const m = MARKETS[symbol];
  const day = Number.isFinite(atr) && atr > 0 ? atr : Number.isFinite(price) ? price * 0.01 : null;
  const zones = [];
  const dropped = [];
  for (const z of Array.isArray(list) ? list : []) {
    if (!z || typeof z !== 'object') continue;
    const num = (v) => (v === null || v === '' || v === undefined ? NaN : Number(String(v).replace(/,/g, '')));
    let low = num(z.low);
    let high = num(z.high);
    if (!Number.isFinite(high)) high = low;
    if (!Number.isFinite(low)) low = high;
    const label = briefClip(z.label, BRIEF.text.label);
    const name = label || `${z.low ?? ''}`;
    if (!Object.hasOwn(BRIEF.kinds, z.kind)) { dropped.push({ zone: name, why: 'unknown kind' }); continue; }
    if (!(low > 0) || !(high > 0)) { dropped.push({ zone: name, why: 'no price' }); continue; }
    if (low > high) [low, high] = [high, low];
    low = brRound(low, m.digits);
    high = brRound(high, m.digits);
    if (day && Number.isFinite(price) && (high < price - 8 * day || low > price + 8 * day)) { dropped.push({ zone: name, why: 'too far from the price' }); continue; }
    if (day && high - low > 3 * day) { dropped.push({ zone: name, why: 'too wide' }); continue; }
    if (zones.some((y) => y.low === low && y.high === high && y.kind === z.kind)) continue;
    zones.push({ kind: z.kind, low, high, tf: briefClip(z.tf ?? z.timeframe, 12), label, why: briefClip(z.why, BRIEF.text.why) });
  }
  if (zones.length > BRIEF.maxZones && Number.isFinite(price)) {
    zones.sort((a, b) => Math.abs(zoneEdge(a, price) - price) - Math.abs(zoneEdge(b, price) - price));
    for (const z of zones.splice(BRIEF.maxZones)) dropped.push({ zone: z.label || String(z.low), why: `more than ${BRIEF.maxZones} zones` });
  }
  zones.splice(BRIEF.maxZones);
  zones.sort((a, b) => b.high - a.high || b.low - a.low);
  return { zones, dropped };
}

// Where a zone sits from `price`: below it, above it, or around it.
const zoneSide = (z, price) => (price > z.high ? 'below' : price < z.low ? 'above' : 'inside');
// The part of a zone price reaches first: its top from above, its bottom from below.
const zoneEdge = (z, price) => (price > z.high ? z.high : price < z.low ? z.low : price);
// The engine's odds of price reaching a zone with `variance` of log price to go, moving at random.
const zoneOdds = (z, price, variance) => (zoneSide(z, price) === 'inside' ? 1 : touchProb(price, zoneEdge(z, price), variance));

// ------------------------------------------------------------------- review
// What price did at a zone after the brief went out. `from` is when it was posted (the bar
// that was forming then is left out: part of it came before), `to` is when the session closed
// (only bars finished by then count). The first bar to reach the zone marks it reached; from
// that bar's close, `away` is the furthest price then went back the way it came and `through`
// the furthest it went on, over the same later bars. `turn` is away less through, in average
// daily ranges. A zone price was already inside when the brief went out is left out.
function reviewZone(z, bars, { from, to, price, atr, step = 60 }) {
  const side = zoneSide(z, price);
  if (side === 'inside') return { side, reached: null };
  let touch = null;
  let away = 0;
  let through = 0;
  for (const b of bars) {
    if (b.t < from) continue;
    if (b.t + step > to) break;
    if (!touch) {
      if (side === 'below' ? b.l <= z.high : b.h >= z.low) touch = { at: b.t, close: b.c };
      continue;
    }
    const c = touch.close;
    if (side === 'below') {
      away = Math.max(away, b.h - c);
      through = Math.max(through, c - b.l);
    } else {
      away = Math.max(away, c - b.l);
      through = Math.max(through, b.h - c);
    }
  }
  if (!touch) return { side, reached: false };
  const digits = 5;
  return {
    side, reached: true, at: touch.at, close: touch.close, away: brRound(away, digits), through: brRound(through, digits),
    turn: atr > 0 ? brRound((away - through) / atr, 3) : null,
  };
}

// Every zone of a brief, reviewed; and the count for the wrap.
function reviewBrief(zones, bars, window) {
  const out = zones.map((z) => ({ ...z, review: reviewZone(z, bars, window) }));
  const counted = out.filter((z) => z.review.reached !== null);
  return {
    zones: out,
    counted: counted.length,
    reached: counted.filter((z) => z.review.reached).length,
    expected: brRound(counted.reduce((a, z) => a + (Number.isFinite(z.odds) ? z.odds : 0), 0), 2),
  };
}

// -------------------------------------------------------------------- record
function brGroup(rows, keyOf) {
  const groups = new Map();
  for (const r of rows) {
    const key = keyOf(r);
    const g = groups.get(key) || { key, zones: 0, reached: 0, expected: 0, turns: [] };
    g.zones += 1;
    g.expected += r.odds;
    if (r.review.reached) {
      g.reached += 1;
      if (r.review.turn != null) g.turns.push(r.review.turn);
    }
    groups.set(key, g);
  }
  return [...groups.values()]
    .map((g) => ({ key: g.key, zones: g.zones, reached: g.reached, expected: brRound(g.expected, 1),
      turn: g.turns.length ? brRound(g.turns.reduce((a, b) => a + b, 0) / g.turns.length, 3) : null, turns: g.turns.length }))
    .sort((a, b) => b.zones - a.zones || String(a.key).localeCompare(String(b.key)));
}

// The record from every reviewed brief that counts (test briefs don't): zones, how many were
// reached against the random walk's expectation, and the average turn with its 95% band. The
// verdict waits for firstRead reached zones: the whole band above zero means zones turned price
// more than chance would, below zero that price went through them more.
function briefStats(briefs) {
  const rows = [];
  let reviewed = 0;
  for (const b of [...briefs].sort((x, y) => (x.posted || 0) - (y.posted || 0))) {
    if (b.test || !b.review) continue;
    reviewed += 1;
    for (const z of b.review.zones || []) {
      if (!z.review || z.review.reached === null || z.review.reached === undefined) continue;
      rows.push({ ...z, odds: Number.isFinite(z.odds) ? z.odds : 0, session: b.session, symbol: b.symbol });
    }
  }
  const reached = rows.filter((r) => r.review.reached);
  const expected = rows.reduce((a, r) => a + r.odds, 0);
  let n = 0;
  let mean = 0;
  let ss = 0;
  const curve = [];
  for (const r of reached) {
    if (r.review.turn == null) continue;
    const x = r.review.turn;
    n += 1;
    const d = x - mean;
    mean += d / n;
    ss += d * (x - mean);
    const band = meanBand(n, mean, ss);
    curve.push({ turn: x, mean: brRound(mean, 3), band: band && band.map((v) => brRound(v, 3)) });
  }
  const band = meanBand(n, mean, ss);
  return {
    briefs: reviewed,
    zones: rows.length,
    reached: reached.length,
    expected: brRound(expected, 1),
    reach: { rate: rows.length ? brRound(reached.length / rows.length, 3) : null, band: wilsonBand(reached.length, rows.length),
      noEdge: rows.length ? brRound(expected / rows.length, 3) : null },
    turn: { n, avg: n ? brRound(mean, 3) : null, band: band && band.map((v) => brRound(v, 3)) },
    firstRead: BRIEF.firstRead,
    verdict: n < BRIEF.firstRead || !band ? 'collecting' : band[0] > 0 ? 'turning' : band[1] < 0 ? 'breaking' : 'unclear',
    byKind: brGroup(rows, (r) => r.kind),
    bySession: brGroup(rows, (r) => r.session),
    curve,
  };
}

const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>TCP Quant Terminal</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<script src=\"https://cdn.jsdelivr.net/npm/lightweight-charts@4.2.3/dist/lightweight-charts.standalone.production.js\" integrity=\"sha384-stKllnUqA9AD0gsKCuUtf5XlqAW7PwIgDagoNsTWkjkBmJ/GZ/uHTgEBxdLV2VSK\" crossorigin=\"anonymous\"></script>\n<style>\n@font-face{font-family:\"Archivo\";src:url(/fonts/archivo-400.woff2) format(\"woff2\");font-weight:400;font-display:swap}\n@font-face{font-family:\"TCP Display\";src:url(/fonts/archivo-expanded-800.woff2) format(\"woff2\");font-weight:800;font-display:swap}\n@font-face{font-family:\"JetBrains Mono\";src:url(/fonts/jetbrains-mono-500.woff2) format(\"woff2\");font-weight:500;font-display:swap}\n@font-face{font-family:\"JetBrains Mono\";src:url(/fonts/jetbrains-mono-600.woff2) format(\"woff2\");font-weight:600;font-display:swap}\n@font-face{font-family:\"Instrument Serif\";src:url(/fonts/instrument-serif-italic.woff2) format(\"woff2\");font-style:italic;font-display:swap}\n:root{\n  --ink:#0E0D0B;--panel:#16140F;--panel-2:#1C1A15;--line:#2E2A22;--line-2:#3A3429;\n  --gold:#D8AD4E;--gold-soft:#E3C06D;--ivory:#F2ECDF;--stone:#A69D8C;--muted:#8A8274;\n  --royal:#8C7BD1;--up:#35A68C;--down:#E0613F;\n  --display:\"TCP Display\",\"Archivo\",system-ui,sans-serif;--sans:\"Archivo\",system-ui,-apple-system,sans-serif;\n  --mono:\"JetBrains Mono\",ui-monospace,monospace;--serif:\"Instrument Serif\",Georgia,serif;\n  --foil:linear-gradient(180deg,#F6E3A3 0%,#D8AD4E 42%,#B0812F 72%,#E3C06D 100%);\n  --foil-x:linear-gradient(90deg,#B0812F 0%,#D8AD4E 45%,#F6E3A3 100%);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--ink);color:var(--ivory)}\nbody{font:400 15px/1.45 var(--sans);min-height:100vh;-webkit-font-smoothing:antialiased;\n  background:radial-gradient(120% 50% at 50% -12%,rgba(216,173,78,.13),transparent 62%),var(--ink);\n  padding-bottom:calc(76px + env(safe-area-inset-bottom))}\nbutton,input,select{font:inherit;color:inherit}\n[hidden]{display:none!important}\n.label{font:500 10.5px/1 var(--mono);letter-spacing:.2em;text-transform:uppercase;color:var(--stone);white-space:nowrap}\n\nheader{display:flex;align-items:center;gap:10px;padding:14px 16px 6px}\nheader svg{width:30px;height:auto;flex:none}\n.brand{display:flex;flex-direction:column;gap:3px}\n.brand b{font:800 17px/1 var(--display);letter-spacing:.02em}\n.brand span{font:600 9.5px/1 var(--mono);letter-spacing:.26em;color:var(--gold)}\n.who{margin-left:auto;display:flex;align-items:center;gap:8px;font-size:13px;color:var(--stone)}\n.avatar{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--panel-2);\n  border:1px solid var(--line-2);font:600 12px/1 var(--mono);color:var(--gold)}\n\n/* ---------------------------------------------------------- engine strip */\n.engine{position:relative;overflow:hidden;display:flex;align-items:center;gap:9px;margin:8px 16px 0;padding:9px 12px;\n  border:1px solid var(--line);border-radius:12px;background:linear-gradient(90deg,rgba(216,173,78,.07),rgba(22,20,15,.6));\n  font:600 10.5px/1 var(--mono);letter-spacing:.16em;color:var(--stone)}\n.engine::after{content:\"\";position:absolute;inset:0;background:linear-gradient(100deg,transparent 30%,rgba(246,227,163,.10) 50%,transparent 70%);\n  transform:translateX(-100%);animation:sweep 3.6s ease-in-out infinite}\n.engine b{color:var(--ivory);font-weight:600}\n.engine .sync{margin-left:auto;letter-spacing:.06em;font-weight:500;color:var(--muted);white-space:nowrap}\n.pulse{width:8px;height:8px;border-radius:50%;background:var(--up);flex:none;box-shadow:0 0 0 0 rgba(53,166,140,.6);animation:pulse 1.8s ease-out infinite}\n.engine.closed .pulse,.engine.delayed .pulse{background:var(--gold);animation:none;box-shadow:none}\n.engine.closed .eq i,.engine.delayed .eq i{animation-play-state:paused}\n.eq{display:inline-flex;align-items:flex-end;gap:2px;height:12px}\n.eq i{width:3px;height:100%;border-radius:1px;background:var(--gold);transform-origin:bottom;animation:eq 1.2s ease-in-out infinite}\n.eq i:nth-child(2){animation-delay:-.3s}.eq i:nth-child(3){animation-delay:-.6s}.eq i:nth-child(4){animation-delay:-.9s}\n@keyframes sweep{to{transform:translateX(100%)}}\n@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(53,166,140,.55)}80%,100%{box-shadow:0 0 0 9px rgba(53,166,140,0)}}\n@keyframes eq{0%,100%{transform:scaleY(.25)}50%{transform:scaleY(1)}}\n\n.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:16px;margin:12px 16px}\n.card h2{margin:0 0 12px}\n.card > .row:first-child{margin-bottom:12px}\n.card .row h2{margin:0}\n.row{display:flex;align-items:center;gap:10px}\n.spread{justify-content:space-between}\n.meta{font-size:12px;color:var(--muted);margin-top:10px}\n.warn{color:var(--gold-soft)}\n.up{color:var(--up)}.down{color:var(--down)}\n\n.segment{display:flex;gap:8px;margin:10px 16px 0}\n.segment button{flex:1;display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:10px 14px;border-radius:14px;\n  background:var(--panel);border:1px solid var(--line);cursor:pointer;text-align:left}\n.segment button b{font:600 14px/1 var(--mono);letter-spacing:.04em}\n.segment button span{font-size:12px;color:var(--stone)}\n.segment button[aria-pressed=\"true\"]{border-color:var(--gold);background:var(--panel-2)}\n.segment button[aria-pressed=\"true\"] b{color:var(--gold)}\n\n.pill{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:999px;border:1px solid var(--line-2);\n  font:500 11.5px/1 var(--mono);color:var(--stone);white-space:nowrap}\n.dot{width:7px;height:7px;border-radius:50%;background:var(--muted)}\n.pill.open .dot{background:var(--up);box-shadow:0 0 0 3px rgba(53,166,140,.18)}\n.pill.open{color:var(--ivory)}\n\n/* ----------------------------------------------------------------- quote */\n.quote{display:grid;grid-template-columns:1fr 112px;gap:8px;align-items:end}\n.price{font:600 36px/1.05 var(--mono);letter-spacing:-.02em;margin:10px 0 6px;border-radius:8px;padding:0 4px;margin-left:-4px;transition:color .5s}\n.price.tick-up{animation:up .7s ease-out}\n.price.tick-down{animation:down .7s ease-out}\n@keyframes up{0%{background:rgba(53,166,140,.28);color:#7FE0C4}100%{background:transparent}}\n@keyframes down{0%{background:rgba(224,97,63,.28);color:#FFB39E}100%{background:transparent}}\n.change{font:500 13.5px/1.2 var(--mono)}\n#spark{width:112px;height:46px;overflow:visible}\n\n/* ----------------------------------------------------------------- chart */\n#chart{height:300px;margin:0 -6px;position:relative}\n.chart-note{position:absolute;inset:0;display:grid;place-items:center;color:var(--muted);font-size:13px;text-align:center;padding:20px}\n.keys{display:flex;flex-wrap:wrap;gap:6px 12px;margin-top:10px;font:500 10.5px/1 var(--mono);color:var(--stone)}\n.keys i{display:inline-block;width:14px;height:0;border-top:2px dashed;vertical-align:middle;margin-right:5px}\n.timer{font:600 11px/1 var(--mono);color:var(--gold-soft);letter-spacing:.06em}\n\n/* ----------------------------------------------------------- probability */\n.bands{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}\n.band{padding:10px 12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line)}\n.band span{display:block;font:500 10px/1 var(--mono);letter-spacing:.16em;color:var(--stone);margin-bottom:7px}\n.band b{display:block;font:600 13.5px/1.5 var(--mono)}\n.band b small{font:500 10px/1 var(--mono);color:var(--muted);margin-right:6px}\n.touched{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}\n.touched .label{width:100%;margin-bottom:2px}\n.touched span:not(.label){padding:4px 9px;border-radius:999px;border:1px solid var(--line-2);font:500 11px/1.2 var(--mono);color:var(--stone)}\n.closed-note{margin:10px 0 2px;font-size:12.5px;color:var(--gold-soft)}\n.lv{padding:10px 0;border-bottom:1px solid var(--line)}\n.lv:last-child{border-bottom:0}\n.lv-top{display:grid;grid-template-columns:1fr auto 70px;gap:10px;align-items:baseline}\n.lv-name{font-size:13.5px}\n.lv-price{font:600 13.5px/1 var(--mono)}\n.lv-dist{font:500 12px/1 var(--mono);font-style:normal;color:var(--muted);text-align:right}\n.lv-odds{display:grid;grid-template-columns:1fr 44px;gap:10px;align-items:center;margin-top:8px}\n.lv-bar{height:6px;border-radius:999px;background:var(--panel-2);overflow:hidden}\n.lv-bar i{display:block;height:100%;width:0;border-radius:999px;background:var(--foil-x);transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.lv.below .lv-bar i{background:linear-gradient(90deg,#6C5BB8,#8C7BD1,#B7AAF0)}\n.lv-pct{font:600 13px/1 var(--mono);text-align:right;color:var(--gold-soft)}\n.lv.below .lv-pct{color:#B7AAF0}\n.hit{display:inline-block;margin-top:8px;padding:3px 8px;border-radius:999px;border:1px solid var(--line-2);font:500 10.5px/1.2 var(--mono);color:var(--muted);letter-spacing:.06em}\n.lv.now{border:1px solid rgba(216,173,78,.5);border-radius:12px;padding:10px 12px;margin:6px -8px;background:rgba(216,173,78,.07);\n  display:flex;justify-content:space-between;align-items:center}\n.lv.now span{font-size:13.5px;color:var(--gold)}\n.lv.now b{font:600 14px/1 var(--mono);color:var(--gold)}\n.fine{font-size:12px;color:var(--muted);margin-top:12px;line-height:1.5}\n\n/* ----------------------------------------------------------------- gauges */\n.gauge{position:relative;height:10px;border-radius:999px;background:var(--panel-2);border:1px solid var(--line);margin:14px 0 8px}\n.gauge .fill{position:absolute;inset:0 auto 0 0;border-radius:999px;background:var(--foil);transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.gauge .avg{position:absolute;top:-5px;bottom:-5px;width:2px;background:var(--ivory);opacity:.7}\n.gauge-scale{position:relative;height:12px;font:500 10px/1 var(--mono);color:var(--muted)}\n.gauge-scale span{position:absolute;top:0}\n.gauge-scale span:nth-child(2){left:66.6%;transform:translateX(-50%)}\n.gauge-scale span:last-child{right:0}\n.big{font:600 26px/1.1 var(--mono)}\n.sub{color:var(--stone);font-size:13.5px}\n.meter{margin-bottom:16px}\n.meter:last-child{margin-bottom:0}\n.meter .row{justify-content:space-between;align-items:baseline}\n.meter b{font:600 14px/1 var(--mono)}\n.meter small{font-size:12.5px;color:var(--stone)}\n.track{position:relative;height:8px;border-radius:999px;background:var(--panel-2);border:1px solid var(--line);margin-top:9px;overflow:hidden}\n.track i{position:absolute;top:0;bottom:0;left:0;border-radius:999px;background:var(--foil-x);transition:width .8s cubic-bezier(.2,.8,.2,1),left .8s cubic-bezier(.2,.8,.2,1)}\n.track.mid::before{content:\"\";position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--line-2);z-index:1}\n.mom{display:grid;grid-template-columns:34px 1fr 58px;gap:10px;align-items:center;margin-top:8px}\n.mom span{font:500 11px/1 var(--mono);color:var(--stone)}\n.mom em{font:600 12px/1 var(--mono);font-style:normal;text-align:right}\n.mom .track{margin-top:0}\n.mom .track i.pos{background:linear-gradient(90deg,rgba(53,166,140,.5),#35A68C)}\n.mom .track i.neg{background:linear-gradient(90deg,#E0613F,rgba(224,97,63,.5))}\n.tag{flex-shrink:0;white-space:nowrap;font:500 10.5px/1 var(--mono);letter-spacing:.1em;color:var(--muted);border:1px solid var(--line-2);border-radius:999px;padding:4px 8px}\n\n/* --------------------------------------------------------------- sessions */\n.sessions{display:grid;gap:8px}\n.session{position:relative;overflow:hidden;display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line)}\n.session .code{font:600 11px/1 var(--mono);letter-spacing:.12em;color:var(--stone)}\n.session.open{border-color:rgba(53,166,140,.45)}\n.session.open .code{color:var(--up)}\n.session b{font-weight:600;font-size:14px}\n.session small{display:block;color:var(--stone);font-size:12px;margin-top:2px;font-variant-numeric:tabular-nums}\n.session time{font:500 12px/1 var(--mono);color:var(--muted)}\n.session .prog{position:absolute;left:0;bottom:0;height:2px;background:linear-gradient(90deg,rgba(53,166,140,.2),#35A68C);transition:width 1s linear}\n.overlap{margin-top:10px;font-size:12.5px;color:var(--gold-soft)}\n\n/* ------------------------------------------------------------ model check */\n#checkChart{width:100%;height:auto;display:block;margin:4px 0 6px}\n.check-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}\n.check-stats div{padding:10px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);text-align:center}\n.check-stats b{display:block;font:600 16px/1.1 var(--mono);color:var(--gold-soft)}\n.check-stats span{font-size:11px;color:var(--stone)}\n\n/* -------------------------------------------------------------------- risk */\n.field{display:grid;gap:6px;margin-bottom:14px}\n.field label{font:500 10.5px/1 var(--mono);letter-spacing:.18em;text-transform:uppercase;color:var(--stone)}\n.inputs{display:flex;gap:8px}\ninput,select{width:100%;min-width:0;background:var(--panel-2);border:1px solid var(--line-2);border-radius:12px;padding:12px 12px;\n  font:500 16px/1.2 var(--mono);outline:none}\nselect{appearance:none;-webkit-appearance:none;width:auto;min-width:96px;flex:none;padding-right:34px;background-image:linear-gradient(45deg,transparent 50%,var(--stone) 50%),linear-gradient(135deg,var(--stone) 50%,transparent 50%);\n  background-position:calc(100% - 15px) 55%,calc(100% - 10px) 55%;background-size:5px 5px;background-repeat:no-repeat}\ninput:focus,select:focus{border-color:var(--gold)}\n.chips{display:flex;gap:6px}\n.chips button{padding:8px 12px;border-radius:999px;border:1px solid var(--line-2);background:transparent;font:500 13px/1 var(--mono);cursor:pointer}\n.chips button[aria-pressed=\"true\"]{border-color:var(--gold);color:var(--gold)}\n.hint{font-size:12px;color:var(--muted)}\n.link{background:none;border:0;padding:0;color:var(--gold);font-size:12.5px;cursor:pointer}\n.result{text-align:center;padding:22px 16px}\n.lots{font:800 46px/1 var(--display);background:var(--foil);-webkit-background-clip:text;background-clip:text;color:transparent;margin:8px 0 4px}\n.facts{display:grid;gap:8px;margin-top:16px;text-align:left}\n.facts div{display:flex;justify-content:space-between;gap:10px;font-size:13.5px;color:var(--stone)}\n.facts b{font:600 13.5px/1.3 var(--mono);color:var(--ivory)}\n#targets{width:100%;border-collapse:collapse;margin-top:14px;font:500 13px/1 var(--mono)}\n#targets th{font:500 10px/1 var(--mono);letter-spacing:.16em;color:var(--muted);text-align:left;padding:0 0 8px}\n#targets td{padding:9px 0;border-top:1px solid var(--line);text-align:left}\n#targets td:last-child,#targets th:last-child{text-align:right}\n.odds-note{margin-top:14px;text-align:left;font-size:12.5px;color:var(--stone);line-height:1.5}\n.odds-note b{color:var(--gold-soft);font-family:var(--mono);font-weight:600}\n.note{font-size:12px;color:var(--muted);margin:14px 16px 0;text-align:center}\n\n.soon h2{font:800 20px/1.15 var(--display);margin:6px 0 8px}\n.soon p{color:var(--stone);margin:0 0 12px}\n.soon ul{margin:0;padding:0;list-style:none;display:grid;gap:8px}\n.soon li{display:flex;gap:10px;align-items:baseline;font-size:14px}\n.soon li:before{content:\"\";width:6px;height:6px;border-radius:2px;background:var(--gold);transform:translateY(-2px);flex:none}\n.serif{font:italic 400 19px/1.2 var(--serif);color:var(--gold-soft)}\n\nnav{position:fixed;left:0;right:0;bottom:0;display:grid;grid-template-columns:repeat(5,1fr);padding:8px 8px calc(8px + env(safe-area-inset-bottom));\n  background:rgba(14,13,11,.92);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-top:1px solid var(--line);z-index:4}\nnav button{display:grid;justify-items:center;gap:4px;padding:6px 0;background:none;border:0;color:var(--muted);font:500 10.5px/1 var(--mono);letter-spacing:.08em;cursor:pointer}\nnav svg{width:22px;height:22px}\nnav button[aria-current=\"page\"]{color:var(--gold)}\n\n.gate{position:fixed;inset:0;display:grid;place-items:center;padding:32px;text-align:center;background:var(--ink);z-index:5}\n.gate svg{width:64px;margin-bottom:18px}\n.gate h1{font:800 22px/1.15 var(--display);margin:0 0 10px}\n.gate p{color:var(--stone);margin:0 0 20px}\n.cta{display:inline-block;padding:13px 20px;border-radius:14px;background:var(--foil);color:var(--ink);font:600 14px/1 var(--mono);letter-spacing:.06em;text-decoration:none;border:0;cursor:pointer}\n.skeleton{border-radius:8px;background:linear-gradient(90deg,var(--panel-2),#24211A,var(--panel-2));background-size:200% 100%;animation:shimmer 1.4s infinite}\n@keyframes shimmer{to{background-position:-200% 0}}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}\n\n/* ------------------------------------------------------------- briefing */\n.brief p{margin:0;font-size:14.5px;line-height:1.6;color:var(--ivory)}\n.brief p b{font-family:var(--mono);font-weight:600;color:var(--gold-soft);white-space:nowrap}\n.testing{margin-top:10px;padding:9px 12px;border-radius:12px;border:1px solid rgba(216,173,78,.55);background:rgba(216,173,78,.08);\n  font:500 12.5px/1.35 var(--mono);color:var(--gold-soft);animation:glow 1.6s ease-in-out infinite}\n@keyframes glow{0%,100%{box-shadow:0 0 0 0 rgba(216,173,78,0)}50%{box-shadow:0 0 0 4px rgba(216,173,78,.12)}}\n\n/* ----------------------------------------------------------------- swarm */\n#swarm{display:block;width:100%;height:270px;border-radius:12px;background:radial-gradient(90% 80% at 0% 50%,rgba(216,173,78,.08),transparent 60%),#12110D;\n  border:1px solid var(--line);cursor:pointer;touch-action:manipulation}\n.swarm-legend{display:grid;gap:6px;margin-top:12px}\n.swarm-legend div{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:baseline;font-size:12.5px;color:var(--stone)}\n.swarm-legend b{font:600 12.5px/1 var(--mono);color:var(--ivory);min-width:44px;text-align:right}\n.swarm-legend em{font:500 11px/1 var(--mono);font-style:normal;color:var(--muted);min-width:88px;text-align:right}\n.swarm-legend .above b{color:var(--gold-soft)}\n.swarm-legend .below b{color:#B7AAF0}\n\n/* --------------------------------------------------------- volatility clock */\n.vclock{margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}\n#vclock{display:block;width:100%;height:96px;margin-top:10px}\n\n/* ---------------------------------------------------------- coming soon */\n.state{display:inline-flex;align-items:center;gap:6px;padding:4px 9px;border-radius:999px;font:600 10px/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;white-space:nowrap;border:1px solid}\n.state.testing{color:var(--gold-soft);border-color:rgba(216,173,78,.45);background:rgba(216,173,78,.07)}\n.state.soon-tag{color:#B7AAF0;border-color:rgba(140,123,209,.5);background:rgba(140,123,209,.1)}\n.soon-card p,.feature p{margin:0;color:var(--stone);font-size:14px;line-height:1.5}\n.notify{margin-top:14px;width:100%;padding:12px;border-radius:12px;border:1px solid rgba(216,173,78,.55);background:rgba(216,173,78,.08);\n  color:var(--gold-soft);font:600 12.5px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase;cursor:pointer}\n.notify[disabled]{border-color:rgba(53,166,140,.5);background:rgba(53,166,140,.08);color:var(--up);cursor:default}\n\n/* -------------------------------------------------------------- pipeline */\n.pipe{display:grid;gap:0}\n.node{display:grid;grid-template-columns:38px 1fr;gap:12px;align-items:start;padding:12px;border-radius:14px;background:var(--panel-2);border:1px solid var(--line)}\n.node .state{grid-column:2;justify-self:start;margin-top:8px}\n.node b{display:block;font-size:14.5px}\n.node small{display:block;color:var(--stone);font-size:12.5px;line-height:1.45;margin-top:3px}\n.node-icon{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:rgba(216,173,78,.1);color:var(--gold)}\n.node-icon svg{width:20px;height:20px}\n.flow{position:relative;height:30px;margin-left:30px;width:2px;background:linear-gradient(var(--line-2),var(--line-2))}\n.flow i{position:absolute;left:-2px;top:0;width:6px;height:6px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px rgba(216,173,78,.8);animation:drip 1.8s linear infinite;opacity:0}\n.flow i:nth-child(2){animation-delay:.6s}.flow i:nth-child(3){animation-delay:1.2s}\n@keyframes drip{0%{top:-4px;opacity:0}15%{opacity:1}85%{opacity:1}100%{top:28px;opacity:0}}\n\n/* -------------------------------------------------------- example signal */\n.sig{position:relative;overflow:hidden;padding:14px;border-radius:14px;border:1px dashed var(--line-2);background:var(--panel-2)}\n.sig-top{display:flex;align-items:center;gap:10px}\n.sig-top b{font:600 15px/1 var(--mono)}\n.sig-side{padding:4px 9px;border-radius:8px;background:rgba(53,166,140,.15);color:var(--up);font:700 11px/1 var(--mono);letter-spacing:.1em}\n.sig-time{margin-left:auto;font:500 11px/1 var(--mono);color:var(--muted)}\n.sig-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}\n.sig-grid span,.sig-foot span{display:block;font:500 10px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:5px}\n.sig-grid b{font:600 15px/1 var(--mono)}\n.sig-foot{display:flex;justify-content:space-between;gap:10px;margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}\n.sig-foot b{display:block;margin-top:4px;font:600 13px/1 var(--mono);color:var(--gold-soft);letter-spacing:0;text-transform:none}\n.watermark{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-14deg);pointer-events:none;white-space:nowrap;font:800 46px/1 var(--display);letter-spacing:.12em;color:rgba(183,170,240,.09)}\n\n/* -------------------------------------------------------------------- AI */\n.ai-hero{padding:0;overflow:hidden;position:relative}\n#orb{display:block;width:100%;height:230px}\n.ai-copy{padding:0 18px 18px;margin-top:-18px;position:relative}\n.ai-copy h2{font:800 26px/1.1 var(--display);margin:10px 0 8px}\n.ai-copy p{margin:0;color:var(--stone)}\n.feature{display:grid;grid-template-columns:1fr auto;gap:4px 12px;padding:12px 0;border-bottom:1px solid var(--line)}\n.feature:last-child{border-bottom:0}\n.feature b{font-size:14.5px}\n.feature p{grid-column:1}\n.feature .state{grid-column:2;grid-row:1}\n\n/* --------------------------------------------------------------- account */\n.profile{display:flex;align-items:center;gap:14px}\n.big-avatar{width:48px;height:48px;font-size:18px}\n.profile b{display:block;font-size:17px}\n.profile small{display:block;color:var(--stone);font-size:13px;margin-top:2px}\n.stat-preview{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.stat-preview div{padding:12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line)}\n.stat-preview span{display:block;font:500 10px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.stat-preview b{display:block;margin-top:8px;font:600 20px/1 var(--mono);color:var(--line-2)}\n\n/* -------------------------------------------------------------- playbook */\n.pb-lede{margin:0 0 14px;color:var(--stone);font-size:14px;line-height:1.5}\n.pb-lede b{color:var(--ivory);font-weight:600}\n.pb-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}\n.pb-stats div{padding:10px 8px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);min-width:0}\n.pb-stats span{display:block;font:500 9.5px/1 var(--mono);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);white-space:nowrap}\n.pb-stats b{display:block;margin-top:8px;font:600 15px/1 var(--mono);white-space:nowrap}\n.pb-chart{position:relative;margin:14px 0 6px}\n#pbCurve{display:block;width:100%;height:184px;touch-action:pan-y}\n.pb-tip{position:absolute;top:6px;min-width:148px;padding:8px 10px;border-radius:10px;background:rgba(28,26,21,.96);border:1px solid var(--line-2);\n  font:500 11.5px/1.45 var(--mono);color:var(--stone);pointer-events:none;box-shadow:0 6px 20px rgba(0,0,0,.4)}\n.pb-tip b{color:var(--ivory);font-weight:600}\n.pb-tip .k{display:inline-block;width:12px;height:0;border-top:2px solid var(--gold);vertical-align:middle;margin-right:6px}\n.pb-legend{display:flex;flex-wrap:wrap;gap:6px 14px;font:500 10.5px/1 var(--mono);color:var(--stone)}\n.pb-legend span{display:inline-flex;align-items:center;gap:6px}\n.pb-legend i{display:inline-block;flex:none}\n.pb-legend .k-line{width:14px;height:0;border-top:2px solid var(--gold)}\n.pb-legend .k-band{width:14px;height:10px;border-radius:2px;background:rgba(216,173,78,.2)}\n.pb-legend .k-won{width:8px;height:8px;border-radius:50%;background:var(--up)}\n.pb-legend .k-lost{width:8px;height:8px;border-radius:50%;border:2px solid var(--down)}\n.pb-verdict{display:grid;grid-template-columns:26px 1fr;gap:10px;align-items:start;margin-top:14px;padding:12px;border-radius:14px;border:1px solid var(--line-2);background:var(--panel-2);font-size:13.5px;line-height:1.45}\n.pb-verdict .icon{width:26px;height:26px;border-radius:8px;display:grid;place-items:center;font:700 13px/1 var(--mono);background:rgba(216,173,78,.12);color:var(--gold)}\n.pb-verdict b{display:block;font:600 12px/1.2 var(--mono);letter-spacing:.08em;text-transform:uppercase;margin-bottom:4px}\n.pb-verdict span{color:var(--stone)}\n.pb-verdict.ahead{border-color:rgba(53,166,140,.5)}.pb-verdict.ahead .icon{background:rgba(53,166,140,.14);color:var(--up)}\n.pb-verdict.behind{border-color:rgba(224,97,63,.5)}.pb-verdict.behind .icon{background:rgba(224,97,63,.14);color:var(--down)}\n.pb-verdict.collecting{border-color:rgba(216,173,78,.4)}\n.pb-progress{grid-column:2;height:6px;border-radius:999px;background:var(--ink);border:1px solid var(--line);overflow:hidden;margin-top:6px}\n.pb-progress i{display:block;height:100%;background:var(--foil-x);border-radius:999px;transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.pb-first{margin:10px 0 0;font-size:12.5px;color:var(--stone)}\n.pb-first b{font-family:var(--mono);font-weight:600;color:var(--ivory)}\n.pb-empty{margin:4px 0 0;padding:14px;border-radius:12px;border:1px dashed var(--line-2);color:var(--stone);font-size:13.5px;line-height:1.5;text-align:center}\n\n.pb-setup{position:relative;overflow:hidden}\n.pb-setup.test{border-style:dashed}\n.pb-setup .sig-top{flex-wrap:wrap;row-gap:8px}\n.sig-side.sell{background:rgba(224,97,63,.15);color:var(--down)}\n.pb-state{padding:4px 8px;border-radius:999px;border:1px solid var(--line-2);font:600 9.5px/1 var(--mono);letter-spacing:.1em;color:var(--stone)}\n.pb-state.open{border-color:rgba(53,166,140,.55);color:var(--up)}\n.pb-state.open::before{content:\"\";display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--up);margin-right:6px;vertical-align:1px;animation:pulse 1.8s ease-out infinite}\n.pb-state.pending{border-color:rgba(216,173,78,.5);color:var(--gold-soft)}\n.pb-state.test{border-color:rgba(140,123,209,.5);color:#B7AAF0}\n.pb-setup .sig-grid b small{font:500 10.5px/1 var(--mono);color:var(--muted);margin-left:4px}\n.pb-now{transition:color .3s}\n.pb-track{position:relative;height:28px;margin:16px 0 4px}\n.pb-track .rail{position:absolute;left:0;right:0;top:12px;height:4px;border-radius:999px;background:linear-gradient(90deg,rgba(224,97,63,.55),rgba(46,42,34,.9) 40%,rgba(46,42,34,.9) 60%,rgba(53,166,140,.55))}\n.pb-track .mark{position:absolute;top:6px;width:2px;height:16px;background:var(--ivory);opacity:.6;transform:translateX(-1px)}\n.pb-track .dot{position:absolute;top:8px;width:12px;height:12px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 2px var(--panel),0 0 12px rgba(216,173,78,.7);transform:translateX(-6px);transition:left .6s cubic-bezier(.2,.8,.2,1)}\n.pb-track .ends{position:absolute;left:0;right:0;top:-4px;display:flex;justify-content:space-between;font:500 9.5px/1 var(--mono);letter-spacing:.1em;color:var(--muted)}\n.pb-why{margin:12px 0 0;font-size:14px;line-height:1.5}\n.pb-why b{font:600 10.5px/1 var(--mono);letter-spacing:.14em;color:var(--stone);margin-right:6px}\n.pb-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}\n.pb-tags span{padding:4px 9px;border-radius:999px;border:1px solid var(--line-2);font:500 11px/1.2 var(--mono);color:var(--gold-soft)}\n.pb-meta{margin-top:10px;font:500 11px/1.5 var(--mono);color:var(--muted)}\n.pb-buttons{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}\n.pb-buttons button{flex:1 1 auto;padding:10px 12px;border-radius:12px;border:1px solid var(--line-2);background:transparent;font:600 11.5px/1 var(--mono);letter-spacing:.08em;cursor:pointer}\n.pb-buttons button.gold{border-color:rgba(216,173,78,.55);color:var(--gold-soft);background:rgba(216,173,78,.07)}\n.pb-buttons button[disabled]{opacity:.5;cursor:default}\n.pb-stoprow{display:flex;gap:8px;margin-top:10px}\n.pb-stoprow input{flex:1}\n.pb-stoprow button{flex:none;padding:0 16px;border-radius:12px;border:1px solid rgba(216,173,78,.55);background:rgba(216,173,78,.1);color:var(--gold-soft);font:600 12px/1 var(--mono);letter-spacing:.08em;cursor:pointer}\n\n.pb-row{display:grid;grid-template-columns:40px 1fr auto;gap:10px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line);cursor:pointer}\n.pb-row:last-of-type{border-bottom:0}\n.pb-row .n{font:600 11.5px/1 var(--mono);color:var(--muted)}\n.pb-row .what{font:600 13px/1.2 var(--mono)}\n.pb-row .what small{display:block;margin-top:4px;font:500 11px/1.3 var(--sans);color:var(--stone)}\n.pb-row .r{font:600 14px/1 var(--mono);text-align:right}\n.pb-row .r small{display:block;margin-top:4px;font:500 10px/1 var(--mono);letter-spacing:.08em;color:var(--muted);text-transform:uppercase}\n.pb-row.won .r{color:var(--up)}.pb-row.lost .r{color:var(--down)}\n.pb-row.void .what,.pb-row.void .r{color:var(--muted)}\n.pb-detail{padding:0 0 12px 50px;border-bottom:1px solid var(--line)}\n.pb-detail .pb-why{margin-top:0}\n.pb-more{display:block;width:100%;margin-top:10px;padding:10px;border-radius:12px;border:1px solid var(--line-2);background:transparent;font:600 11.5px/1 var(--mono);letter-spacing:.1em;color:var(--stone);cursor:pointer}\n\n.pb-read{display:grid;grid-template-columns:1fr 70px 64px;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line);font-size:13px}\n.pb-read:last-child{border-bottom:0}\n.pb-read small{color:var(--muted);font:500 11px/1 var(--mono)}\n.pb-read .bar{position:relative;height:6px;border-radius:999px;background:var(--panel-2)}\n.pb-read .bar::before{content:\"\";position:absolute;left:50%;top:-3px;bottom:-3px;width:1px;background:var(--line-2)}\n.pb-read .bar i{position:absolute;top:0;bottom:0;border-radius:999px}\n.pb-read b{font:600 12.5px/1 var(--mono);text-align:right}\n\n.pb-fab{position:fixed;right:16px;bottom:calc(80px + env(safe-area-inset-bottom));z-index:4;padding:13px 18px;border-radius:999px;border:0;background:var(--foil);color:var(--ink);\n  font:700 12.5px/1 var(--mono);letter-spacing:.1em;cursor:pointer;box-shadow:0 10px 30px rgba(0,0,0,.5),0 0 0 1px rgba(246,227,163,.4)}\n\n.sheet{position:fixed;inset:0;z-index:6;display:flex;align-items:flex-end;background:rgba(6,5,4,.66);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px)}\n.sheet-body{width:100%;max-height:92vh;overflow:auto;padding:18px 16px calc(22px + env(safe-area-inset-bottom));border-radius:22px 22px 0 0;\n  background:var(--panel);border-top:1px solid var(--line-2);animation:rise .28s cubic-bezier(.2,.8,.2,1)}\n@keyframes rise{from{transform:translateY(40px);opacity:0}}\n.sheet-head{margin-bottom:14px}\n.sheet-head h2{margin:0;font:800 19px/1.1 var(--display)}\n.sheet .chips{flex-wrap:wrap}\n.pb-prices{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.pb-prices .field{margin-bottom:10px}\n.pb-prices input{padding:11px 9px;font-size:15px}\n.pb-plan{margin:0 0 14px;padding:10px 12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);font:500 12.5px/1.5 var(--mono);color:var(--stone)}\n.pb-plan b{color:var(--ivory);font-weight:600}\ntextarea{width:100%;min-width:0;resize:vertical;background:var(--panel-2);border:1px solid var(--line-2);border-radius:12px;padding:12px;font:400 15px/1.45 var(--sans);color:inherit;outline:none}\ntextarea:focus{border-color:var(--gold)}\n.tagpick{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}\n.tagpick button{padding:8px 11px;border-radius:999px;border:1px solid var(--line-2);background:transparent;font:500 12px/1 var(--mono);cursor:pointer;color:var(--stone)}\n.tagpick button[aria-pressed=\"true\"]{border-color:var(--gold);color:var(--gold);background:rgba(216,173,78,.08)}\n.field .pb-photo{display:grid;place-items:center;gap:10px;min-height:64px;padding:12px;border-radius:12px;border:1px dashed var(--line-2);color:var(--stone);\n  font:400 13.5px/1.4 var(--sans);letter-spacing:normal;text-transform:none;cursor:pointer;text-align:center}\nbody.with-fab main{padding-bottom:64px}\n.pb-photo img{max-width:100%;max-height:180px;border-radius:8px}\n.pb-error{margin:0 0 12px;padding:10px 12px;border-radius:12px;border:1px solid rgba(224,97,63,.55);background:rgba(224,97,63,.08);color:#FFB39E;font-size:13.5px}\n.pb-submit{width:100%;padding:15px}\n.pb-submit[disabled]{opacity:.6;cursor:default}\n\n.viewer{position:fixed;inset:0;z-index:7;display:grid;place-items:center;gap:12px;padding:20px;background:rgba(0,0,0,.92)}\n.viewer img{max-width:100%;max-height:82vh;border-radius:10px}\n.toast{position:fixed;left:16px;right:16px;top:calc(12px + env(safe-area-inset-top));z-index:8;padding:12px 14px;border-radius:14px;background:rgba(28,26,21,.97);\n  border:1px solid rgba(216,173,78,.5);font-size:13.5px;box-shadow:0 10px 30px rgba(0,0,0,.45);animation:rise .25s ease-out}\n\n.ai-memory .mem-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:12px}\n.ai-memory .mem-grid div{padding:12px 8px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);text-align:center}\n.ai-memory .mem-grid b{display:block;font:600 22px/1 var(--mono);background:var(--foil);-webkit-background-clip:text;background-clip:text;color:transparent}\n.ai-memory .mem-grid span{display:block;margin-top:6px;font-size:11.5px;color:var(--stone)}\n.ai-memory p{margin:0;color:var(--stone);font-size:14px;line-height:1.5}\n\n/* ------------------------------------------------------------ session briefs */\n.state.live{color:var(--up);border-color:rgba(53,166,140,.5);background:rgba(53,166,140,.08)}\n.ai-copy .state{margin-bottom:2px}\n.card-empty{margin:12px 16px}\n.feature-list .notify{margin-top:12px}\n.br-nextrow{display:flex;align-items:center;gap:12px}\n.br-icon{font-size:22px;line-height:1}\n.br-nextrow b{display:block;font:800 18px/1.1 var(--display)}\n.br-nextrow small{display:block;margin-top:5px;font:500 12px/1 var(--mono);color:var(--stone)}\n.br-ask,.br-askline{margin:12px 0 0;font-size:13px;line-height:1.7;color:var(--stone)}\n.br-askline{margin:0}\n.br-ask b,.br-askline b{display:inline-block;margin:0 2px;padding:3px 7px;border-radius:999px;border:1px solid var(--line-2);font:600 11px/1 var(--mono);color:var(--gold-soft)}\n.br-card.test,.br-card.draft{border-style:dashed}\n.br-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap;row-gap:8px}\n.br-top b{font:800 16px/1 var(--display)}\n.br-sym{font:600 11px/1 var(--mono);letter-spacing:.08em;color:var(--stone)}\n.br-top .pb-state:nth-of-type(3){margin-left:auto}\n.br-headline{margin:14px 0 8px;font:600 17px/1.3 var(--sans)}\n.br-reason{margin:0;color:var(--stone);font-size:14px;line-height:1.5}\n.br-card.draft .br-reason{margin-top:12px}\n.br-bias{display:inline-block;margin-right:8px;padding:3px 7px;border-radius:6px;border:1px solid var(--line-2);font:700 10.5px/1.2 var(--mono);letter-spacing:.1em;vertical-align:1px}\n.br-bias.long{color:var(--up);border-color:rgba(53,166,140,.5)}\n.br-bias.short{color:var(--down);border-color:rgba(224,97,63,.5)}\n.br-bias.neutral{color:var(--gold-soft);border-color:rgba(216,173,78,.45)}\n.br-zones{margin-top:14px;border-top:1px solid var(--line)}\n.br-zone{display:grid;grid-template-columns:4px 1fr auto;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}\n.br-zone i{align-self:stretch;border-radius:2px;background:var(--stone)}\n.br-zone.demand i{background:var(--up)}.br-zone.supply i{background:var(--down)}.br-zone.liquidity i{background:var(--gold)}\n.br-zone b{display:block;font:600 14px/1.2 var(--mono)}\n.br-zone span{display:block;margin-top:3px;font-size:12.5px;line-height:1.35;color:var(--stone)}\n.br-zone em{max-width:118px;font:500 11.5px/1.3 var(--mono);font-style:normal;color:var(--stone);text-align:right}\n.br-zone em.br-hit{color:var(--up)}.br-zone em.br-miss{color:var(--muted)}\n.br-plan{margin-top:14px}\n.br-plan b{font:600 10.5px/1 var(--mono);letter-spacing:.14em;color:var(--stone)}\n.br-plan ul{margin:8px 0 0;padding-left:18px;font-size:14px;line-height:1.5}\n.br-plan li+li{margin-top:4px}\n.br-wrap{margin-top:12px;padding:10px 12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);font-size:13px;color:var(--stone)}\n.br-wrap b{color:var(--ivory);font-family:var(--mono);font-weight:600}\n.br-inline{padding-top:4px}\n.br-row .n{font-size:17px}\n.br-thumbs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.br-thumbs:empty{display:none}\n.br-thumbs figure{position:relative;margin:0;aspect-ratio:4/3;border-radius:10px;overflow:hidden;border:1px solid var(--line-2);background:var(--panel-2)}\n.br-thumbs img{width:100%;height:100%;object-fit:cover;display:block}\n.br-thumbs button{position:absolute;top:4px;right:4px;width:26px;height:26px;border-radius:50%;border:0;background:rgba(14,13,11,.82);color:var(--ivory);font:600 15px/1 var(--mono);cursor:pointer}\n.br-thumbs figcaption{position:absolute;left:6px;bottom:4px;font:600 11px/1 var(--mono);color:var(--ivory);text-shadow:0 1px 3px #000}\n.br-reading{display:grid;justify-items:center;gap:12px;padding:28px 0 8px;text-align:center}\n.br-reading b{font:600 15px/1.3 var(--sans)}\n.br-scan{position:relative;width:168px;height:112px;border-radius:14px;border:1px solid var(--line-2);overflow:hidden;\n  background:repeating-linear-gradient(90deg,transparent 0 22px,rgba(58,52,41,.35) 22px 23px),linear-gradient(180deg,rgba(216,173,78,.07),rgba(22,20,15,.4))}\n.br-scan i{position:absolute;left:0;right:0;top:8%;height:2px;background:var(--foil-x);box-shadow:0 0 16px rgba(216,173,78,.8);animation:scan 1.8s ease-in-out infinite alternate}\n@keyframes scan{to{top:90%}}\n.br-elapsed{font:600 13px/1 var(--mono);color:var(--gold)}\n.br-failed{margin-bottom:14px;padding:12px;border-radius:12px;border:1px solid rgba(224,97,63,.55);background:rgba(224,97,63,.08)}\n.br-failed p{margin:0;color:#FFB39E;font-size:13.5px}\n.br-warnings{margin-bottom:14px;padding:10px 12px;border-radius:12px;border:1px solid rgba(216,173,78,.5);background:rgba(216,173,78,.07);font-size:13px;line-height:1.5;color:var(--gold-soft)}\n.br-readcard{margin-bottom:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel-2)}\n.br-readcard summary{padding:12px;font:600 11px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--stone);cursor:pointer}\n.br-readcard > div{padding:0 12px 12px}\n.br-readrow{display:grid;grid-template-columns:auto 1fr;gap:4px 10px;padding:8px 0;border-top:1px solid var(--line);font-size:12.5px;line-height:1.45}\n.br-readrow b{font:600 11.5px/1.45 var(--mono);white-space:nowrap}\n.br-readrow span{color:var(--stone)}\n.br-panel{margin:6px 0;padding:8px 10px;border-radius:10px;background:var(--ink);font:500 11px/1.6 var(--mono)}\n.br-panel div{display:flex;justify-content:space-between;gap:10px}\n.br-panel span{color:var(--muted)}\n.br-panel b{font-weight:500;text-align:right}\n.br-zrow{display:grid;grid-template-columns:1.1fr 1fr 1fr 34px;gap:6px;padding:10px 0;border-bottom:1px solid var(--line)}\n.br-zrow:first-child{padding-top:0}\n.br-zrow input{padding:10px 7px}\n.br-zrow select{width:100%;min-width:0;padding:10px 24px 10px 8px;font-size:14px;background-position:calc(100% - 13px) 55%,calc(100% - 8px) 55%}\n.br-zrow [data-f=\"label\"]{grid-column:1 / 3;font-family:var(--sans);font-size:16px}\n.br-zrow [data-f=\"why\"]{grid-column:3 / 5;font-family:var(--sans);font-size:16px}\n.br-zrow small{grid-column:1 / -1;font:500 11px/1.3 var(--mono);color:var(--muted)}\n.br-zrow small:empty{display:none}\n.br-zrow.demand select{color:var(--up)}.br-zrow.supply select{color:var(--down)}.br-zrow.liquidity select{color:var(--gold)}\n.br-x{border:1px solid var(--line-2);border-radius:10px;background:transparent;color:var(--stone);font:600 16px/1 var(--mono);cursor:pointer}\n#brAddZone{margin-top:8px}\n#brBias{margin-bottom:8px}\n.br-chartpick{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.br-chartpick button{aspect-ratio:4/3;padding:0;border-radius:10px;border:2px solid var(--line-2);background:var(--panel-2);overflow:hidden;cursor:pointer;font:600 14px/1 var(--mono);color:var(--stone)}\n.br-chartpick button[aria-pressed=\"true\"]{border-color:var(--gold);box-shadow:0 0 0 2px rgba(216,173,78,.25)}\n.br-chartpick img{width:100%;height:100%;object-fit:cover;display:block}\n.br-drop{display:block;margin:8px auto 0;color:var(--muted)}\n.br-lesson{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:start;padding:10px 0;border-bottom:1px solid var(--line);font-size:13.5px;line-height:1.45}\n.br-lesson small{display:block;margin-bottom:3px;font:500 10.5px/1 var(--mono);color:var(--muted)}\n.br-lesson button{padding:7px 9px;border-radius:9px;border:1px solid var(--line-2);background:transparent;font:600 10px/1 var(--mono);letter-spacing:.08em;color:var(--stone);cursor:pointer}\n#brRemind,#brRemindSessions{margin-bottom:6px}\n#brGuide{font-size:14.5px}\n.pb-stats b small{margin-left:4px;font:500 10px/1 var(--mono);color:var(--muted)}\n.br-row + .pb-detail{padding-left:0}\n#brHeadline,#brReason,#brNewLesson{font-family:var(--sans)}\n\n</style>\n</head>\n<body>\n<template id=\"crown\"><svg viewBox=\"-19.2 -19.53 238.4 194.2\" aria-hidden=\"true\"><defs><linearGradient id=\"foil\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#F6E3A3\"/><stop offset=\"0.42\" stop-color=\"#D8AD4E\"/><stop offset=\"0.72\" stop-color=\"#B0812F\"/><stop offset=\"1\" stop-color=\"#E3C06D\"/></linearGradient></defs><path fill=\"url(#foil)\" fill-rule=\"evenodd\" d=\"M16 130L0 36.67L60 76.67L100 10L140 76.67L200 36.67L184 130ZM16 141.67H184V166.67H16ZM40 73.33H46V85H53V116.67H46V123.33H40V116.67H33V85H40ZM97 40H103V55H110V110H103V123.33H97V110H90V55H97ZM154 73.33H160V85H167V116.67H160V123.33H154V116.67H147V85H154Z\"/><circle cx=\"0\" cy=\"28.33\" r=\"11.2\" fill=\"url(#foil)\"/><circle cx=\"100\" cy=\"1.67\" r=\"13.2\" fill=\"url(#foil)\"/><circle cx=\"200\" cy=\"28.33\" r=\"11.2\" fill=\"url(#foil)\"/></svg></template>\n\n<header>\n  <span data-crown></span>\n  <div class=\"brand\"><b>TCP</b><span>QUANT TERMINAL</span></div>\n  <div class=\"who\" id=\"who\" hidden><span id=\"whoName\"></span><span class=\"avatar\" id=\"whoInitial\"></span></div>\n</header>\n\n<div class=\"engine\" id=\"engine\" aria-live=\"off\">\n  <span class=\"pulse\"></span><b id=\"engineState\">LIVE</b>\n  <span class=\"eq\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span>\n  <span>QUANT ENGINE</span>\n  <span class=\"sync\" id=\"engineSync\">starting…</span>\n</div>\n\n<main>\n  <!-- ============================================================ Markets -->\n  <section id=\"markets\">\n    <div class=\"segment\" role=\"group\" aria-label=\"Market\">\n      <button data-symbol=\"XAUUSD\" aria-pressed=\"true\"><b>XAUUSD</b><span>Gold</span></button>\n      <button data-symbol=\"BTCUSD\" aria-pressed=\"false\"><b>BTCUSD</b><span>Bitcoin</span></button>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><span class=\"label\" id=\"quoteName\">Gold · spot</span><span class=\"pill\" id=\"status\"><span class=\"dot\"></span><span></span></span></div>\n      <div class=\"quote\">\n        <div>\n          <div class=\"price\" id=\"price\"><span class=\"skeleton\" style=\"display:inline-block;width:180px;height:34px\"></span></div>\n          <div class=\"change\" id=\"change\">&nbsp;</div>\n        </div>\n        <svg id=\"spark\" viewBox=\"0 0 112 46\" preserveAspectRatio=\"none\" aria-label=\"Last 48 hours\"></svg>\n      </div>\n      <div class=\"testing\" id=\"testing\" hidden></div>\n      <div class=\"meta\" id=\"updated\">&nbsp;</div>\n    </div>\n\n    <div class=\"card brief\">\n      <div class=\"row spread\"><h2 class=\"label\">Engine briefing</h2><span class=\"tag\">from the numbers</span></div>\n      <p id=\"briefing\" aria-live=\"polite\"><span class=\"skeleton\" style=\"display:block;height:54px\"></span></p>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Chart · 15 min</h2><span class=\"timer\" id=\"candleTimer\"></span></div>\n      <div id=\"chart\"><div class=\"chart-note\" id=\"chartNote\">Loading the chart…</div></div>\n      <div class=\"keys\">\n        <span><i style=\"color:var(--gold)\"></i>Previous day</span>\n        <span><i style=\"color:var(--gold-soft);border-top-style:solid\"></i>Previous week</span>\n        <span><i style=\"color:#8C7BD1\"></i>Asia range</span>\n        <span><i style=\"color:rgba(227,192,109,.9)\"></i>68% cone</span>\n        <span><i style=\"color:rgba(166,157,140,.8);border-top-style:dotted\"></i>95% cone</span>\n        <span id=\"zoneKey\" hidden><i style=\"color:rgba(53,166,140,.9);border-top-style:dashed\"></i>Brief zones</span>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Probability swarm</h2><span class=\"tag\" id=\"swarmTag\">paths to the close</span></div>\n      <canvas id=\"swarm\" role=\"img\" aria-label=\"Simulated price paths from now to the close\"></canvas>\n      <div class=\"swarm-legend\" id=\"swarmLegend\"></div>\n      <div class=\"fine\">Each dot is one possible path from the live price to the close, drawn with this market's hour-by-hour volatility. A dot lights up when it touches a level, and the share that do settles on the engine's odds. At the close they stack into the spread of where it could finish. Tap to run it again.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Probability engine</h2><span class=\"tag\" id=\"closeIn\">to the close</span></div>\n      <div class=\"bands\">\n        <div class=\"band\"><span>68% CLOSE RANGE</span><b id=\"band68\">—</b></div>\n        <div class=\"band\"><span>95% CLOSE RANGE</span><b id=\"band95\">—</b></div>\n      </div>\n      <div class=\"row spread\" style=\"margin-bottom:2px\"><span class=\"label\">Level · chance of a touch</span><span class=\"label\">distance</span></div>\n      <div id=\"levels\"><div class=\"skeleton\" style=\"height:160px;margin-top:10px\"></div></div>\n      <div class=\"fine\">Chances of a touch before today's close, if price moves at random with this market's usual volatility for each hour. They measure reach, not direction. They move with every tick and shrink as the close gets nearer.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Market state</h2><span class=\"tag\">not a signal</span></div>\n      <div id=\"state\"></div>\n    </div>\n\n    <div class=\"card\">\n      <h2 class=\"label\">Volatility today</h2>\n      <div class=\"row spread\" style=\"align-items:flex-end\">\n        <div><div class=\"big\" id=\"range\">—</div><div class=\"sub\">moved today</div></div>\n        <div style=\"text-align:right\"><div class=\"big\" id=\"rangePct\">—</div><div class=\"sub\">of an average day</div></div>\n      </div>\n      <div class=\"gauge\" aria-hidden=\"true\"><div class=\"fill\" id=\"gaugeFill\" style=\"width:0\"></div><div class=\"avg\" style=\"left:66.6%\"></div></div>\n      <div class=\"gauge-scale\"><span>0%</span><span>100%</span><span>150%</span></div>\n      <div class=\"meta\" id=\"atrLine\">&nbsp;</div>\n      <div class=\"vclock\">\n        <div class=\"row spread\"><span class=\"label\" id=\"vclockTitle\">When it moves</span><span class=\"label\">your time</span></div>\n        <svg id=\"vclock\" viewBox=\"0 0 320 96\" preserveAspectRatio=\"none\" role=\"img\" aria-label=\"Typical move for each hour of the day\"></svg>\n        <div class=\"meta\" id=\"vclockNote\"></div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Sessions</h2><span class=\"label\" id=\"localTime\"></span></div>\n      <div class=\"sessions\" id=\"sessions\"></div>\n      <div class=\"overlap\" id=\"overlap\" hidden></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">Model check</h2><span class=\"tag\">out of sample</span></div>\n      <div id=\"check\"></div>\n    </div>\n  </section>\n\n  <!-- ============================================================== Risk -->\n  <section id=\"risk\" hidden>\n    <div class=\"card\">\n      <h2 class=\"label\">Position size</h2>\n      <div class=\"field\">\n        <label for=\"balance\">Account balance</label>\n        <div class=\"inputs\"><input id=\"balance\" inputmode=\"decimal\" placeholder=\"10000\" autocomplete=\"off\"><select id=\"currency\" aria-label=\"Account currency\"><option>USD</option><option>GBP</option><option>EUR</option></select></div>\n        <div class=\"hint\" id=\"fxHint\" hidden></div>\n      </div>\n      <div class=\"field\">\n        <label for=\"riskPct\">Risk per trade (%)</label>\n        <div class=\"inputs\"><input id=\"riskPct\" inputmode=\"decimal\" value=\"1\" autocomplete=\"off\">\n          <div class=\"chips\" id=\"riskChips\"><button data-risk=\"0.5\">0.5</button><button data-risk=\"1\">1</button><button data-risk=\"2\">2</button></div></div>\n      </div>\n      <div class=\"field\">\n        <label>Market</label>\n        <div class=\"chips\" id=\"riskMarket\"><button data-symbol=\"XAUUSD\">XAUUSD</button><button data-symbol=\"BTCUSD\">BTCUSD</button></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"row spread\"><label for=\"entry\">Entry</label><button class=\"link\" id=\"useLive\" type=\"button\">Use live price</button></div>\n        <input id=\"entry\" inputmode=\"decimal\" autocomplete=\"off\">\n      </div>\n      <div class=\"field\">\n        <label for=\"stop\">Stop loss</label>\n        <input id=\"stop\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Your stop price\">\n      </div>\n      <div class=\"field\" style=\"margin-bottom:0\">\n        <label for=\"contract\">Contract size (per 1.00 lot)</label>\n        <input id=\"contract\" inputmode=\"decimal\" autocomplete=\"off\">\n        <div class=\"hint\">Gold is usually 100 oz and Bitcoin 1 BTC. Check yours in MT5: tap the symbol, then Specification.</div>\n      </div>\n    </div>\n\n    <div class=\"card result\" id=\"result\">\n      <div class=\"label\">Lot size</div>\n      <div class=\"lots\" id=\"lots\">—</div>\n      <div class=\"sub\" id=\"lotsLine\">Enter your balance and stop loss.</div>\n      <div class=\"facts\" id=\"facts\" hidden></div>\n      <table id=\"targets\" hidden><thead><tr><th>TARGET</th><th>PRICE</th><th>ODDS</th><th>PROFIT</th></tr></thead><tbody></tbody></table>\n      <div class=\"odds-note\" id=\"oddsNote\" hidden></div>\n    </div>\n    <p class=\"note\">A calculator, not advice. Check the numbers in MT5 before you place a trade.</p>\n  </section>\n\n  <!-- =========================================================== Signals -->\n  <section id=\"signals\" hidden>\n    <div class=\"card pb-card\" id=\"pbCard\">\n      <div class=\"row spread\"><h2 class=\"label\">The Playbook</h2><span class=\"tag\" id=\"pbTag\">loading</span></div>\n      <p class=\"pb-lede\">Lewis's setups, logged <b>before</b> the result, with his reasons. Each one is followed to the end automatically, and every result counts.</p>\n      <div id=\"pbBody\">\n        <div class=\"pb-stats\">\n          <div><span>Results</span><b id=\"pbResults\">—</b></div>\n          <div><span>Won · lost</span><b id=\"pbWL\">—</b></div>\n          <div><span>Average</span><b id=\"pbAvg\">—</b></div>\n          <div><span>Total</span><b id=\"pbTotal\">—</b></div>\n        </div>\n        <div class=\"pb-chart\" id=\"pbChart\">\n          <canvas id=\"pbCurve\" role=\"img\" aria-label=\"The average result after each setup closed, with the band the true average likely sits in\"></canvas>\n          <div class=\"pb-tip\" id=\"pbTip\" hidden></div>\n        </div>\n        <div class=\"pb-legend\" aria-hidden=\"true\">\n          <span><i class=\"k-line\"></i>Average, after costs</span>\n          <span><i class=\"k-band\"></i>95% band</span>\n          <span><i class=\"k-won\"></i>Won</span>\n          <span><i class=\"k-lost\"></i>Lost</span>\n        </div>\n        <div class=\"pb-verdict\" id=\"pbVerdict\"></div>\n        <p class=\"pb-first\" id=\"pbFirst\"></p>\n        <p class=\"fine\">Results in R after an assumed spread. With no edge, the average sits on zero; an edge shows when the whole band clears it, and that takes many results.</p>\n      </div>\n      <p class=\"pb-empty\" id=\"pbEmpty\" hidden></p>\n      <button class=\"pb-more\" id=\"pbExport\" type=\"button\" hidden>SEND ME THE WHOLE RECORD</button>\n    </div>\n\n    <div id=\"pbActive\"></div>\n\n    <div class=\"card\" id=\"pbHistoryCard\" hidden>\n      <div class=\"row spread\"><h2 class=\"label\">History</h2><span class=\"tag\" id=\"pbCount\"></span></div>\n      <div id=\"pbHistory\"></div>\n    </div>\n\n    <div class=\"card\" id=\"pbReadsCard\" hidden>\n      <div class=\"row spread\"><h2 class=\"label\">Early reads</h2><span class=\"tag\">not evidence</span></div>\n      <div id=\"pbReads\"></div>\n      <p class=\"fine\">Averages after costs for each reason, market and session with at least 5 results. With this many ways to slice a small record, some will look good by luck: treat them as questions, not answers.</p>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"row spread\"><h2 class=\"label\">From the algo to your account</h2><span class=\"tag\">the plan</span></div>\n      <div class=\"pipe\">\n        <div class=\"node\">\n          <span class=\"node-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><path d=\"M4 18 9 12l4 3 7-9\"/><path d=\"M15 6h5v5\"/></svg></span>\n          <div><b>TCP algo</b><small>Finds the trade: entry, stop and targets, by fixed rules.</small></div>\n          <span class=\"state testing\">In forward test</span>\n        </div>\n        <div class=\"flow\" aria-hidden=\"true\"><i></i><i></i><i></i></div>\n        <div class=\"node\">\n          <span class=\"node-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"><path d=\"M13 2 4 14h7l-1 8 9-12h-7l1-8Z\"/></svg></span>\n          <div><b>Terminal and Inner Circle</b><small>The signal lands here and in the group at the same moment, with its odds.</small></div>\n          <span class=\"state testing\">Waiting on the algo</span>\n        </div>\n        <div class=\"flow\" aria-hidden=\"true\"><i></i><i></i><i></i></div>\n        <div class=\"node\">\n          <span class=\"node-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"12\" rx=\"2\"/><path d=\"M8 21h8M12 17v4\"/></svg></span>\n          <div><b>The TCP EA</b><small>Places the trade on Lewis's account, exactly as signalled.</small></div>\n          <span class=\"state testing\">Dry run</span>\n        </div>\n        <div class=\"flow\" aria-hidden=\"true\"><i></i><i></i><i></i></div>\n        <div class=\"node\">\n          <span class=\"node-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><circle cx=\"9\" cy=\"8\" r=\"3.5\"/><path d=\"M2.5 20a6.5 6.5 0 0 1 13 0\"/><path d=\"M16 11.5a3 3 0 1 0 0-6M17.5 20h4a5.5 5.5 0 0 0-4.5-5.4\"/></svg></span>\n          <div><b>Your account</b><small>Copy trading: the same trade on your MT5, at the size you choose.</small></div>\n          <span class=\"state soon-tag\">Coming soon</span>\n        </div>\n      </div>\n      <p class=\"note serif\" style=\"margin:14px 0 0\">Proven first. Then live.</p>\n    </div>\n\n    <div class=\"card example\">\n      <div class=\"row spread\"><h2 class=\"label\">What a signal will look like</h2><span class=\"tag\">example</span></div>\n      <div class=\"sig\">\n        <div class=\"sig-top\"><b>XAUUSD</b><span class=\"sig-side\">BUY</span><span class=\"sig-time\">09:12 · London</span></div>\n        <div class=\"sig-grid\">\n          <div><span>Entry</span><b>3,742.50</b></div>\n          <div><span>Stop</span><b>3,737.50</b></div>\n          <div><span>Target 1 · 1R</span><b>3,747.50</b></div>\n          <div><span>Target 2 · 2R</span><b>3,752.50</b></div>\n        </div>\n        <div class=\"sig-foot\"><span>Tested win rate <b>—</b></span><span>Your size at 1% <b>0.20 lots</b></span></div>\n        <span class=\"watermark\">EXAMPLE</span>\n      </div>\n      <div class=\"fine\">Not a live signal. Once the algo passes its forward test, each signal shows its tested win rate and a size worked out for your account, and every result is posted in full.</div>\n    </div>\n\n    <div class=\"card soon-card\" data-feature=\"copy\">\n      <div class=\"row spread\"><h2 class=\"label\">Copy trading</h2><span class=\"state soon-tag\">Coming soon</span></div>\n      <p>Connect your MT5 account and the algo's trades copy onto it automatically, at the risk you set. Pause or stop whenever you like.</p>\n      <button class=\"notify\" type=\"button\">Notify me</button>\n    </div>\n  </section>\n\n  <!-- ================================================================ AI -->\n  <section id=\"ai\" hidden>\n    <div class=\"card ai-hero\">\n      <canvas id=\"orb\" aria-hidden=\"true\"></canvas>\n      <div class=\"ai-copy\">\n        <span class=\"state testing\" id=\"brMode\" hidden>Test mode</span>\n        <h2>TCP AI</h2>\n        <p>Before each session, Lewis sends his charts. TCP AI reads them with the terminal's numbers and drafts the brief, and Lewis checks it before it posts. After the session, every zone is scored.</p>\n      </div>\n    </div>\n\n    <div class=\"card br-next\" id=\"brNext\" hidden>\n      <div class=\"row spread\"><h2 class=\"label\">Next session</h2><span class=\"tag\" id=\"brNextTag\"></span></div>\n      <div class=\"br-nextrow\"><span class=\"br-icon\" id=\"brNextIcon\" aria-hidden=\"true\"></span><div><b id=\"brNextName\"></b><small id=\"brNextWhen\" data-open=\"\"></small></div></div>\n      <p class=\"br-ask\" id=\"brAsk\" hidden></p>\n    </div>\n\n    <div id=\"brList\"></div>\n\n    <div class=\"card\" id=\"brRecordCard\" hidden>\n      <div class=\"row spread\"><h2 class=\"label\">Zone record</h2><span class=\"tag\">vs a random walk</span></div>\n      <div class=\"pb-stats\">\n        <div><span>Briefs</span><b id=\"brBriefs\">—</b></div>\n        <div><span>Zones</span><b id=\"brZoneCount\">—</b></div>\n        <div><span>Reached</span><b id=\"brReached\">—</b></div>\n        <div><span>Avg turn</span><b id=\"brTurn\">—</b></div>\n      </div>\n      <div class=\"pb-verdict\" id=\"brVerdict\"></div>\n      <p class=\"pb-first\" id=\"brReach\"></p>\n      <div id=\"brReads\" hidden></div>\n      <p class=\"fine\">A zone counts as reached when price trades into it after the brief goes out. The turn is how far price then went back the way it came, less how far it went on through, before the session closed, in average daily ranges (ATR). Moving at random, price reaches each zone as often as its odds say and goes back as far as it goes through, so zero is the line to beat.</p>\n    </div>\n\n    <div class=\"card\" id=\"brHistoryCard\" hidden>\n      <div class=\"row spread\"><h2 class=\"label\">Earlier briefs</h2><span class=\"tag\" id=\"brCount\"></span></div>\n      <div id=\"brHistory\"></div>\n    </div>\n\n    <div class=\"card ai-memory\" id=\"aiMemory\">\n      <div class=\"row spread\"><h2 class=\"label\">What TCP AI has learned</h2><span class=\"state testing\">Growing</span></div>\n      <div class=\"mem-grid\">\n        <div><b id=\"memCharts\">0</b><span>charts read</span></div>\n        <div><b id=\"memLessons\">0</b><span>lessons from Lewis</span></div>\n        <div><b id=\"memZones\">0</b><span>zones scored</span></div>\n      </div>\n      <p>Before every brief, TCP AI reads Lewis's guide to his charts, what he changed in its earlier drafts, and how the zones have done since. <span id=\"memPlaybook\"></span></p>\n      <div class=\"pb-buttons\"><button type=\"button\" class=\"gold\" id=\"brTeach\" hidden>TEACH TCP AI</button><button type=\"button\" id=\"brExport\" hidden>SEND ME THE DATA</button></div>\n    </div>\n\n    <div class=\"card feature-list\" data-feature=\"ai\">\n      <div class=\"feature\"><b>Session briefs</b><p>Lewis's charts, read by TCP AI before each session: the zones to watch, the plan, and every zone scored afterwards.</p><span class=\"state live\">Live</span></div>\n      <div class=\"feature\"><b>Snap to log</b><p>Send a screenshot of your chart and TCP AI reads the indicator's panel to fill in the setup: zone, fib, confirmations.</p><span class=\"state soon-tag\">Soon</span></div>\n      <div class=\"feature\"><b>AI trade reviews</b><p>After every trade: what went to plan, what didn't, and what to change.</p><span class=\"state soon-tag\">Soon</span></div>\n      <div class=\"feature\"><b>Ask TCP AI</b><p>Ask about a level, a setup or your risk, and get answers built on the engine's numbers.</p><span class=\"state soon-tag\">Soon</span></div>\n      <div class=\"feature\"><b>Your AI coach</b><p>A weekly look at your habits: best sessions, overtrading, and how well you keep to your stops.</p><span class=\"state soon-tag\">Soon</span></div>\n      <button class=\"notify\" type=\"button\">Notify me</button>\n    </div>\n    <p class=\"note\">TCP AI reads the charts Lewis sends; it doesn't place trades. The odds on each zone come from the terminal's engine, not from AI. The engine briefing on Markets is written from the numbers.</p>\n  </section>\n\n  <!-- ============================================================ Account -->\n  <section id=\"account\" hidden>\n    <div class=\"card profile\">\n      <span class=\"avatar big-avatar\" id=\"profileInitial\">?</span>\n      <div><b id=\"profileName\">Member</b><small id=\"profileRole\">TCP Inner Circle</small></div>\n    </div>\n    <div class=\"card soon-card\" data-feature=\"connect\">\n      <div class=\"row spread\"><h2 class=\"label\">Connect your account</h2><span class=\"state soon-tag\">Coming soon</span></div>\n      <p>Link your MT5 account or wallet to see your real results here. Read-only: the terminal can see your trades, never move your money.</p>\n      <button class=\"notify\" type=\"button\">Notify me</button>\n    </div>\n    <div class=\"card soon-card\">\n      <div class=\"row spread\"><h2 class=\"label\">Your trading, measured</h2><span class=\"state soon-tag\">After connecting</span></div>\n      <div class=\"stat-preview\">\n        <div><span>Profit factor</span><b>—</b></div>\n        <div><span>Win rate</span><b>—</b></div>\n        <div><span>Average R</span><b>—</b></div>\n        <div><span>Max drawdown</span><b>—</b></div>\n      </div>\n      <p style=\"margin-top:12px\">Plus your equity curve, and your best and worst sessions, days and markets.</p>\n    </div>\n    <div class=\"card soon-card\" data-feature=\"alerts\">\n      <div class=\"row spread\"><h2 class=\"label\">Price and odds alerts</h2><span class=\"state soon-tag\">Coming soon</span></div>\n      <p>A Telegram message when gold reaches a level you pick, or when the odds of a touch climb past your line.</p>\n      <button class=\"notify\" type=\"button\">Notify me</button>\n    </div>\n  </section>\n</main>\n\n<button class=\"pb-fab\" id=\"pbNew\" type=\"button\" hidden>+ LOG A SETUP</button>\n<button class=\"pb-fab\" id=\"brNew\" type=\"button\" hidden>+ SEND CHARTS</button>\n\n<div class=\"sheet\" id=\"pbSheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pbSheetTitle\" hidden>\n  <div class=\"sheet-body\">\n    <div class=\"row spread sheet-head\"><h2 id=\"pbSheetTitle\">Log a setup</h2><button class=\"link\" id=\"pbClose\" type=\"button\">Close</button></div>\n    <div class=\"field\"><label>Market</label><div class=\"chips\" id=\"pbSymbol\"><button type=\"button\" data-v=\"XAUUSD\">Gold</button><button type=\"button\" data-v=\"BTCUSD\">Bitcoin</button></div></div>\n    <div class=\"field\"><label>Direction</label><div class=\"chips\" id=\"pbSide\"><button type=\"button\" data-v=\"buy\">Buy</button><button type=\"button\" data-v=\"sell\">Sell</button></div></div>\n    <div class=\"field\"><label>Order</label><div class=\"chips\" id=\"pbKind\"><button type=\"button\" data-v=\"market\">Market</button><button type=\"button\" data-v=\"limit\">Limit</button><button type=\"button\" data-v=\"stop\">Stop</button></div></div>\n    <div class=\"pb-prices\">\n      <div class=\"field\"><label for=\"pbEntry\">Entry</label><input id=\"pbEntry\" inputmode=\"decimal\" autocomplete=\"off\"></div>\n      <div class=\"field\"><label for=\"pbSl\">Stop</label><input id=\"pbSl\" inputmode=\"decimal\" autocomplete=\"off\"></div>\n      <div class=\"field\"><label for=\"pbTp\">Target</label><input id=\"pbTp\" inputmode=\"decimal\" autocomplete=\"off\"></div>\n    </div>\n    <div class=\"pb-plan\" id=\"pbPlan\">Enter the stop and the target.</div>\n    <div class=\"field\" id=\"pbExpiryField\" hidden><label>Waits for its price</label><div class=\"chips\" id=\"pbExpiry\"><button type=\"button\" data-v=\"4\">4 hours</button><button type=\"button\" data-v=\"24\">A day</button><button type=\"button\" data-v=\"168\">A week</button></div></div>\n    <div class=\"field\"><label>Reasons</label><div class=\"tagpick\" id=\"pbTags\"></div>\n      <input id=\"pbTagNew\" placeholder=\"Add your own reason\" maxlength=\"24\" autocomplete=\"off\" enterkeyhint=\"done\"></div>\n    <div class=\"field\"><label for=\"pbNote\">Why</label><textarea id=\"pbNote\" rows=\"3\" maxlength=\"400\" placeholder=\"The reason for this trade, in a sentence or two. It goes out with the setup.\"></textarea></div>\n    <div class=\"field\"><label>Chart</label>\n      <label class=\"pb-photo\" id=\"pbPhotoLabel\"><input type=\"file\" id=\"pbPhoto\" accept=\"image/*\" hidden><span id=\"pbPhotoText\">Add a screenshot of your chart</span><img id=\"pbPhotoPreview\" alt=\"Your chart\" hidden></label></div>\n    <div class=\"pb-error\" id=\"pbError\" role=\"alert\" hidden></div>\n    <button class=\"cta pb-submit\" id=\"pbSubmit\" type=\"button\">LOG AND POST</button>\n    <p class=\"fine\" id=\"pbSubmitNote\"></p>\n  </div>\n</div>\n\n<div class=\"sheet\" id=\"brSheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"brSheetTitle\" hidden>\n  <div class=\"sheet-body\">\n    <div class=\"row spread sheet-head\"><h2 id=\"brSheetTitle\">Session brief</h2><button class=\"link\" id=\"brClose\" type=\"button\">Close</button></div>\n\n    <div id=\"brStep_charts\">\n      <div class=\"field\"><label>Session</label><div class=\"chips\" id=\"brSession\"></div></div>\n      <div class=\"field\"><label>Market</label><div class=\"chips\" id=\"brSymbol\"><button type=\"button\" data-v=\"XAUUSD\">Gold</button><button type=\"button\" data-v=\"BTCUSD\">Bitcoin</button></div></div>\n      <div class=\"field\"><label>Charts</label>\n        <p class=\"br-askline\" id=\"brAskLine\"></p>\n        <div class=\"br-thumbs\" id=\"brThumbs\"></div>\n        <label class=\"pb-photo\"><input type=\"file\" id=\"brFiles\" accept=\"image/*\" multiple hidden><span id=\"brPickText\">Add your chart screenshots</span></label></div>\n      <div class=\"field\"><label for=\"brNote\">Your read (optional)</label><textarea id=\"brNote\" rows=\"2\" maxlength=\"600\" placeholder=\"Anything TCP AI should know: your bias, news, what you're waiting for.\"></textarea></div>\n      <div class=\"pb-error\" id=\"brError\" role=\"alert\" hidden></div>\n      <button class=\"cta pb-submit\" id=\"brRead\" type=\"button\" disabled>READ MY CHARTS</button>\n      <p class=\"fine\" id=\"brReadNote\"></p>\n    </div>\n\n    <div id=\"brStep_reading\" hidden>\n      <div class=\"br-reading\" aria-live=\"polite\">\n        <div class=\"br-scan\" aria-hidden=\"true\"><i></i></div>\n        <b id=\"brReadingWhat\">TCP AI is reading your charts</b>\n        <span class=\"br-elapsed\" id=\"brElapsed\">0:00</span>\n        <p class=\"fine\">It reads each chart and the panel, checks them against the terminal's numbers, and drafts the brief. Usually under a minute. You can close the app: the bot tells you when the draft is ready.</p>\n      </div>\n    </div>\n\n    <div id=\"brStep_draft\" hidden>\n      <div class=\"br-failed\" id=\"brFailed\" hidden>\n        <p id=\"brFailedText\"></p>\n        <div class=\"pb-buttons\"><button type=\"button\" class=\"gold\" id=\"brRetry\">TRY AGAIN</button><button type=\"button\" id=\"brManual\">WRITE IT MYSELF</button></div>\n      </div>\n      <div class=\"br-warnings\" id=\"brWarnings\" hidden></div>\n      <details class=\"br-readcard\" id=\"brReadCard\" hidden><summary>What TCP AI read</summary><div id=\"brReadBody\"></div></details>\n      <div class=\"field\"><label for=\"brHeadline\">Headline</label><input id=\"brHeadline\" maxlength=\"120\" autocomplete=\"off\" placeholder=\"One line for the Inner Circle\"></div>\n      <div class=\"field\"><label>Bias</label><div class=\"chips\" id=\"brBias\"><button type=\"button\" data-v=\"long\">Long</button><button type=\"button\" data-v=\"short\">Short</button><button type=\"button\" data-v=\"neutral\">Neutral</button></div>\n        <input id=\"brReason\" maxlength=\"240\" autocomplete=\"off\" placeholder=\"Why, in a sentence\"></div>\n      <div class=\"field\"><label>Zones to watch</label><div id=\"brZones\"></div><button type=\"button\" class=\"pb-more\" id=\"brAddZone\">+ ADD A ZONE</button></div>\n      <div class=\"field\"><label for=\"brPlan\">Plan · one line each</label><textarea id=\"brPlan\" rows=\"4\" maxlength=\"900\" placeholder=\"If … then …\"></textarea></div>\n      <div class=\"field\" id=\"brChartField\"><label>Chart to post with it</label><div class=\"br-chartpick\" id=\"brChartPick\"></div></div>\n      <div class=\"field\"><label for=\"brLesson\">What it got wrong (optional)</label><textarea id=\"brLesson\" rows=\"2\" maxlength=\"400\" placeholder=\"e.g. The Asia high only matters once it has been swept.\"></textarea>\n        <div class=\"hint\">TCP AI reads this, and what you changed above, before its next brief.</div></div>\n      <button class=\"cta pb-submit\" id=\"brPost\" type=\"button\">POST</button>\n      <p class=\"fine\" id=\"brPostNote\"></p>\n      <button type=\"button\" class=\"link br-drop\" id=\"brDrop\">Drop this draft</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"sheet\" id=\"brTeachSheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"brTeachTitle\" hidden>\n  <div class=\"sheet-body\">\n    <div class=\"row spread sheet-head\"><h2 id=\"brTeachTitle\">Teach TCP AI</h2><button class=\"link\" id=\"brTeachClose\" type=\"button\">Close</button></div>\n    <div class=\"field\"><label for=\"brGuide\">How to read your charts</label>\n      <textarea id=\"brGuide\" rows=\"9\" maxlength=\"6000\" placeholder=\"What your indicator's panel shows and what each row means, the colours, which zones you trust, what you never trade…\"></textarea>\n      <div class=\"hint\">TCP AI reads this before every brief. It stays in the terminal's database, not in any public file.</div></div>\n    <div class=\"field\"><label>Reminders before each session</label>\n      <div class=\"chips\" id=\"brRemind\"><button type=\"button\" data-v=\"on\">On</button><button type=\"button\" data-v=\"off\">Off</button></div>\n      <div class=\"chips\" id=\"brRemindSessions\"></div>\n      <div class=\"chips\" id=\"brLead\"><button type=\"button\" data-v=\"30\">30 min before</button><button type=\"button\" data-v=\"45\">45 min</button><button type=\"button\" data-v=\"60\">1 hour</button></div></div>\n    <div class=\"field\"><label for=\"brNewLesson\">Add a lesson</label><input id=\"brNewLesson\" maxlength=\"400\" autocomplete=\"off\" placeholder=\"Something TCP AI should always remember\"></div>\n    <button class=\"cta pb-submit\" id=\"brTeachSave\" type=\"button\">SAVE</button>\n    <div class=\"field\" style=\"margin-top:18px\"><label>What it has learned from you</label><div id=\"brLessons\"></div></div>\n  </div>\n</div>\n\n<div class=\"viewer\" id=\"pbViewer\" hidden><img id=\"pbViewerImg\" alt=\"The chart for this setup\"><button class=\"link\" id=\"pbViewerClose\" type=\"button\">Close</button></div>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\" hidden></div>\n\n<nav aria-label=\"Terminal\">\n  <button data-tab=\"markets\" aria-current=\"page\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><path d=\"M6 3v4M6 17v4M12 6v3M12 17v3M18 4v3M18 14v6\"/><rect x=\"4\" y=\"7\" width=\"4\" height=\"10\" rx=\"1\"/><rect x=\"10\" y=\"9\" width=\"4\" height=\"8\" rx=\"1\"/><rect x=\"16\" y=\"7\" width=\"4\" height=\"7\" rx=\"1\"/></svg>MARKETS</button>\n  <button data-tab=\"risk\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><circle cx=\"12\" cy=\"12\" r=\"4.5\"/><path d=\"M12 2v4M12 18v4M2 12h4M18 12h4\"/></svg>RISK</button>\n  <button data-tab=\"signals\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"><path d=\"M13 2 4 14h7l-1 8 9-12h-7l1-8Z\"/></svg>SIGNALS</button>\n  <button data-tab=\"ai\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"><path d=\"M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3Z\"/><path d=\"M19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8L19 15Z\"/></svg>AI</button>\n  <button data-tab=\"account\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21a8 8 0 0 1 16 0\"/></svg>ACCOUNT</button>\n</nav>\n\n<div class=\"gate\" id=\"gate\">\n  <div>\n    <span data-crown></span>\n    <h1 id=\"gateTitle\">Checking your membership…</h1>\n    <p id=\"gateText\">One moment.</p>\n    <a class=\"cta\" id=\"gateCta\" hidden></a>\n  </div>\n</div>\n\n<script type=\"module\">\n// TCP Quant Terminal: the market maths, shared by the Worker and the page.\n// Pure functions, no dependencies. Times are Unix seconds (UTC); bars are\n// { t, o, h, l, c } with t the bar's open time, oldest first.\n//\n// These are standard, public reference levels (previous day and week, opens,\n// session ranges, round numbers) and a probability engine built on a plain,\n// stated model: price as a trendless random walk with each market's own\n// hour-by-hour volatility. It forecasts reach, not direction, and it checks\n// itself against history (calibrate). No strategy rules live here: the algo's\n// own zones join the terminal only after they pass their forward test.\n\nconst MARKETS = {\n  XAUUSD: { symbol: 'XAUUSD', name: 'Gold', digits: 2, contract: 100, day: 'ny', round: 50 },\n  BTCUSD: { symbol: 'BTCUSD', name: 'Bitcoin', digits: 2, contract: 1, day: 'utc', round: 1000 },\n};\n\n// Forex sessions in local time, Monday to Friday.\nconst SESSIONS = [\n  { id: 'sydney', name: 'Sydney', tz: 'Australia/Sydney', open: 7, close: 16 },\n  { id: 'tokyo', name: 'Tokyo', range: 'Asia', tz: 'Asia/Tokyo', open: 9, close: 18 },\n  { id: 'london', name: 'London', range: 'London', tz: 'Europe/London', open: 8, close: 17 },\n  { id: 'newyork', name: 'New York', range: 'New York', tz: 'America/New_York', open: 8, close: 17 },\n];\n\n// ------------------------------------------------------------ time zones\nconst formatters = {};\nfunction zoned(ts, tz) {\n  formatters[tz] ||= new Intl.DateTimeFormat('en-GB', {\n    timeZone: tz, hourCycle: 'h23', weekday: 'short',\n    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',\n  });\n  const p = {};\n  for (const { type, value } of formatters[tz].formatToParts(new Date(ts * 1000))) p[type] = value;\n  return { y: +p.year, m: +p.month, d: +p.day, h: +p.hour, min: +p.minute, s: +p.second, wd: p.weekday };\n}\n\n// The UTC time of a wall-clock time in a time zone (DST-aware).\nfunction wallToUtc(tz, y, m, d, h = 0, min = 0) {\n  const wall = Date.UTC(y, m - 1, d, h, min) / 1000;\n  let ts = wall;\n  for (let i = 0; i < 3; i++) {\n    const z = zoned(ts, tz);\n    const offset = Date.UTC(z.y, z.m - 1, z.d, z.h, z.min, z.s) / 1000 - ts;\n    const next = wall - offset;\n    if (next === ts) break;\n    ts = next;\n  }\n  return ts;\n}\n\n// New York time without Intl, for loops over thousands of bars (a Worker on the free\n// plan gets 10 ms of CPU per request). US daylight saving runs from the second Sunday\n// in March, 02:00 local (07:00 UTC), to the first Sunday in November, 02:00 local (06:00 UTC).\nfunction nthSunday(y, month, n, hourUtc) {\n  const first = new Date(Date.UTC(y, month - 1, 1)).getUTCDay();\n  return Date.UTC(y, month - 1, 1 + ((7 - first) % 7) + 7 * (n - 1), hourUtc) / 1000;\n}\nconst usDst = {};\nfunction nyOffset(ts) {\n  // The year only picks the daylight-saving window, and both windows sit far from New\n  // Year, so the average Gregorian year (365.2425 days) is exact enough and needs no Date.\n  const y = 1970 + Math.floor(ts / 31556952);\n  const [from, to] = (usDst[y] ||= [nthSunday(y, 3, 2, 7), nthSunday(y, 11, 1, 6)]);\n  return ts >= from && ts < to ? -4 * 3600 : -5 * 3600;\n}\nconst DAY = 86400;\nconst nyHour = (ts) => Math.floor(((((ts + nyOffset(ts)) % DAY) + DAY) % DAY) / 3600);\n\n// The same yes/no as marketStatus(market, ts).open, fast enough for thousands of bars:\n// gold shuts from Friday 17:00 to Sunday 18:00 New York, and from 17:00 to 18:00 each day.\nfunction marketOpen(ts, market) {\n  if (market.day === 'utc') return true;\n  const local = ts + nyOffset(ts);\n  const days = Math.floor(local / DAY);\n  const hour = (local - days * DAY) / 3600;\n  const weekday = (((days + 4) % 7) + 7) % 7; // 0 is Sunday: 1 January 1970 was a Thursday\n  if (hour >= 17 && hour < 18) return false;\n  return !(weekday === 6 || (weekday === 0 && hour < 18) || (weekday === 5 && hour >= 17));\n}\n\n// A trading day as a whole number of days since 1970 (fast; dayKey gives the same day as text).\nfunction dayIndex(ts, market) {\n  if (market.day === 'utc') return Math.floor(ts / DAY);\n  const i = Math.floor((ts + nyOffset(ts) + 7 * 3600) / DAY);\n  const wd = (i + 4) % 7; // 1 January 1970 was a Thursday; 0 is Sunday\n  return wd === 6 ? i + 2 : wd === 0 ? i + 1 : i;\n}\n\nconst iso = (y, m, d) => `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;\nconst addDays = (key, n) => new Date(Date.parse(key + 'T00:00:00Z') + n * 86400e3).toISOString().slice(0, 10);\nconst weekdayOf = (key) => new Date(key + 'T00:00:00Z').getUTCDay(); // 0 Sunday ... 6 Saturday\nconst mondayOf = (key) => addDays(key, -((weekdayOf(key) + 6) % 7));\n\n// The trading day a moment belongs to. Gold's day ends at 17:00 New York (as on\n// broker charts), and a weekend belongs to the Monday after it; Bitcoin uses UTC days.\nconst keyOf = (index) => new Date(index * DAY * 1000).toISOString().slice(0, 10);\nconst dayKey = (ts, market) => keyOf(dayIndex(ts, market));\n\n// ------------------------------------------------------------------- bars\n// Merge bars (or days) that share a key into one bar per key.\nfunction groupBars(bars, keyOf) {\n  const out = [];\n  for (const b of bars) {\n    const key = keyOf(b);\n    const last = out[out.length - 1];\n    if (last && last.key === key) {\n      last.h = Math.max(last.h, b.h);\n      last.l = Math.min(last.l, b.l);\n      last.c = b.c;\n    } else {\n      out.push({ key, t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });\n    }\n  }\n  return out;\n}\n\nfunction toDays(bars, market) {\n  const days = [];\n  let index = null;\n  for (const b of bars) {\n    const i = dayIndex(b.t, market);\n    const last = days[days.length - 1];\n    if (last && i === index) {\n      last.h = Math.max(last.h, b.h);\n      last.l = Math.min(last.l, b.l);\n      last.c = b.c;\n    } else {\n      index = i;\n      days.push({ key: keyOf(i), t: b.t, o: b.o, h: b.h, l: b.l, c: b.c });\n    }\n  }\n  return days;\n}\n\n// Wilder's average true range over completed days.\nfunction atr(days, period = 14) {\n  if (days.length < period + 1) return null;\n  const tr = days.slice(1).map((d, i) => Math.max(d.h - d.l, Math.abs(d.h - days[i].c), Math.abs(d.l - days[i].c)));\n  let value = tr.slice(0, period).reduce((a, b) => a + b, 0) / period;\n  for (const x of tr.slice(period)) value = (value * (period - 1) + x) / period;\n  return value;\n}\n\nfunction rangeOf(bars, from, to) {\n  const inside = bars.filter((b) => b.t >= from && b.t < to);\n  if (!inside.length) return null;\n  return { high: Math.max(...inside.map((b) => b.h)), low: Math.min(...inside.map((b) => b.l)) };\n}\n\n// Session windows on a trading day's date, in UTC.\nfunction sessionWindow(session, key) {\n  const [y, m, d] = key.split('-').map(Number);\n  return { from: wallToUtc(session.tz, y, m, d, session.open), to: wallToUtc(session.tz, y, m, d, session.close) };\n}\n\n// ---------------------------------------------------------------- snapshot\n// days: daily bars (the last may be today's, still forming); intraday: 15-minute bars.\nfunction snapshot(market, days, intraday, now) {\n  const today = dayKey(now, market);\n  const done = days.filter((d) => d.key < today);\n  let current = days.find((d) => d.key === today) || null;\n  const fresh = intraday.filter((b) => dayKey(b.t, market) === today);\n  if (fresh.length) {\n    current = {\n      key: today, t: current ? current.t : fresh[0].t, o: current ? current.o : fresh[0].o,\n      h: Math.max(current ? current.h : -Infinity, ...fresh.map((b) => b.h)),\n      l: Math.min(current ? current.l : Infinity, ...fresh.map((b) => b.l)),\n      c: fresh[fresh.length - 1].c,\n    };\n  }\n  const prev = done[done.length - 1] || null;\n  const price = intraday.length ? intraday[intraday.length - 1].c : current ? current.c : prev ? prev.c : null;\n\n  const thisWeek = mondayOf(today);\n  const weeks = groupBars(done, (d) => mondayOf(d.key));\n  const prevWeek = [...weeks].reverse().find((w) => w.key < thisWeek) || null;\n  const weekOpenDay = days.find((d) => mondayOf(d.key) === thisWeek) || null;\n\n  const averageRange = atr(done);\n  const todayRange = current ? current.h - current.l : 0;\n\n  const levels = [];\n  const add = (id, name, value) => { if (Number.isFinite(value)) levels.push({ id, name, price: value }); };\n  if (prev) { add('pdh', 'Previous day high', prev.h); add('pdl', 'Previous day low', prev.l); }\n  if (prevWeek) { add('pwh', 'Previous week high', prevWeek.h); add('pwl', 'Previous week low', prevWeek.l); }\n  if (current) add('do', 'Day open', current.o);\n  if (weekOpenDay) add('wo', 'Week open', weekOpenDay.o);\n\n  const sessions = {};\n  for (const s of SESSIONS.filter((x) => x.range)) {\n    const { from, to } = sessionWindow(s, today);\n    const r = from <= now ? rangeOf(intraday, from, Math.min(to, now + 1)) : null;\n    sessions[s.id] = r && { ...r, from, to, done: now >= to };\n    if (r) { add(`${s.id}_h`, `${s.range} high`, r.high); add(`${s.id}_l`, `${s.range} low`, r.low); }\n  }\n  if (Number.isFinite(price)) {\n    const below = Math.floor(price / market.round) * market.round;\n    add('round_up', 'Round number', below + market.round);\n    add('round_down', 'Round number', below === price ? below - market.round : below);\n  }\n  levels.sort((a, b) => b.price - a.price);\n\n  return {\n    symbol: market.symbol, name: market.name, digits: market.digits, day: today,\n    price,\n    dayOpen: current ? current.o : null,\n    dayHigh: current ? current.h : null,\n    dayLow: current ? current.l : null,\n    change: current && Number.isFinite(price) ? price - current.o : null,\n    changePct: current && Number.isFinite(price) ? ((price - current.o) / current.o) * 100 : null,\n    atr: averageRange,\n    todayRange,\n    rangePct: averageRange ? (todayRange / averageRange) * 100 : null,\n    levels,\n    sessions,\n  };\n}\n\n// ------------------------------------------------------------ session clock\n// Which sessions are open at `now`, and when each next opens or closes.\nfunction sessionClock(now) {\n  return SESSIONS.map((s) => {\n    const z = zoned(now, s.tz);\n    const base = iso(z.y, z.m, z.d);\n    let open = null;\n    let next = null;\n    for (let i = -1; i <= 7 && !next; i++) {\n      const key = addDays(base, i);\n      const wd = weekdayOf(key);\n      if (wd === 0 || wd === 6) continue;\n      const w = sessionWindow(s, key);\n      if (w.from <= now && now < w.to) open = w;\n      else if (w.from > now && !next) next = w;\n    }\n    return open\n      ? { id: s.id, name: s.name, open: true, closesIn: open.to - now, until: open.to }\n      : { id: s.id, name: s.name, open: false, opensIn: next ? next.from - now : null, at: next && next.from };\n  });\n}\n\n// Gold closes from Friday 17:00 to Sunday 18:00 New York, with a daily break\n// from 17:00 to 18:00; Bitcoin never closes.\nfunction marketStatus(market, now) {\n  if (market.day === 'utc') return { open: true };\n  const z = zoned(now, 'America/New_York');\n  const key = iso(z.y, z.m, z.d);\n  const wd = weekdayOf(key);\n  const hour = z.h + z.min / 60;\n  const at = (dayOffset, h) => {\n    const [y, m, d] = addDays(key, dayOffset).split('-').map(Number);\n    return wallToUtc('America/New_York', y, m, d, h);\n  };\n  if (wd === 6) return { open: false, reason: 'weekend', opensAt: at(1, 18) };\n  if (wd === 0 && hour < 18) return { open: false, reason: 'weekend', opensAt: at(0, 18) };\n  if (wd === 5 && hour >= 17) return { open: false, reason: 'weekend', opensAt: at(2, 18) };\n  if (hour >= 17 && hour < 18) return { open: false, reason: 'daily break', opensAt: at(0, 18) };\n  const closeDay = hour >= 18 ? 1 : 0;\n  return { open: true, closesAt: at(closeDay, 17), weekendClose: weekdayOf(addDays(key, closeDay)) === 5 };\n}\n\n// ------------------------------------------------------------------- risk\n// usdPerUnit: the US-dollar value of one unit of the account currency\n// (1 for USD accounts; about 1.3 for GBP). Lots round down to the broker's step.\nfunction lotSize({ balance, riskPct, entry, stop, contract, usdPerUnit = 1, step = 0.01, min = 0.01 }) {\n  const riskMoney = (balance * riskPct) / 100;\n  const distance = Math.abs(entry - stop);\n  const riskPerLot = (distance * contract) / usdPerUnit; // account currency lost at the stop, per 1.00 lot\n  if (!(riskMoney > 0) || !(riskPerLot > 0)) return null;\n  const lots = Math.floor(riskMoney / riskPerLot / step + 1e-9) * step;\n  const rounded = Math.round(lots * 100) / 100;\n  const side = entry > stop ? 'long' : 'short';\n  const r = (k) => (side === 'long' ? entry + k * distance : entry - k * distance);\n  return {\n    side, riskMoney, distance, riskPerLot,\n    lots: rounded,\n    tooSmall: rounded < min,\n    actualRisk: rounded * riskPerLot,\n    perPoint: (rounded * contract) / usdPerUnit, // account currency per $1 move\n    targets: [1, 2, 3].map((k) => ({ r: k, price: r(k), profit: k * rounded * riskPerLot })),\n  };\n}\n\n// ------------------------------------------------------------- formatting\nconst fmtNum = (v, digits = 2) =>\n  Number.isFinite(v) ? v.toLocaleString('en-GB', { minimumFractionDigits: digits, maximumFractionDigits: digits }) : '—';\n\nfunction fmtDuration(seconds) {\n  if (!Number.isFinite(seconds)) return '—';\n  const m = Math.max(0, Math.round(seconds / 60));\n  const d = Math.floor(m / 1440);\n  const h = Math.floor((m % 1440) / 60);\n  if (d) return `${d}d ${h}h`;\n  return h ? `${h}h ${m % 60}m` : `${m % 60}m`;\n}\n\n// ------------------------------------------------------- probability engine\n// The model: over the rest of the trading day, log price moves like a trendless\n// random walk whose variance follows the market's own hour-of-day pattern (gold is\n// quiet in Asia and busy at the London and New York opens). Under that model the\n// reflection principle gives the chance of touching a level before the close.\n// calibrate() replays history out of sample to show how honest the numbers are.\n\n// Standard normal CDF (Abramowitz and Stegun 7.1.26, error below 1.5e-7).\nfunction normCdf(x) {\n  const z = Math.abs(x) / Math.SQRT2;\n  const t = 1 / (1 + 0.3275911 * z);\n  const erf = 1 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-z * z);\n  return x >= 0 ? (1 + erf) / 2 : (1 - erf) / 2;\n}\n\n// Variance of hourly log returns for each hour of the day (New York time), from\n// hourly bars. Thin hours are pulled towards the all-hours average.\nfunction volProfile(hourly, shrink = 5) {\n  const sums = new Array(24).fill(0);\n  const counts = new Array(24).fill(0);\n  for (let i = 1; i < hourly.length; i++) {\n    const a = hourly[i - 1];\n    const b = hourly[i];\n    if (b.t - a.t !== 3600 || !(a.c > 0) || !(b.c > 0)) continue; // skip breaks and weekends\n    const r = Math.log(b.c / a.c);\n    const h = nyHour(b.t);\n    sums[h] += r * r;\n    counts[h] += 1;\n  }\n  const n = counts.reduce((a, b) => a + b, 0);\n  const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;\n  return sums.map((s, h) => (s + shrink * overall) / (counts[h] + shrink));\n}\n\n// Expected variance of log price between two moments, hour by hour.\nfunction varianceBetween(profile, from, to) {\n  let v = 0;\n  for (let t = from; t < to;) {\n    const next = Math.min(to, (Math.floor(t / 3600) + 1) * 3600);\n    v += (profile[nyHour(t)] * (next - t)) / 3600;\n    t = next;\n  }\n  return v;\n}\n\n// When the current trading day ends: 17:00 New York for gold, midnight UTC for Bitcoin.\nfunction dayEnd(key, market) {\n  const [y, m, d] = key.split('-').map(Number);\n  if (market.day === 'utc') return Date.UTC(y, m - 1, d + 1) / 1000;\n  const naive = Date.UTC(y, m - 1, d, 17) / 1000;\n  return naive - nyOffset(naive);\n}\n\n// Chance of touching `level` before the close, with `variance` of log price left.\nfunction touchProb(price, level, variance) {\n  if (!(price > 0) || !(level > 0)) return null;\n  if (!(variance > 0)) return price === level ? 1 : 0;\n  const z = Math.abs(Math.log(level / price)) / Math.sqrt(variance);\n  return Math.min(1, 2 * (1 - normCdf(z)));\n}\n\n// Chance of closing beyond `level`, on its side of the price.\nfunction beyondProb(price, level, variance) {\n  if (!(variance > 0)) return 0;\n  return 1 - normCdf(Math.abs(Math.log(level / price)) / Math.sqrt(variance));\n}\n\n// The band that holds the close with a given probability (k = 1: 68%, k = 2: 95%).\nconst band = (price, variance, k) => [price * Math.exp(-k * Math.sqrt(variance)), price * Math.exp(k * Math.sqrt(variance))];\n\n// The widening cone from now to the close, every `step` seconds.\nfunction cone(price, profile, from, to, step = 900) {\n  const points = [];\n  let v = 0;\n  for (let t = from; t < to;) {\n    const next = Math.min(to, (Math.floor(t / step) + 1) * step);\n    v += varianceBetween(profile, t, next);\n    t = next;\n    const [l1, u1] = band(price, v, 1);\n    const [l2, u2] = band(price, v, 2);\n    points.push({ t, l1, u1, l2, u2 });\n  }\n  return points;\n}\n\n// Probabilities for each level that can still be reached today. Levels inside\n// today's range have already been touched.\nfunction levelOdds(levels, price, high, low, variance) {\n  return levels.map((l) => {\n    const touched = Number.isFinite(high) && Number.isFinite(low) && l.price <= high && l.price >= low;\n    return { ...l, side: l.price >= price ? 'above' : 'below', touched,\n      touch: touched ? 1 : touchProb(price, l.price, variance),\n      close: beyondProb(price, l.price, variance) };\n  });\n}\n\n// Descriptive state of the market from hourly bars: trend efficiency over the last\n// 24 hours (0 = choppy, 1 = one-way), momentum in standard deviations over 1, 4 and\n// 24 hours, and where the last 24 hours' volatility ranks against the history.\nfunction marketState(hourly, profile) {\n  const n = hourly.length;\n  if (n < 50) return null;\n  const closes = hourly.map((b) => b.c);\n  const last = closes[n - 1];\n  const window = closes.slice(-25);\n  let path = 0;\n  for (let i = 1; i < window.length; i++) path += Math.abs(window[i] - window[i - 1]);\n  const efficiency = path ? Math.abs(window[window.length - 1] - window[0]) / path : 0;\n  const hourVar = profile.reduce((a, b) => a + b, 0) / 24;\n  const momentum = (h) => Math.log(last / closes[n - 1 - h]) / Math.sqrt(hourVar * h);\n  const sq = [0];\n  for (let i = 1; i < n; i++) sq.push(sq[i - 1] + Math.log(closes[i] / closes[i - 1]) ** 2);\n  const rv = (i) => sq[i] - sq[i - 24];\n  const now = rv(n - 1);\n  const past = [];\n  for (let i = 24; i < n - 24; i += 6) past.push(rv(i));\n  const rank = past.filter((x) => x < now).length / past.length;\n  return { efficiency, momentum: { h1: momentum(1), h4: momentum(4), h24: momentum(24) }, volRank: rank, vol24: Math.sqrt(now) };\n}\n\n// Out-of-sample check of the touch probabilities on the previous day's high and low.\n// For each past day: a volatility profile from the `lookback` days before it only,\n// then at every hourly bar a forecast for each level not yet touched, scored against\n// what happened by the close.\n// One pass over the bars (it runs inside the Worker's CPU budget): the profile rolls\n// forward a day at a time, and the variance left to the close is a suffix sum.\nfunction calibrate(hourly, market, lookback = 20) {\n  const days = [];\n  for (let i = 0; i < hourly.length; i++) {\n    const b = hourly[i];\n    const a = hourly[i - 1];\n    const day = dayIndex(b.t, market);\n    const r2 = a && b.t - a.t === 3600 && a.c > 0 && b.c > 0 ? Math.log(b.c / a.c) ** 2 : null;\n    const bar = { ...b, hour: nyHour(b.t), r2 };\n    const last = days[days.length - 1];\n    if (last && last.day === day) last.bars.push(bar);\n    else days.push({ day, bars: [bar] });\n  }\n  const sums = new Array(24).fill(0);\n  const counts = new Array(24).fill(0);\n  const tally = (bars, sign) => {\n    for (const b of bars) if (b.r2 !== null) { sums[b.hour] += sign * b.r2; counts[b.hour] += sign; }\n  };\n  const pairs = [];\n  for (let d = 0; d < days.length - 1; d++) {\n    if (d > lookback) {\n      const n = counts.reduce((a, b) => a + b, 0);\n      const overall = n ? sums.reduce((a, b) => a + b, 0) / n : 0;\n      const profile = sums.map((s, h) => (s + 5 * overall) / (counts[h] + 5));\n      const prev = days[d - 1].bars;\n      let pdh = -Infinity;\n      let pdl = Infinity;\n      for (const b of prev) { pdh = Math.max(pdh, b.h); pdl = Math.min(pdl, b.l); }\n      const bars = days[d].bars;\n      const k = bars.length;\n      const highAfter = new Array(k);\n      const lowAfter = new Array(k);\n      const varAfter = new Array(k);\n      for (let i = k - 1; i >= 0; i--) {\n        highAfter[i] = Math.max(bars[i].h, i + 1 < k ? highAfter[i + 1] : -Infinity);\n        lowAfter[i] = Math.min(bars[i].l, i + 1 < k ? lowAfter[i + 1] : Infinity);\n        varAfter[i] = profile[bars[i].hour] + (i + 1 < k ? varAfter[i + 1] : 0);\n      }\n      let high = -Infinity;\n      let low = Infinity;\n      for (let i = 0; i < k; i++) {\n        const price = bars[i].o;\n        if (high < pdh && price < pdh) pairs.push([touchProb(price, pdh, varAfter[i]), highAfter[i] >= pdh ? 1 : 0]);\n        if (low > pdl && price > pdl) pairs.push([touchProb(price, pdl, varAfter[i]), lowAfter[i] <= pdl ? 1 : 0]);\n        high = Math.max(high, bars[i].h);\n        low = Math.min(low, bars[i].l);\n      }\n    }\n    // Roll the profile's window forward: this day in, the day `lookback` back out.\n    tally(days[d].bars, 1);\n    if (d - lookback >= 0) tally(days[d - lookback].bars, -1);\n  }\n  if (pairs.length < 50) return null;\n  const rate = pairs.reduce((a, [, o]) => a + o, 0) / pairs.length;\n  const brier = pairs.reduce((a, [p, o]) => a + (p - o) ** 2, 0) / pairs.length;\n  const reference = rate * (1 - rate); // always forecasting the average rate\n  const bins = [];\n  for (let k = 0; k < 5; k++) {\n    const lo = k / 5;\n    const hi = (k + 1) / 5;\n    const inside = pairs.filter(([p]) => p >= lo && (k === 4 ? p <= hi : p < hi));\n    if (!inside.length) continue;\n    bins.push({ lo, hi, n: inside.length,\n      predicted: inside.reduce((a, [p]) => a + p, 0) / inside.length,\n      observed: inside.reduce((a, [, o]) => a + o, 0) / inside.length });\n  }\n  return { days: days.length - 2 - lookback, n: pairs.length, brier, skill: reference ? 1 - brier / reference : 0, bins };\n}\n\n// Baseline odds for a trade on a trendless market: the chance the target comes\n// before the stop, and the typical time until one of them is hit.\nfunction tradeOdds(entry, stop, target, hourVar) {\n  const risk = Math.abs(entry - stop);\n  const reward = Math.abs(target - entry);\n  if (!(risk > 0) || !(reward > 0)) return null;\n  const sigma2 = hourVar * entry * entry; // price variance per hour\n  return { targetFirst: risk / (risk + reward), hours: sigma2 > 0 ? (risk * reward) / sigma2 : null };\n}\n\n// TCP Quant Terminal: the Playbook's maths, shared by the Worker and the page.\n// Pure functions, nothing stored. Times are Unix seconds (UTC); bars are\n// { t, o, h, l, c } with t the bar's open time, oldest first.\n//\n// A setup is a trade plan logged before its result: gold or Bitcoin, buy or sell,\n// a market, limit or stop order, an entry, a stop and one target, the reasons, and\n// the engine's read of the market at that moment. advanceSetup() walks it through\n// the bars that followed the way the orders would have filled, and settles every\n// doubt against the setup, so the record can only look worse than the truth:\n//   - a limit order fills at its price, never better;\n//   - a stop order, or a stop, that the market gaps through fills at the open;\n//   - on the bar an order fills, its stop counts and its target doesn't;\n//   - when one bar reaches both the stop and the target, the stop came first.\n// Results are in R, as the signal publisher counts them: the move from the fill to\n// the exit over the planned risk, |entry - stop|.\n//\n// Judging the record. If the market moves at random, a trade's expected result is\n// zero before costs, whatever its stop, target or management; its target comes\n// before its stop with odds risk / (risk + reward), the \"no-edge odds\". So an edge\n// is an average result, after costs, above zero by more than luck explains. The\n// band around the average is where the true average sits with 95% confidence\n// (Student's t), and the record gets a verdict only after PLAYBOOK.firstRead results.\n\nconst PLAYBOOK = {\n  spread: { XAUUSD: 0.3, BTCUSD: 20 }, // assumed round-trip cost, in price, taken off every result\n  scratch: 0.05, // a result within 0.05R of zero is a scratch, neither won nor lost\n  firstRead: 20, // results before the record gets a verdict\n  tagRead: 5, // results with a reason, market or session before it gets its own average\n  maxTags: 6,\n  minNote: 8,\n  maxNote: 400,\n  expiry: [4, 24, 168], // hours a limit or stop order can wait for its price\n  rr: [0.3, 20], // the target's distance, in R, that a plan may use\n};\n\nconst pbRound = (v, d) => Math.round(v * 10 ** d) / 10 ** d;\n\n// A result in R for posts and the page: +2.0R, −1.0R (a true minus sign).\nconst fmtR = (v, d = 1) => (Number.isFinite(v) ? (v > 0 ? '+' : v < 0 ? '−' : '') + fmtNum(Math.abs(v), d) + 'R' : '—');\n\n// ------------------------------------------------------------------ the plan\n// Tidies a plan and checks that it makes sense and, given the live `quote`\n// ({ price, atr, open }), that it's honest: a market order at the price now, a\n// limit or stop order on the right side of it. Returns { plan } or { error, field }.\nfunction checkPlan(input, quote) {\n  const p = input || {};\n  const market = MARKETS[p.symbol];\n  if (!market) return { error: 'Pick gold or Bitcoin.', field: 'symbol' };\n  if (p.side !== 'buy' && p.side !== 'sell') return { error: 'Pick buy or sell.', field: 'side' };\n  if (!['market', 'limit', 'stop'].includes(p.kind)) return { error: 'Pick a market, limit or stop order.', field: 'kind' };\n  const price = (v) => pbRound(typeof v === 'string' ? parseFloat(v.replace(/,/g, '')) : Number(v), market.digits);\n  const [entry, sl, tp] = [p.entry, p.sl, p.tp].map(price);\n  for (const [field, v, name] of [['entry', entry, 'entry'], ['sl', sl, 'stop'], ['tp', tp, 'target']]) {\n    if (!(v > 0)) return { error: `Enter the ${name} price.`, field };\n  }\n  const buy = p.side === 'buy';\n  if (buy ? !(sl < entry) : !(sl > entry)) return { error: `For a ${p.side}, the stop goes ${buy ? 'below' : 'above'} the entry.`, field: 'sl' };\n  if (buy ? !(tp > entry) : !(tp < entry)) return { error: `For a ${p.side}, the target goes ${buy ? 'above' : 'below'} the entry.`, field: 'tp' };\n  const rr = Math.abs(tp - entry) / Math.abs(entry - sl);\n  if (rr < PLAYBOOK.rr[0] || rr > PLAYBOOK.rr[1]) {\n    return { error: `The target is ${fmtNum(rr, 1)}R away: keep it between ${PLAYBOOK.rr[0]}R and ${PLAYBOOK.rr[1]}R.`, field: 'tp' };\n  }\n  const tags = [];\n  for (const raw of Array.isArray(p.tags) ? p.tags : []) {\n    const tag = String(raw).replace(/\\s+/g, ' ').trim().slice(0, 24).trim();\n    if (!tag || tags.some((t) => t.toLowerCase() === tag.toLowerCase())) continue;\n    if (!/^[\\p{L}\\p{N}][\\p{L}\\p{N} &+./'-]*$/u.test(tag)) return { error: `\"${tag}\": a reason is a few words (letters, numbers, & + . / ' -).`, field: 'tags' };\n    tags.push(tag);\n  }\n  if (tags.length > PLAYBOOK.maxTags) return { error: `Up to ${PLAYBOOK.maxTags} reasons.`, field: 'tags' };\n  const note = String(p.note || '').replace(/\\s+/g, ' ').trim();\n  if (note.length < PLAYBOOK.minNote) return { error: 'Say why, in a sentence: it goes out with the setup.', field: 'note' };\n  if (note.length > PLAYBOOK.maxNote) return { error: `Keep the why under ${PLAYBOOK.maxNote} characters.`, field: 'note' };\n  const pending = p.kind !== 'market';\n  const expiry = pending ? Number(p.expiry ?? 24) : null;\n  if (pending && !(Number.isInteger(expiry) && expiry >= 1 && expiry <= 168)) return { error: 'Pick how long the order waits for its price.', field: 'expiry' };\n  const plan = { symbol: market.symbol, side: p.side, kind: p.kind, entry, sl, tp, tags, note, expiry };\n  if (!quote || !(quote.price > 0)) return { plan };\n\n  const live = quote.price;\n  const f = (v) => fmtNum(v, market.digits);\n  if (p.kind === 'market') {\n    if (quote.open === false) return { error: `${market.name} is closed: use a limit or stop order, or wait for the open.`, field: 'kind' };\n    const tolerance = Math.max((quote.atr || 0) * 0.1, live * 0.0005);\n    if (Math.abs(entry - live) > tolerance) {\n      return { error: `The live price is ${f(live)}. A market order is logged at the price now; for another price, use a limit or stop order.`, field: 'entry' };\n    }\n    const pastStop = buy ? live <= sl : live >= sl;\n    const pastTarget = buy ? live >= tp : live <= tp;\n    if (pastStop || pastTarget) return { error: `The live price (${f(live)}) is already past the ${pastStop ? 'stop' : 'target'}.`, field: pastStop ? 'sl' : 'tp' };\n  } else {\n    // A buy limit or a sell stop waits below the price; a sell limit or a buy stop above it.\n    const want = (p.kind === 'limit') === buy ? 'below' : 'above';\n    if (entry === live || (want === 'below') !== entry < live) {\n      return { error: `A ${p.side} ${p.kind} goes ${want} the live price (${f(live)}).`, field: 'entry' };\n    }\n  }\n  return { plan };\n}\n\n// With no edge, the chance the target comes before the stop.\nfunction noEdgeOdds(s) {\n  const risk = Math.abs(s.entry - s.sl);\n  return risk / (risk + Math.abs(s.tp - s.entry));\n}\n\n// ------------------------------------------------------------------ the setup\n// A setup from a checked plan, logged at `at`. A market order is filled at once, at its\n// entry. The minute it was logged in isn't scanned: its prices may come from before it.\nfunction openSetup(plan, at) {\n  const market = plan.kind === 'market';\n  return {\n    symbol: plan.symbol, side: plan.side, kind: plan.kind, entry: plan.entry, sl: plan.sl, tp: plan.tp,\n    tags: plan.tags, note: plan.note, stop: plan.sl, created: at,\n    expires: market ? null : at + plan.expiry * 3600,\n    status: market ? 'open' : 'pending',\n    filled: market ? at : null, fill: market ? plan.entry : null,\n    closed: null, exit: null, r: null, reason: null,\n    checked: Math.ceil(at / 60) * 60,\n  };\n}\n\nconst isActive = (s) => s.status === 'pending' || s.status === 'open';\n\n// A result in R: from the fill to the exit, over the planned risk.\nfunction planR(s, exit) {\n  const move = s.side === 'buy' ? exit - s.fill : s.fill - exit;\n  return pbRound(move / Math.abs(s.entry - s.sl), 2);\n}\n\nfunction settleSetup(s, at, exit, reason) {\n  s.closed = at;\n  s.exit = exit;\n  s.r = planR(s, exit);\n  s.reason = reason;\n  s.status = s.r > PLAYBOOK.scratch ? 'won' : s.r < -PLAYBOOK.scratch ? 'lost' : 'scratch';\n  return { type: reason, at, price: exit, r: s.r };\n}\n\n// Which stop was hit: the planned one, one moved to the fill (breakeven), or one trailed elsewhere.\nconst stopReason = (s) => (s.stop === s.sl ? 'sl' : s.stop === s.fill ? 'be' : 'trail');\n\n// The price a pending order fills at on bar `b`, or null.\nfunction fillOf(s, b) {\n  const buy = s.side === 'buy';\n  if (s.kind === 'limit') return (buy ? b.l <= s.entry : b.h >= s.entry) ? s.entry : null;\n  if (buy) return b.h >= s.entry ? Math.max(s.entry, b.o) : null;\n  return b.l <= s.entry ? Math.min(s.entry, b.o) : null;\n}\n\nfunction expireSetup(s) {\n  s.status = 'expired';\n  s.closed = s.expires;\n  return { type: 'expired', at: s.expires };\n}\n\n// Walks a pending or open setup through `bars` of `step` seconds, from where it was last\n// checked up to the last bar that has finished by `now`. A coarser bar that started before\n// the last check still counts: nothing in its earlier part had touched anything, or the\n// setup would have closed then. Returns the setup as it now stands and what happened.\nfunction advanceSetup(setup, bars, now, step = 60) {\n  const s = { ...setup };\n  const events = [];\n  const buy = s.side === 'buy';\n  for (const b of bars) {\n    if (!isActive(s)) break;\n    if (b.t + step <= s.checked) continue;\n    if (b.t + step > now) break;\n    if (s.status === 'pending') {\n      if (s.expires != null && b.t >= s.expires) {\n        events.push(expireSetup(s));\n        break;\n      }\n      const fill = fillOf(s, b);\n      if (fill != null) {\n        s.status = 'open';\n        s.filled = b.t;\n        s.fill = fill;\n        events.push({ type: 'filled', at: b.t, price: fill });\n        if (buy ? b.l <= s.stop : b.h >= s.stop) events.push(settleSetup(s, b.t, s.stop, stopReason(s)));\n      }\n    } else if (buy ? b.l <= s.stop : b.h >= s.stop) {\n      const gapped = buy ? b.o < s.stop : b.o > s.stop;\n      events.push(settleSetup(s, b.t, gapped ? b.o : s.stop, stopReason(s)));\n    } else if (buy ? b.h >= s.tp : b.l <= s.tp) {\n      events.push(settleSetup(s, b.t, s.tp, 'tp'));\n    }\n    s.checked = b.t + step;\n  }\n  return { setup: s, events };\n}\n\n// A pending order whose time is up while its market was shut, so it can't have filled.\nfunction expireIfDue(setup, now) {\n  const s = { ...setup };\n  if (s.status !== 'pending' || s.expires == null || s.expires > now) return { setup: s, events: [] };\n  return { setup: s, events: [expireSetup(s)] };\n}\n\n// By hand: close an open setup at `price`, move its stop, or cancel an order that hasn't filled.\nfunction closeSetup(setup, at, price) {\n  const s = { ...setup };\n  return { setup: s, events: [settleSetup(s, at, price, 'manual')] };\n}\nfunction moveSetupStop(setup, at, price) {\n  return { setup: { ...setup, stop: price }, events: [{ type: 'stop', at, price }] };\n}\nfunction cancelSetup(setup, at) {\n  return { setup: { ...setup, status: 'cancelled', closed: at }, events: [{ type: 'cancelled', at }] };\n}\n\n// Where an open setup stands at `price`, in R.\nfunction setupLiveR(s, price) {\n  if (s.status !== 'open' || !(price > 0)) return null;\n  return (s.side === 'buy' ? price - s.fill : s.fill - price) / Math.abs(s.entry - s.sl);\n}\n\n// ----------------------------------------------------------------- the record\nconst DONE = ['won', 'lost', 'scratch'];\nconst isResult = (s) => DONE.includes(s.status);\n\n// A result after the assumed round-trip spread.\nconst netR = (s) => s.r - (PLAYBOOK.spread[s.symbol] || 0) / Math.abs(s.entry - s.sl);\n\n// The 97.5th percentile of Student's t with `df` degrees of freedom: a 95% two-sided band.\nconst T975 = [12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.16, 2.145, 2.131,\n  2.12, 2.11, 2.101, 2.093, 2.086, 2.08, 2.074, 2.069, 2.064, 2.06, 2.056, 2.052, 2.048, 2.045, 2.042];\nfunction t975(df) {\n  if (df <= T975.length) return T975[df - 1];\n  const z = 1.959964; // beyond the table, the Cornish-Fisher expansion (exact to 3 decimals)\n  return z + (z ** 3 + z) / (4 * df) + (5 * z ** 5 + 16 * z ** 3 + 3 * z) / (96 * df * df);\n}\n\n// The 95% band for a true average, from `n` results with this mean and sum of squared deviations.\nfunction meanBand(n, mean, ss) {\n  if (n < 3) return null;\n  const half = t975(n - 1) * Math.sqrt(ss / (n - 1) / n);\n  return [mean - half, mean + half];\n}\n\n// Wilson's 95% band for a proportion, k of n.\nfunction wilsonBand(k, n) {\n  if (!n) return null;\n  const z = 1.959964;\n  const p = k / n;\n  const z2 = z * z;\n  const mid = (p + z2 / (2 * n)) / (1 + z2 / n);\n  const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / (1 + z2 / n);\n  return [Math.max(0, mid - half), Math.min(1, mid + half)];\n}\n\nfunction groupResults(done, keysOf) {\n  const groups = new Map();\n  for (const s of done) {\n    for (const label of keysOf(s)) {\n      const key = String(label).toLowerCase();\n      const g = groups.get(key) || { key: label, n: 0, sum: 0, won: 0, lost: 0 };\n      g.n += 1;\n      g.sum += netR(s);\n      if (s.status === 'won') g.won += 1;\n      if (s.status === 'lost') g.lost += 1;\n      groups.set(key, g);\n    }\n  }\n  return [...groups.values()]\n    .map((g) => ({ key: g.key, n: g.n, avg: pbRound(g.sum / g.n, 3), won: g.won, lost: g.lost }))\n    .sort((a, b) => b.n - a.n || String(a.key).localeCompare(String(b.key)));\n}\n\n// The record, from every setup: counts, the average after costs with its band, the\n// verdict, the curve of how the average settled as results came in, target-before-stop\n// against the no-edge odds, and averages by reason, market and session.\nfunction recordStats(setups) {\n  const done = setups.filter(isResult).sort((a, b) => a.closed - b.closed || a.n - b.n);\n  const curve = [];\n  let n = 0;\n  let mean = 0;\n  let ss = 0;\n  let total = 0;\n  let peak = 0;\n  let drawdown = 0;\n  for (const s of done) {\n    const x = netR(s);\n    n += 1;\n    const d = x - mean;\n    mean += d / n;\n    ss += d * (x - mean);\n    total += x;\n    peak = Math.max(peak, total);\n    drawdown = Math.max(drawdown, peak - total);\n    const band = meanBand(n, mean, ss);\n    curve.push({ n: s.n, r: pbRound(x, 3), mean: pbRound(mean, 3), band: band && band.map((v) => pbRound(v, 3)), status: s.status });\n  }\n  const band = meanBand(n, mean, ss);\n  const clean = done.filter((s) => s.reason === 'tp' || s.reason === 'sl');\n  const hits = clean.filter((s) => s.reason === 'tp').length;\n  const count = (status) => setups.filter((s) => s.status === status).length;\n  return {\n    setups: setups.length,\n    open: count('open'),\n    pending: count('pending'),\n    results: n,\n    won: count('won'),\n    lost: count('lost'),\n    scratch: count('scratch'),\n    avg: n ? pbRound(mean, 3) : null,\n    total: pbRound(total, 2),\n    band: band && band.map((v) => pbRound(v, 3)),\n    drawdown: pbRound(drawdown, 2),\n    firstRead: PLAYBOOK.firstRead,\n    verdict: n < PLAYBOOK.firstRead || !band ? 'collecting' : band[0] > 0 ? 'ahead' : band[1] < 0 ? 'behind' : 'unclear',\n    targetFirst: {\n      n: clean.length,\n      hits,\n      band: wilsonBand(hits, clean.length),\n      noEdge: clean.length ? pbRound(clean.reduce((a, s) => a + noEdgeOdds(s), 0) / clean.length, 3) : null,\n    },\n    byTag: groupResults(done, (s) => s.tags || []),\n    byMarket: groupResults(done, (s) => [s.symbol]),\n    bySession: groupResults(done, (s) => (s.engine && s.engine.sessions) || []),\n    curve,\n  };\n}\n\n// One line for posts: where the record stands.\nfunction recordLine(st) {\n  if (!st || !st.results) return 'The first result starts the record.';\n  return `Record: ${st.results} result${st.results === 1 ? '' : 's'} · ${st.won} won · ${st.lost} lost` +\n    `${st.scratch ? ` · ${st.scratch} scratch` : ''} · average ${fmtR(st.avg, 2)} after costs`;\n}\n\n// TCP Quant Terminal: session briefs, the maths shared by the Worker and the page.\n//\n// Before each session opens, Lewis sends TCP AI his charts. It reads them and drafts the zones\n// to watch and a plan; Lewis checks and edits the draft, and only then does it post. After the\n// session, what price did at each zone is measured, and the record says which zones matter:\n//   reach  how often price got to a zone, against the engine's odds of it getting there if it\n//          moved at random (a zone that draws price in beats them);\n//   turn   from the bar that reached a zone, how far price went back the way it came against\n//          how far it went on through, in average daily ranges. Both are measured from that\n//          bar's close over the same bars, so on a random walk they are equal on average: a zone\n//          that holds price back shows a turn above zero.\n// Zones are prices Lewis chooses; nothing here says how to find them.\n\nconst BRIEF = {\n  sessions: [\n    { id: 'asia', name: 'Asia', city: 'Tokyo', session: 'tokyo', icon: '🌏' },\n    { id: 'london', name: 'London', city: 'London', session: 'london', icon: '🌍' },\n    { id: 'newyork', name: 'New York', city: 'New York', session: 'newyork', icon: '🌎' },\n  ],\n  timeframes: ['5M', '15M', '30M', '1H', '4H'], // asked for before each session\n  weekly: '1D', // and the daily chart before the week's first session\n  kinds: { demand: 'Demand', supply: 'Supply', liquidity: 'Liquidity', level: 'Level' },\n  maxCharts: 6,\n  maxZones: 6,\n  lead: 45, // minutes before the open that the reminder goes out\n  leads: [30, 45, 60],\n  late: 3600, // a new brief is for a session that opened this recently, or else the next\n  firstRead: 20, // zones reached before the record gives a verdict\n  text: { headline: 120, reason: 240, plan: 900, note: 600, label: 40, why: 200, lesson: 400, guide: 6000 },\n};\n\nconst brRound = (v, d = 2) => (Number.isFinite(v) ? Math.round(v * 10 ** d) / 10 ** d : null);\nconst briefClip = (v, max) => String(v ?? '').replace(/\\s+/g, ' ').trim().slice(0, max);\nconst brKey = (z) => `${z.y}-${String(z.m).padStart(2, '0')}-${String(z.d).padStart(2, '0')}`;\nconst brShift = (key, n) => new Date(Date.parse(key + 'T00:00:00Z') + n * 864e5).toISOString().slice(0, 10);\nconst brWeekday = (key) => new Date(key + 'T00:00:00Z').getUTCDay(); // 0 Sunday ... 6 Saturday\nconst briefSession = (id) => BRIEF.sessions.find((s) => s.id === id) || null;\n\n// ------------------------------------------------------------------ schedule\n// A session's window on a date never changes, so each is worked out once (the time-zone\n// arithmetic is the slow part, and the Worker has 10 ms of CPU a request).\nconst brKnown = new Map();\nfunction brSessionWindow(s, key) {\n  const id = `${s.id}|${key}`;\n  let w = brKnown.get(id);\n  if (!w) {\n    if (brKnown.size > 400) brKnown.clear();\n    brKnown.set(id, (w = sessionWindow(s, key)));\n  }\n  return w;\n}\n\n// Each session's windows from yesterday to `days` ahead, Monday to Friday in its own city\n// (the terminal's session clock). The week's first is Asia on Monday: its brief also asks\n// for the daily chart.\nfunction briefWindows(now, days = 8) {\n  const out = [];\n  for (const b of BRIEF.sessions) {\n    const s = SESSIONS.find((x) => x.id === b.session);\n    const today = brKey(zoned(now, s.tz));\n    for (let i = -1; i <= days; i++) {\n      const key = brShift(today, i);\n      const wd = brWeekday(key);\n      if (wd === 0 || wd === 6) continue;\n      const { from, to } = brSessionWindow(s, key);\n      out.push({ id: b.id, name: b.name, key, open: from, close: to, weekly: b.id === 'asia' && wd === 1 });\n    }\n  }\n  return out.sort((a, b) => a.open - b.open);\n}\n\n// The session a new brief is for: one that opened in the last hour, or else the next to open.\nconst briefDefault = (now) => briefWindows(now).find((w) => w.open > now - BRIEF.late) || null;\n\n// A named session's window for a brief made now: the one running, or else the next.\nconst briefWindow = (id, now) => briefWindows(now).find((w) => w.id === id && w.close > now) || null;\n\n// Sessions whose reminder (`lead` minutes before the open) fell due in the last `span` seconds.\n// The check runs every 5 minutes; the Worker keeps each reminder to one send.\nfunction briefReminders(now, lead = BRIEF.lead, span = 900) {\n  return briefWindows(now, 2).filter((w) => w.open - lead * 60 <= now && w.open - lead * 60 > now - span);\n}\n\n// The charts to ask for before a session.\nconst briefAsk = (w) => (w && w.weekly ? [...BRIEF.timeframes, BRIEF.weekly] : [...BRIEF.timeframes]);\n\n// --------------------------------------------------------------------- zones\n// Checks zones from TCP AI or the poster before they're kept: a known kind, real prices within\n// eight average days of the market, low below high (a single price is a level), rounded to the\n// market's decimals, no wider than three average days, no repeats, and at most maxZones, the\n// nearest to the price. Returns them highest first, with what was dropped and why.\nfunction cleanZones(list, { symbol, price, atr }) {\n  const m = MARKETS[symbol];\n  const day = Number.isFinite(atr) && atr > 0 ? atr : Number.isFinite(price) ? price * 0.01 : null;\n  const zones = [];\n  const dropped = [];\n  for (const z of Array.isArray(list) ? list : []) {\n    if (!z || typeof z !== 'object') continue;\n    const num = (v) => (v === null || v === '' || v === undefined ? NaN : Number(String(v).replace(/,/g, '')));\n    let low = num(z.low);\n    let high = num(z.high);\n    if (!Number.isFinite(high)) high = low;\n    if (!Number.isFinite(low)) low = high;\n    const label = briefClip(z.label, BRIEF.text.label);\n    const name = label || `${z.low ?? ''}`;\n    if (!Object.hasOwn(BRIEF.kinds, z.kind)) { dropped.push({ zone: name, why: 'unknown kind' }); continue; }\n    if (!(low > 0) || !(high > 0)) { dropped.push({ zone: name, why: 'no price' }); continue; }\n    if (low > high) [low, high] = [high, low];\n    low = brRound(low, m.digits);\n    high = brRound(high, m.digits);\n    if (day && Number.isFinite(price) && (high < price - 8 * day || low > price + 8 * day)) { dropped.push({ zone: name, why: 'too far from the price' }); continue; }\n    if (day && high - low > 3 * day) { dropped.push({ zone: name, why: 'too wide' }); continue; }\n    if (zones.some((y) => y.low === low && y.high === high && y.kind === z.kind)) continue;\n    zones.push({ kind: z.kind, low, high, tf: briefClip(z.tf ?? z.timeframe, 12), label, why: briefClip(z.why, BRIEF.text.why) });\n  }\n  if (zones.length > BRIEF.maxZones && Number.isFinite(price)) {\n    zones.sort((a, b) => Math.abs(zoneEdge(a, price) - price) - Math.abs(zoneEdge(b, price) - price));\n    for (const z of zones.splice(BRIEF.maxZones)) dropped.push({ zone: z.label || String(z.low), why: `more than ${BRIEF.maxZones} zones` });\n  }\n  zones.splice(BRIEF.maxZones);\n  zones.sort((a, b) => b.high - a.high || b.low - a.low);\n  return { zones, dropped };\n}\n\n// Where a zone sits from `price`: below it, above it, or around it.\nconst zoneSide = (z, price) => (price > z.high ? 'below' : price < z.low ? 'above' : 'inside');\n// The part of a zone price reaches first: its top from above, its bottom from below.\nconst zoneEdge = (z, price) => (price > z.high ? z.high : price < z.low ? z.low : price);\n// The engine's odds of price reaching a zone with `variance` of log price to go, moving at random.\nconst zoneOdds = (z, price, variance) => (zoneSide(z, price) === 'inside' ? 1 : touchProb(price, zoneEdge(z, price), variance));\n\n// ------------------------------------------------------------------- review\n// What price did at a zone after the brief went out. `from` is when it was posted (the bar\n// that was forming then is left out: part of it came before), `to` is when the session closed\n// (only bars finished by then count). The first bar to reach the zone marks it reached; from\n// that bar's close, `away` is the furthest price then went back the way it came and `through`\n// the furthest it went on, over the same later bars. `turn` is away less through, in average\n// daily ranges. A zone price was already inside when the brief went out is left out.\nfunction reviewZone(z, bars, { from, to, price, atr, step = 60 }) {\n  const side = zoneSide(z, price);\n  if (side === 'inside') return { side, reached: null };\n  let touch = null;\n  let away = 0;\n  let through = 0;\n  for (const b of bars) {\n    if (b.t < from) continue;\n    if (b.t + step > to) break;\n    if (!touch) {\n      if (side === 'below' ? b.l <= z.high : b.h >= z.low) touch = { at: b.t, close: b.c };\n      continue;\n    }\n    const c = touch.close;\n    if (side === 'below') {\n      away = Math.max(away, b.h - c);\n      through = Math.max(through, c - b.l);\n    } else {\n      away = Math.max(away, c - b.l);\n      through = Math.max(through, b.h - c);\n    }\n  }\n  if (!touch) return { side, reached: false };\n  const digits = 5;\n  return {\n    side, reached: true, at: touch.at, close: touch.close, away: brRound(away, digits), through: brRound(through, digits),\n    turn: atr > 0 ? brRound((away - through) / atr, 3) : null,\n  };\n}\n\n// Every zone of a brief, reviewed; and the count for the wrap.\nfunction reviewBrief(zones, bars, window) {\n  const out = zones.map((z) => ({ ...z, review: reviewZone(z, bars, window) }));\n  const counted = out.filter((z) => z.review.reached !== null);\n  return {\n    zones: out,\n    counted: counted.length,\n    reached: counted.filter((z) => z.review.reached).length,\n    expected: brRound(counted.reduce((a, z) => a + (Number.isFinite(z.odds) ? z.odds : 0), 0), 2),\n  };\n}\n\n// -------------------------------------------------------------------- record\nfunction brGroup(rows, keyOf) {\n  const groups = new Map();\n  for (const r of rows) {\n    const key = keyOf(r);\n    const g = groups.get(key) || { key, zones: 0, reached: 0, expected: 0, turns: [] };\n    g.zones += 1;\n    g.expected += r.odds;\n    if (r.review.reached) {\n      g.reached += 1;\n      if (r.review.turn != null) g.turns.push(r.review.turn);\n    }\n    groups.set(key, g);\n  }\n  return [...groups.values()]\n    .map((g) => ({ key: g.key, zones: g.zones, reached: g.reached, expected: brRound(g.expected, 1),\n      turn: g.turns.length ? brRound(g.turns.reduce((a, b) => a + b, 0) / g.turns.length, 3) : null, turns: g.turns.length }))\n    .sort((a, b) => b.zones - a.zones || String(a.key).localeCompare(String(b.key)));\n}\n\n// The record from every reviewed brief that counts (test briefs don't): zones, how many were\n// reached against the random walk's expectation, and the average turn with its 95% band. The\n// verdict waits for firstRead reached zones: the whole band above zero means zones turned price\n// more than chance would, below zero that price went through them more.\nfunction briefStats(briefs) {\n  const rows = [];\n  let reviewed = 0;\n  for (const b of [...briefs].sort((x, y) => (x.posted || 0) - (y.posted || 0))) {\n    if (b.test || !b.review) continue;\n    reviewed += 1;\n    for (const z of b.review.zones || []) {\n      if (!z.review || z.review.reached === null || z.review.reached === undefined) continue;\n      rows.push({ ...z, odds: Number.isFinite(z.odds) ? z.odds : 0, session: b.session, symbol: b.symbol });\n    }\n  }\n  const reached = rows.filter((r) => r.review.reached);\n  const expected = rows.reduce((a, r) => a + r.odds, 0);\n  let n = 0;\n  let mean = 0;\n  let ss = 0;\n  const curve = [];\n  for (const r of reached) {\n    if (r.review.turn == null) continue;\n    const x = r.review.turn;\n    n += 1;\n    const d = x - mean;\n    mean += d / n;\n    ss += d * (x - mean);\n    const band = meanBand(n, mean, ss);\n    curve.push({ turn: x, mean: brRound(mean, 3), band: band && band.map((v) => brRound(v, 3)) });\n  }\n  const band = meanBand(n, mean, ss);\n  return {\n    briefs: reviewed,\n    zones: rows.length,\n    reached: reached.length,\n    expected: brRound(expected, 1),\n    reach: { rate: rows.length ? brRound(reached.length / rows.length, 3) : null, band: wilsonBand(reached.length, rows.length),\n      noEdge: rows.length ? brRound(expected / rows.length, 3) : null },\n    turn: { n, avg: n ? brRound(mean, 3) : null, band: band && band.map((v) => brRound(v, 3)) },\n    firstRead: BRIEF.firstRead,\n    verdict: n < BRIEF.firstRead || !band ? 'collecting' : band[0] > 0 ? 'turning' : band[1] < 0 ? 'breaking' : 'unclear',\n    byKind: brGroup(rows, (r) => r.kind),\n    bySession: brGroup(rows, (r) => r.session),\n    curve,\n  };\n}\n\n// TCP Quant Terminal: the page's Playbook. build.mjs puts lib.js and playbook-lib.js in front\n// of this file and app.js after it, all in one script. Nothing here runs on load: the\n// functions use app.js's helpers ($, call, tg, demo, quoteOf, ...) when they're called, and\n// app.js calls pbInit() once the member is signed in.\n\nconst pb = {\n  data: null, // the last answer from /api/playbook\n  at: 0, // when it came\n  loading: null,\n  opened: new Set(), // history rows showing their detail\n  rows: 12, // history rows shown\n  form: { symbol: 'XAUUSD', side: 'buy', kind: 'market', expiry: 24, tags: [], photo: null, liveEntry: true },\n  busy: false,\n  curve: { drawn: '', hover: null, anim: 0 },\n  photos: {}, // setup number -> object URL of its chart\n  toastTimer: 0,\n};\nconst pbEsc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\nconst pbDate = (t) => new Date(t * 1000).toLocaleDateString([], { day: 'numeric', month: 'short' });\nconst pbKind = (s) => (s.kind === 'market' ? '' : ` ${s.kind.toUpperCase()}`);\nconst PB_SESSIONS = { sydney: 'Sydney session', tokyo: 'Tokyo session', london: 'London session', newyork: 'New York session' };\n\n// ------------------------------------------------------------------- data\nasync function pbSend(path, body) {\n  const form = body instanceof FormData;\n  const res = await fetch(path, {\n    method: 'POST',\n    headers: { authorization: 'tma ' + (tg ? tg.initData : ''), ...(form ? {} : { 'content-type': 'application/json' }) },\n    body: form ? body : JSON.stringify(body),\n  });\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw Object.assign(new Error(data.message || 'Something went wrong. Try again.'), { code: data.error, field: data.field });\n  return data;\n}\n\n// One load at a time; a forced reload asked for during one runs after it.\nfunction pbLoad(force = false) {\n  if (!force && pb.data && !pb.data.error && clock() - pb.at < 30) return Promise.resolve();\n  if (pb.loading) return force ? pb.loading.then(() => pbLoad(true)) : pb.loading;\n  pb.loading = (async () => {\n    try {\n      pb.data = demo ? pbDemo() : await call('/api/playbook');\n      pb.at = clock();\n    } catch (err) {\n      if (!pb.data || pb.data.error) pb.data = { error: err.message };\n    }\n    pbRender();\n  })().finally(() => { pb.loading = null; });\n  return pb.loading;\n}\n\n// Setups on a market other than the one on screen still need its prices for their live R.\nfunction pbPrices() {\n  const d = pb.data;\n  if (!d || !d.setups) return;\n  for (const symbol of new Set(d.setups.filter(isActive).map((s) => s.symbol))) {\n    if (!state.data[symbol] || clock() - (state.data[symbol].updated || 0) > 90) loadMarket(symbol);\n  }\n}\n\n// ----------------------------------------------------------------- render\nfunction pbFab() {\n  const poster = !!(pb.data && pb.data.canPost && pb.data.ready);\n  const show = poster && !$('signals').hidden;\n  $('pbNew').hidden = !show;\n  $('pbExport').hidden = !poster;\n  document.body.classList.toggle('with-fab', show || !$('brNew').hidden);\n}\n\n// Posters: the bot sends the whole record as a file (JSON lines, the chain checked).\nasync function pbExport() {\n  if (demo) return pbToast('Demo: there is no record to send.');\n  $('pbExport').disabled = true;\n  try {\n    const res = await pbSend('/api/playbook/export', {});\n    pbToast(`Sent to you in Telegram: ${res.setups} setups, ${res.entries} entries, ${res.intact ? 'chain intact' : `chain broken at entry ${res.brokenAt}`}.`);\n  } catch (err) {\n    pbToast(err.message);\n  } finally {\n    $('pbExport').disabled = false;\n  }\n}\n\nfunction pbRender() {\n  const d = pb.data;\n  pbFab();\n  pbMemory();\n  if (!d) return;\n  const quiet = (tag, text) => {\n    $('pbTag').textContent = tag;\n    $('pbBody').hidden = true;\n    $('pbEmpty').hidden = false;\n    $('pbEmpty').textContent = text;\n  };\n  if (d.error) {\n    quiet('offline', d.error);\n    for (const id of ['pbHistoryCard', 'pbReadsCard']) $(id).hidden = true;\n    $('pbActive').innerHTML = '';\n    return;\n  }\n  if (!d.ready) {\n    quiet('starts soon', \"The Playbook opens soon: Lewis's setups, logged before the result, with every result tracked to the end.\");\n    return;\n  }\n  const st = d.stats;\n  const tag = d.canPost && d.mode !== 'live' ? 'test mode' : st.setups ? `${st.setups} logged` : d.canPost ? 'ready' : 'starts soon';\n  if (!st.setups) {\n    quiet(tag, d.canPost\n      ? d.mode === 'live' ? 'Nothing logged yet. Tap + LOG A SETUP: it goes to the Inner Circle and its result is tracked to the end.'\n        : 'Test mode: setups you log go to the team group only and stay out of this record. Switch PLAYBOOK_MODE to live when you are ready.'\n      : 'No setups yet. When Lewis logs one, it appears here and in the Inner Circle, and its result is tracked to the end.');\n  } else {\n    $('pbTag').textContent = tag;\n    $('pbBody').hidden = false;\n    $('pbEmpty').hidden = true;\n    $('pbResults').textContent = st.results;\n    $('pbWL').textContent = `${st.won} · ${st.lost}`;\n    $('pbAvg').textContent = fmtR(st.avg, 2);\n    $('pbTotal').textContent = st.results ? fmtR(st.total, 1) : '—';\n    const v = pbVerdict(st);\n    $('pbVerdict').className = `pb-verdict ${v.cls}`;\n    $('pbVerdict').innerHTML = `<span class=\"icon\" aria-hidden=\"true\">${v.icon}</span><div><b>${v.title}</b><span>${v.text}</span></div>` +\n      (v.progress != null ? `<div class=\"pb-progress\"><i style=\"width:${Math.round(v.progress * 100)}%\"></i></div>` : '');\n    const tf = st.targetFirst;\n    $('pbFirst').innerHTML = tf.n\n      ? `Target before stop: <b>${tf.hits} of ${tf.n}</b> (${Math.round((tf.hits / tf.n) * 100)}%), where no edge would give <b>${pct(tf.noEdge)}</b> for the same stops and targets.`\n      : '';\n    pbCurve();\n  }\n  pbActive();\n  pbHistory();\n  pbReads();\n  pbLive();\n}\n\nfunction pbVerdict(st) {\n  const n = st.results;\n  if (st.verdict === 'collecting') {\n    return { cls: 'collecting', icon: n, progress: n / st.firstRead, title: `Collecting: ${n} of ${st.firstRead}`,\n      text: `The first read comes at ${st.firstRead} results. Until then, any average is mostly luck.` };\n  }\n  const band = `${fmtR(st.band[0], 2)} to ${fmtR(st.band[1], 2)}`;\n  if (st.verdict === 'ahead') return { cls: 'ahead', icon: '▲', title: 'Ahead of no edge', text: `After ${n} results the whole band (${band}) is above zero: early evidence of an edge, tested again with every setup.` };\n  if (st.verdict === 'behind') return { cls: 'behind', icon: '▼', title: 'Behind no edge', text: `After ${n} results the whole band (${band}) is below zero.` };\n  return { cls: 'unclear', icon: '≈', title: 'Too close to call', text: `After ${n} results the band (${band}) still spans zero: no edge shown either way yet.` };\n}\n\n// The chart: the average result after each close (the line), the band the true average\n// likely sits in (95%), and each result as a dot, filled if won and hollow if lost.\nfunction pbCurve() {\n  if ($('signals').hidden) return; // drawn (and animated) when the tab opens\n  const pts = pb.data.stats.curve;\n  const key = pts.map((p) => `${p.n}:${p.mean}`).join(',');\n  if (key === pb.curve.drawn) return pbDraw(1);\n  pb.curve.drawn = key;\n  cancelAnimationFrame(pb.curve.anim);\n  if (reduceMotion) return pbDraw(1);\n  const began = performance.now();\n  const step = (ts) => {\n    const t = Math.min(1, (ts - began) / 900);\n    pbDraw(1 - (1 - t) ** 3);\n    if (t < 1) pb.curve.anim = requestAnimationFrame(step);\n  };\n  pb.curve.anim = requestAnimationFrame(step);\n}\n\nfunction pbGeometry() {\n  const cv = $('pbCurve');\n  const w = cv.clientWidth;\n  const h = cv.clientHeight;\n  const pts = pb.data.stats.curve;\n  const pad = { l: 36, r: 56, t: 10, b: 22 };\n  // The scale follows the results and the average; the early band, wide on a few results,\n  // is cut off at the edges rather than squeezing everything else flat.\n  let lo = -1.5;\n  let hi = 1.5;\n  for (const p of pts) {\n    lo = Math.min(lo, p.mean - 0.3, Math.max(p.r, -2.5) - 0.3);\n    hi = Math.max(hi, p.mean + 0.3, Math.min(p.r, 3.5) + 0.3);\n  }\n  lo = Math.max(Math.floor(lo * 2) / 2, -3);\n  hi = Math.min(Math.ceil(hi * 2) / 2, 4);\n  const n = pts.length;\n  return {\n    w, h, pad, lo, hi, n, pts,\n    x: (i) => pad.l + (n <= 1 ? (w - pad.l - pad.r) / 2 : (i / (n - 1)) * (w - pad.l - pad.r)),\n    y: (v) => pad.t + ((hi - Math.min(hi, Math.max(lo, v))) / (hi - lo)) * (h - pad.t - pad.b),\n  };\n}\n\nfunction pbDraw(progress) {\n  const cv = $('pbCurve');\n  if (!pb.data || !pb.data.stats || !cv.clientWidth) return;\n  const g = pbGeometry();\n  const dpr = Math.min(window.devicePixelRatio || 1, 3);\n  if (cv.width !== Math.round(g.w * dpr) || cv.height !== Math.round(g.h * dpr)) {\n    cv.width = Math.round(g.w * dpr);\n    cv.height = Math.round(g.h * dpr);\n  }\n  const ctx = cv.getContext('2d');\n  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  ctx.clearRect(0, 0, g.w, g.h);\n  const right = g.w - g.pad.r;\n  ctx.font = '500 10px \"JetBrains Mono\", ui-monospace, monospace';\n  ctx.textBaseline = 'middle';\n  // hairline grid on whole R, and the zero line a step brighter: no edge\n  for (let v = Math.ceil(g.lo); v <= Math.floor(g.hi); v++) {\n    const yy = Math.round(g.y(v)) + 0.5;\n    ctx.strokeStyle = v === 0 ? '#5A5346' : '#26231C';\n    ctx.lineWidth = 1;\n    ctx.beginPath();\n    ctx.moveTo(g.pad.l, yy);\n    ctx.lineTo(right, yy);\n    ctx.stroke();\n    ctx.fillStyle = '#8A8274';\n    ctx.textAlign = 'right';\n    ctx.fillText(v === 0 ? '0R' : `${v > 0 ? '+' : '−'}${Math.abs(v)}R`, g.pad.l - 6, yy);\n  }\n  ctx.textAlign = 'left';\n  ctx.fillStyle = '#8A8274';\n  ctx.fillText('no edge', right + 6, g.y(0) + (g.n && Math.abs(g.y(g.pts[g.n - 1].mean) - g.y(0)) < 12 ? 11 : 0));\n  // x axis: result numbers at the ends\n  ctx.textBaseline = 'alphabetic';\n  if (g.n) {\n    ctx.textAlign = 'left';\n    ctx.fillText('1st result', g.pad.l, g.h - 4);\n    if (g.n > 1) { ctx.textAlign = 'right'; ctx.fillText(`${ordinal(g.n)}`, right, g.h - 4); }\n  }\n  if (!g.n) {\n    ctx.textAlign = 'center';\n    ctx.fillStyle = '#A69D8C';\n    ctx.font = '400 13px Archivo, system-ui, sans-serif';\n    ctx.fillText('The first result starts the line.', (g.pad.l + right) / 2, g.y(0) - 14);\n    return;\n  }\n  const m = Math.max(1, Math.round(g.n * progress));\n  // the band, clipped to the plot\n  const banded = [];\n  for (let i = 0; i < m; i++) if (g.pts[i].band) banded.push(i);\n  if (banded.length > 1) {\n    const top = g.pad.t;\n    const bottom = g.h - g.pad.b;\n    const clampY = (v) => Math.max(top, Math.min(bottom, g.y(v)));\n    ctx.beginPath();\n    banded.forEach((i, k) => (k ? ctx.lineTo(g.x(i), clampY(g.pts[i].band[1])) : ctx.moveTo(g.x(i), clampY(g.pts[i].band[1]))));\n    for (let k = banded.length - 1; k >= 0; k--) ctx.lineTo(g.x(banded[k]), clampY(g.pts[banded[k]].band[0]));\n    ctx.closePath();\n    ctx.fillStyle = 'rgba(216,173,78,0.16)';\n    ctx.fill();\n  }\n  // each result: context, so muted\n  for (let i = 0; i < m; i++) {\n    const p = g.pts[i];\n    ctx.beginPath();\n    ctx.arc(g.x(i), g.y(Math.max(-2.5, Math.min(3.5, p.r))), 3.5, 0, Math.PI * 2);\n    if (p.status === 'lost') {\n      ctx.strokeStyle = 'rgba(224,97,63,0.85)';\n      ctx.lineWidth = 1.6;\n      ctx.stroke();\n    } else {\n      ctx.fillStyle = p.status === 'won' ? 'rgba(53,166,140,0.8)' : 'rgba(138,130,116,0.9)';\n      ctx.fill();\n    }\n  }\n  // the average: the accent\n  ctx.beginPath();\n  for (let i = 0; i < m; i++) (i ? ctx.lineTo(g.x(i), g.y(g.pts[i].mean)) : ctx.moveTo(g.x(i), g.y(g.pts[i].mean)));\n  ctx.strokeStyle = '#D8AD4E';\n  ctx.lineWidth = 2;\n  ctx.lineJoin = 'round';\n  ctx.lineCap = 'round';\n  ctx.stroke();\n  const end = g.pts[m - 1];\n  ctx.beginPath();\n  ctx.arc(g.x(m - 1), g.y(end.mean), 4.5, 0, Math.PI * 2);\n  ctx.fillStyle = '#D8AD4E';\n  ctx.fill();\n  ctx.lineWidth = 2;\n  ctx.strokeStyle = '#16140F';\n  ctx.stroke();\n  if (m === g.n) {\n    ctx.textAlign = 'left';\n    ctx.textBaseline = 'middle';\n    ctx.fillStyle = '#F2ECDF';\n    ctx.font = '600 11px \"JetBrains Mono\", ui-monospace, monospace';\n    ctx.fillText(fmtR(end.mean, 2), right + 6, g.y(end.mean) + (Math.abs(g.y(end.mean) - g.y(0)) < 12 ? -6 : 0));\n  }\n  // the crosshair\n  const hi = pb.curve.hover;\n  if (hi != null && hi < m) {\n    const xx = Math.round(g.x(hi)) + 0.5;\n    ctx.strokeStyle = 'rgba(242,236,223,0.35)';\n    ctx.lineWidth = 1;\n    ctx.beginPath();\n    ctx.moveTo(xx, g.pad.t);\n    ctx.lineTo(xx, g.h - g.pad.b);\n    ctx.stroke();\n    ctx.beginPath();\n    ctx.arc(g.x(hi), g.y(g.pts[hi].mean), 4, 0, Math.PI * 2);\n    ctx.fillStyle = '#D8AD4E';\n    ctx.fill();\n  }\n}\n\n// Touch or hover: the nearest result, its setup and the average and band after it.\nfunction pbHover(i) {\n  const tip = $('pbTip');\n  const pts = pb.data && pb.data.stats ? pb.data.stats.curve : [];\n  if (i == null || !pts[i]) {\n    pb.curve.hover = null;\n    tip.hidden = true;\n    pbDraw(1);\n    return;\n  }\n  pb.curve.hover = i;\n  pbDraw(1);\n  const p = pts[i];\n  const word = p.status === 'won' ? 'won' : p.status === 'lost' ? 'lost' : 'scratch';\n  tip.innerHTML = `<b>${fmtR(p.r, 2)}</b> · #${p.n} ${word}, after costs<br><span class=\"k\"></span>average after ${i + 1}: <b>${fmtR(p.mean, 2)}</b>` +\n    (p.band ? `<br>95% band: ${fmtR(p.band[0], 2)} to ${fmtR(p.band[1], 2)}` : '<br>no band until 3 results');\n  tip.hidden = false;\n  const g = pbGeometry();\n  const left = Math.max(0, Math.min(g.w - tip.offsetWidth, g.x(i) - tip.offsetWidth / 2));\n  tip.style.left = `${left}px`;\n}\n\nfunction pbPoint(e) {\n  const pts = pb.data && pb.data.stats ? pb.data.stats.curve : [];\n  if (!pts.length) return null;\n  const g = pbGeometry();\n  const x = e.clientX - $('pbCurve').getBoundingClientRect().left;\n  let best = 0;\n  for (let i = 1; i < pts.length; i++) if (Math.abs(g.x(i) - x) < Math.abs(g.x(best) - x)) best = i;\n  return best;\n}\n\n// ----------------------------------------------------------- live setups\nfunction pbActive() {\n  const d = pb.data;\n  const active = d.setups.filter(isActive);\n  $('pbActive').innerHTML = active.map((s) => pbCard(s, d.canPost)).join('');\n}\n\nfunction pbCard(s, canPost) {\n  const m = MARKETS[s.symbol];\n  const f = (v) => fmtNum(v, m.digits);\n  const rr = Math.abs(s.tp - s.entry) / Math.abs(s.entry - s.sl);\n  const open = s.status === 'open';\n  const buttons = [];\n  if (s.photo) buttons.push(`<button type=\"button\" data-photo=\"${s.n}\">VIEW CHART</button>`);\n  if (canPost && open) {\n    if (s.stop !== s.fill) buttons.push(`<button type=\"button\" class=\"gold\" data-act=\"breakeven\" data-n=\"${s.n}\">BREAKEVEN</button>`);\n    buttons.push(`<button type=\"button\" data-act=\"stop\" data-n=\"${s.n}\">MOVE STOP</button>`, `<button type=\"button\" class=\"gold\" data-act=\"close\" data-n=\"${s.n}\">CLOSE NOW</button>`);\n  }\n  if (canPost && !open) buttons.push(`<button type=\"button\" data-act=\"cancel\" data-n=\"${s.n}\">CANCEL ORDER</button>`);\n  const stopWord = s.stop === s.sl ? 'Stop' : s.stop === s.fill ? 'Stop · at entry' : 'Stop · moved';\n  return `<div class=\"card pb-setup${s.test ? ' test' : ''}\">\n    <div class=\"sig-top\"><b>${s.symbol}</b><span class=\"sig-side ${s.side}\">${s.side.toUpperCase()}${pbKind(s)}</span>\n      <span class=\"pb-state ${s.status}\">${open ? 'LIVE' : 'WAITING FOR PRICE'}</span>${s.test ? '<span class=\"pb-state test\">TEST</span>' : ''}\n      <span class=\"sig-time\">#${s.n} · ${timeLabel(s.created)}</span></div>\n    <div class=\"sig-grid\">\n      <div><span>${open ? 'Filled' : 'Entry'}</span><b>${f(open ? s.fill : s.entry)}</b></div>\n      <div><span>${stopWord}</span><b>${f(s.stop)}</b></div>\n      <div><span>Target · ${fmtNum(rr, 1)}R</span><b>${f(s.tp)}</b></div>\n      <div><span>${open ? 'Now' : 'Price now'}</span><b class=\"pb-now\" data-live=\"${s.n}\">—</b></div>\n    </div>\n    <div class=\"pb-track\" data-track=\"${s.n}\" aria-hidden=\"true\"><div class=\"ends\"><span>STOP</span><span>TARGET</span></div><div class=\"rail\"></div><i class=\"mark\"></i><i class=\"dot\"></i></div>\n    <p class=\"pb-why\"><b>WHY</b>${pbEsc(s.note)}</p>\n    ${s.tags.length ? `<div class=\"pb-tags\">${s.tags.map((t) => `<span>#${pbEsc(t)}</span>`).join('')}</div>` : ''}\n    <div class=\"pb-meta\">No-edge odds ${pct(noEdgeOdds(s))} · logged ${ago(s.created)}${open ? '' : ` · waits until ${s.expires - clock() > 20 * 3600 ? `${pbDate(s.expires)} ` : ''}${timeLabel(s.expires)}`}${s.ref ? ` · ref ${pbEsc(s.ref)}` : ''}</div>\n    ${buttons.length ? `<div class=\"pb-buttons\">${buttons.join('')}</div>` : ''}\n    <div class=\"pb-stoprow\" data-stoprow=\"${s.n}\" hidden><input inputmode=\"decimal\" placeholder=\"New stop\" aria-label=\"New stop for #${s.n}\"><button type=\"button\" data-act=\"stop-go\" data-n=\"${s.n}\">MOVE</button></div>\n  </div>`;\n}\n\n// Every second while the Signals tab shows: live R, and where the price sits between stop and target.\nfunction pbLive() {\n  const d = pb.data;\n  if (!d || !d.setups) return;\n  for (const s of d.setups) {\n    if (!isActive(s)) continue;\n    const el = document.querySelector(`[data-live=\"${s.n}\"]`);\n    if (!el) continue;\n    const q = quoteOf(s.symbol);\n    const price = q && q.price;\n    const track = document.querySelector(`[data-track=\"${s.n}\"]`);\n    const at = (v) => `${Math.max(-1, Math.min(101, ((v - s.stop) / (s.tp - s.stop)) * 100))}%`;\n    track.querySelector('.mark').style.left = at(s.status === 'open' ? s.fill : s.entry);\n    if (!(price > 0)) {\n      el.textContent = '—';\n      track.querySelector('.dot').hidden = true;\n      continue;\n    }\n    track.querySelector('.dot').hidden = false;\n    track.querySelector('.dot').style.left = at(price);\n    if (s.status === 'open') {\n      const r = setupLiveR(s, price);\n      el.textContent = fmtR(r, 2);\n      el.className = `pb-now ${r > 0.005 ? 'up' : r < -0.005 ? 'down' : ''}`;\n    } else {\n      el.textContent = fmtNum(price, MARKETS[s.symbol].digits);\n    }\n  }\n}\n\n// ---------------------------------------------------------------- history\nfunction pbHistory() {\n  const done = pb.data.setups.filter((s) => !isActive(s));\n  $('pbHistoryCard').hidden = !done.length;\n  if (!done.length) return;\n  $('pbCount').textContent = `${done.length} closed`;\n  const rows = done.slice(0, pb.rows).map((s) => {\n    const result = isResult(s);\n    const how = { tp: 'Target', sl: 'Stop', be: 'Stop at entry', trail: 'Trailing stop', manual: 'Closed by hand' }[s.reason] ||\n      (s.status === 'expired' ? 'Expired, never filled' : 'Cancelled before it filled');\n    const held = result && s.filled ? ` · ${fmtDuration(s.closed - s.filled)}` : '';\n    const cls = result ? s.status : 'void';\n    const open = pb.opened.has(s.n);\n    const detail = open ? `<div class=\"pb-detail\">\n        <p class=\"pb-why\"><b>WHY</b>${pbEsc(s.note)}</p>\n        ${s.tags.length ? `<div class=\"pb-tags\">${s.tags.map((t) => `<span>#${pbEsc(t)}</span>`).join('')}</div>` : ''}\n        <div class=\"pb-meta\">Entry ${fmtNum(s.entry, MARKETS[s.symbol].digits)} · stop ${fmtNum(s.sl, MARKETS[s.symbol].digits)} · target ${fmtNum(s.tp, MARKETS[s.symbol].digits)}${s.exit != null ? ` · out ${fmtNum(s.exit, MARKETS[s.symbol].digits)}` : ''}<br>\n          No-edge odds ${pct(noEdgeOdds(s))} · logged ${pbDate(s.created)} ${timeLabel(s.created)}${s.ref ? ` · ref ${pbEsc(s.ref)}` : ''}</div>\n        ${s.photo ? `<div class=\"pb-buttons\"><button type=\"button\" data-photo=\"${s.n}\">VIEW CHART</button></div>` : ''}\n      </div>` : '';\n    return `<div class=\"pb-row ${cls}\" data-row=\"${s.n}\" role=\"button\" tabindex=\"0\" aria-expanded=\"${open}\">\n        <span class=\"n\">#${s.n}</span>\n        <span class=\"what\">${s.symbol} ${s.side.toUpperCase()}${pbKind(s)}${s.test ? ' · TEST' : ''}<small>${how} · ${pbDate(s.closed || s.created)}${held}</small></span>\n        <span class=\"r\">${result ? fmtR(s.r) : '—'}</span>\n      </div>${detail}`;\n  });\n  $('pbHistory').innerHTML = rows.join('') + (done.length > pb.rows ? `<button class=\"pb-more\" type=\"button\" id=\"pbMore\">SHOW ${Math.min(12, done.length - pb.rows)} MORE</button>` : '');\n}\n\nfunction pbReads() {\n  const st = pb.data.stats;\n  const names = (g, kind) => (kind === 'market' ? MARKETS[g.key].name : kind === 'session' ? PB_SESSIONS[g.key] || g.key : `#${g.key}`);\n  const rows = st.results < st.firstRead ? [] : [\n    ...st.byTag.map((g) => [g, 'tag']), ...st.byMarket.map((g) => [g, 'market']), ...st.bySession.map((g) => [g, 'session']),\n  ].filter(([g]) => g.n >= PLAYBOOK.tagRead);\n  $('pbReadsCard').hidden = !rows.length;\n  $('pbReads').innerHTML = rows.map(([g, kind]) => {\n    const w = Math.min(50, (Math.abs(g.avg) / 2) * 50);\n    const bar = g.avg >= 0 ? `left:50%;width:${w}%;background:var(--up)` : `left:${50 - w}%;width:${w}%;background:var(--down)`;\n    return `<div class=\"pb-read\"><span>${pbEsc(names(g, kind))} <small>${g.n}</small></span><span class=\"bar\"><i style=\"${bar}\"></i></span><b>${fmtR(g.avg, 2)}</b></div>`;\n  }).join('');\n}\n\n// The AI tab's memory card: the Playbook, the record TCP AI will also learn from.\nfunction pbMemory() {\n  const d = pb.data;\n  const record = d && d.setups ? d.setups.filter((s) => !s.test) : [];\n  const results = record.filter(isResult).length;\n  $('memPlaybook').textContent = record.length\n    ? `It will also learn from the Playbook: ${record.length} setup${record.length === 1 ? '' : 's'} with Lewis's reasons, ${results} with a result.`\n    : '';\n}\n\n// ----------------------------------------------------------------- the form\nfunction pbSheet(open) {\n  $('pbSheet').hidden = !open;\n  document.body.style.overflow = open ? 'hidden' : '';\n  if (!open) return;\n  const f = pb.form;\n  f.symbol = state.symbol;\n  f.tags = [];\n  f.photo = null;\n  f.liveEntry = true;\n  for (const id of ['pbSl', 'pbTp', 'pbNote', 'pbTagNew']) $(id).value = '';\n  $('pbPhotoPreview').hidden = true;\n  $('pbPhotoText').textContent = 'Add a screenshot of your chart';\n  $('pbError').hidden = true;\n  pbFormSync();\n}\n\nfunction pbFormSync() {\n  const f = pb.form;\n  for (const [id, key] of [['pbSymbol', 'symbol'], ['pbSide', 'side'], ['pbKind', 'kind'], ['pbExpiry', 'expiry']]) {\n    for (const b of $(id).querySelectorAll('button')) b.setAttribute('aria-pressed', String(b.dataset.v === String(f[key])));\n  }\n  $('pbExpiryField').hidden = f.kind === 'market';\n  if (f.liveEntry) {\n    const q = quoteOf(f.symbol);\n    $('pbEntry').value = q && q.price > 0 ? q.price.toFixed(MARKETS[f.symbol].digits) : '';\n    if (!q) loadMarket(f.symbol);\n  }\n  const suggestions = [...new Set([...(pb.data && pb.data.tags) || [], ...f.tags])];\n  $('pbTags').innerHTML = suggestions.map((t) => `<button type=\"button\" data-tag=\"${pbEsc(t)}\" aria-pressed=\"${f.tags.includes(t)}\">${pbEsc(t)}</button>`).join('');\n  pbPlanLine();\n  const live = pb.data && pb.data.mode === 'live';\n  $('pbSubmitNote').textContent = live\n    ? 'Posted to the Inner Circle with the time. The plan can’t be edited or deleted afterwards: only its stop can move, and it can be closed.'\n    : 'Test mode: posted to the team group only, and left out of the record.';\n}\n\nconst pbNum = (id) => parseFloat(String($(id).value).replace(/,/g, ''));\nfunction pbInput() {\n  const f = pb.form;\n  return { symbol: f.symbol, side: f.side, kind: f.kind, entry: pbNum('pbEntry'), sl: pbNum('pbSl'), tp: pbNum('pbTp'), tags: f.tags, note: $('pbNote').value, expiry: f.kind === 'market' ? null : f.expiry };\n}\n\nfunction pbPlanLine() {\n  const p = pbInput();\n  const m = MARKETS[p.symbol];\n  const risk = Math.abs(p.entry - p.sl);\n  const reward = Math.abs(p.tp - p.entry);\n  const ok = risk > 0 && reward > 0 && (p.side === 'buy' ? p.sl < p.entry && p.tp > p.entry : p.sl > p.entry && p.tp < p.entry);\n  $('pbPlan').innerHTML = ok\n    ? `<b>${fmtNum(reward / risk, 1)}R</b> target · risk <b>${fmtNum(risk, m.digits)}</b> · no-edge odds <b>${pct(risk / (risk + reward))}</b>`\n    : `Enter the stop ${p.side === 'buy' ? 'below' : 'above'} the entry and the target ${p.side === 'buy' ? 'above' : 'below'} it.`;\n}\n\nfunction pbFormError(message) {\n  $('pbError').textContent = message;\n  $('pbError').hidden = !message;\n  if (message) $('pbError').scrollIntoView({ block: 'nearest', behavior: 'smooth' });\n}\n\nfunction pbConfirm(text) {\n  return new Promise((resolve) => {\n    if (tg && tg.showConfirm && !demo) {\n      try { tg.showConfirm(text, (ok) => resolve(!!ok)); return; } catch {}\n    }\n    resolve(window.confirm(text));\n  });\n}\n\nfunction pbToast(text) {\n  const t = $('toast');\n  t.textContent = text;\n  t.hidden = false;\n  clearTimeout(pb.toastTimer);\n  pb.toastTimer = setTimeout(() => { t.hidden = true; }, 4200);\n}\n\n// Phone screenshots can be large: the chart goes up as a JPEG at most 1,600 pixels across.\nasync function pbShrink(file) {\n  try {\n    const bitmap = await createImageBitmap(file);\n    const scale = Math.min(1, 1600 / Math.max(bitmap.width, bitmap.height));\n    const canvas = document.createElement('canvas');\n    canvas.width = Math.round(bitmap.width * scale);\n    canvas.height = Math.round(bitmap.height * scale);\n    canvas.getContext('2d').drawImage(bitmap, 0, 0, canvas.width, canvas.height);\n    return await new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.86));\n  } catch {\n    return file.size <= 5e6 ? file : null;\n  }\n}\n\nasync function pbSubmit() {\n  if (pb.busy) return;\n  const input = pbInput();\n  const d = state.data[input.symbol];\n  const q = quoteOf(input.symbol);\n  const checked = checkPlan(input, q ? { price: q.price, atr: d && d.atr, open: marketStatus(MARKETS[input.symbol], clock()).open } : null);\n  if (checked.error) return pbFormError(checked.error);\n  pbFormError('');\n  const live = pb.data && pb.data.mode === 'live';\n  if (!(await pbConfirm(live ? \"Post this setup to the Inner Circle? It can't be edited or deleted afterwards.\" : 'Test mode: post this setup to the team group?'))) return;\n  pb.busy = true;\n  $('pbSubmit').disabled = true;\n  $('pbSubmit').textContent = 'POSTING…';\n  try {\n    if (demo) {\n      pbDemoAdd(checked.plan);\n      pbToast('Demo: logged here only, nothing was posted.');\n    } else {\n      const form = new FormData();\n      form.append('setup', JSON.stringify(input));\n      if (pb.form.photo) form.append('photo', pb.form.photo, 'chart.jpg');\n      const res = await pbSend('/api/playbook', form);\n      pbToast(res.warning || `Logged as #${res.setup.n} and posted.`);\n    }\n    try { tg && tg.HapticFeedback.notificationOccurred('success'); } catch {}\n    pbSheet(false);\n    await pbLoad(true);\n  } catch (err) {\n    pbFormError(err.message);\n  } finally {\n    pb.busy = false;\n    $('pbSubmit').disabled = false;\n    $('pbSubmit').textContent = 'LOG AND POST';\n  }\n}\n\nasync function pbAct(n, action, price) {\n  const words = { close: `Close #${n} at the market price now?`, cancel: `Cancel #${n} before it fills?`, breakeven: `Move #${n}'s stop to its entry?` };\n  if (words[action] && !(await pbConfirm(words[action]))) return;\n  try {\n    if (demo) {\n      pbDemoAct(n, action, price);\n      pbToast('Demo: changed here only.');\n    } else {\n      const res = await pbSend(`/api/playbook/${n}`, { action, ...(price != null ? { price } : {}) });\n      pbToast(res.message || { close: `#${n} closed.`, cancel: `#${n} cancelled.`, breakeven: `#${n}'s stop is at its entry.`, stop: `#${n}'s stop moved.` }[action]);\n    }\n    haptic();\n    await pbLoad(true);\n  } catch (err) {\n    pbToast(err.message);\n  }\n}\n\nasync function pbPhoto(n) {\n  try {\n    let url = pb.photos[n];\n    if (!url) {\n      const res = await fetch(`/api/playbook/${n}/photo`, { headers: { authorization: 'tma ' + (tg ? tg.initData : '') } });\n      if (!res.ok) throw new Error(\"The chart isn't available right now.\");\n      url = pb.photos[n] = URL.createObjectURL(await res.blob());\n    }\n    $('pbViewerImg').src = url;\n    $('pbViewer').hidden = false;\n  } catch (err) {\n    pbToast(err.message);\n  }\n}\n\n// ------------------------------------------------------------------- wiring\nfunction pbInit() {\n  $('pbNew').addEventListener('click', () => { haptic(); pbSheet(true); });\n  $('pbClose').addEventListener('click', () => pbSheet(false));\n  $('pbSheet').addEventListener('click', (e) => { if (e.target === $('pbSheet')) pbSheet(false); });\n  for (const [id, key] of [['pbSymbol', 'symbol'], ['pbSide', 'side'], ['pbKind', 'kind'], ['pbExpiry', 'expiry']]) {\n    $(id).addEventListener('click', (e) => {\n      const b = e.target.closest('button');\n      if (!b) return;\n      haptic();\n      const f = pb.form;\n      const value = key === 'expiry' ? Number(b.dataset.v) : b.dataset.v;\n      if (key === 'symbol' && value !== f.symbol) { $('pbSl').value = ''; $('pbTp').value = ''; f.liveEntry = f.kind === 'market'; }\n      if (key === 'kind') f.liveEntry = value === 'market';\n      f[key] = value;\n      pbFormSync();\n    });\n  }\n  $('pbEntry').addEventListener('input', () => { pb.form.liveEntry = false; pbPlanLine(); });\n  for (const id of ['pbSl', 'pbTp']) $(id).addEventListener('input', pbPlanLine);\n  $('pbTags').addEventListener('click', (e) => {\n    const b = e.target.closest('button[data-tag]');\n    if (!b) return;\n    const f = pb.form;\n    const tag = b.dataset.tag;\n    if (f.tags.includes(tag)) f.tags = f.tags.filter((t) => t !== tag);\n    else if (f.tags.length < PLAYBOOK.maxTags) f.tags.push(tag);\n    else return pbFormError(`Up to ${PLAYBOOK.maxTags} reasons.`);\n    haptic();\n    pbFormSync();\n  });\n  const addTag = () => {\n    const tag = $('pbTagNew').value.replace(/\\s+/g, ' ').trim().slice(0, 24);\n    $('pbTagNew').value = '';\n    if (!tag || pb.form.tags.some((t) => t.toLowerCase() === tag.toLowerCase())) return;\n    if (pb.form.tags.length >= PLAYBOOK.maxTags) return pbFormError(`Up to ${PLAYBOOK.maxTags} reasons.`);\n    pb.form.tags.push(tag);\n    pbFormSync();\n  };\n  $('pbTagNew').addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); addTag(); } });\n  $('pbTagNew').addEventListener('blur', addTag);\n  $('pbPhoto').addEventListener('change', async () => {\n    const file = $('pbPhoto').files[0];\n    if (!file) return;\n    $('pbPhotoText').textContent = 'Preparing the picture…';\n    const photo = await pbShrink(file);\n    pb.form.photo = photo;\n    $('pbPhotoText').textContent = photo ? 'Tap to change the picture' : 'That picture is too big: pick another.';\n    $('pbPhotoPreview').hidden = !photo;\n    if (photo) $('pbPhotoPreview').src = URL.createObjectURL(photo);\n  });\n  $('pbSubmit').addEventListener('click', pbSubmit);\n  $('pbExport').addEventListener('click', pbExport);\n\n  const clicks = (e) => {\n    const photo = e.target.closest('[data-photo]');\n    if (photo) return pbPhoto(Number(photo.dataset.photo));\n    const act = e.target.closest('[data-act]');\n    if (act) {\n      const n = Number(act.dataset.n);\n      if (act.dataset.act === 'stop') {\n        const row = document.querySelector(`[data-stoprow=\"${n}\"]`);\n        row.hidden = !row.hidden;\n        if (!row.hidden) row.querySelector('input').focus();\n        return;\n      }\n      if (act.dataset.act === 'stop-go') {\n        const value = parseFloat(String(document.querySelector(`[data-stoprow=\"${n}\"] input`).value).replace(/,/g, ''));\n        if (!(value > 0)) return pbToast('Enter the new stop.');\n        return pbAct(n, 'stop', value);\n      }\n      return pbAct(n, act.dataset.act);\n    }\n    if (e.target.id === 'pbMore') { pb.rows += 12; return pbHistory(); }\n    const row = e.target.closest('[data-row]');\n    if (row) {\n      const n = Number(row.dataset.row);\n      if (pb.opened.has(n)) pb.opened.delete(n);\n      else pb.opened.add(n);\n      haptic();\n      pbHistory();\n    }\n  };\n  $('pbActive').addEventListener('click', clicks);\n  $('pbHistoryCard').addEventListener('click', clicks);\n  $('pbHistoryCard').addEventListener('keydown', (e) => { if ((e.key === 'Enter' || e.key === ' ') && e.target.closest('[data-row]')) { e.preventDefault(); clicks(e); } });\n  $('pbViewer').addEventListener('click', () => { $('pbViewer').hidden = true; });\n\n  const cv = $('pbCurve');\n  cv.tabIndex = 0;\n  cv.addEventListener('pointermove', (e) => pbHover(pbPoint(e)));\n  cv.addEventListener('pointerdown', (e) => pbHover(pbPoint(e)));\n  cv.addEventListener('pointerleave', (e) => { if (e.pointerType === 'mouse') pbHover(null); });\n  cv.addEventListener('focus', () => {\n    const pts = pb.data && pb.data.stats ? pb.data.stats.curve : [];\n    if (pts.length && pb.curve.hover == null) pbHover(pts.length - 1); // a tap has already picked its point\n  });\n  cv.addEventListener('blur', () => pbHover(null));\n  cv.addEventListener('keydown', (e) => {\n    const pts = pb.data && pb.data.stats ? pb.data.stats.curve : [];\n    if (!pts.length || !['ArrowLeft', 'ArrowRight'].includes(e.key)) return;\n    e.preventDefault();\n    const i = pb.curve.hover == null ? pts.length - 1 : pb.curve.hover + (e.key === 'ArrowLeft' ? -1 : 1);\n    pbHover(Math.max(0, Math.min(pts.length - 1, i)));\n  });\n  document.addEventListener('pointerdown', (e) => { if (pb.curve.hover != null && e.target !== cv) pbHover(null); });\n  let resized = 0;\n  window.addEventListener('resize', () => { clearTimeout(resized); resized = setTimeout(() => pb.data && pb.data.stats && pbDraw(1), 150); });\n  pbLoad();\n}\n\n// -------------------------------------------------------------------- demo\n// Made-up setups for design work (?demo). Their results sit near the no-edge odds on\n// purpose, so a screenshot of the demo can never pass for a winning record.\nfunction pbDemo() {\n  if (pb.demo) return pb.demo;\n  let a = 99;\n  const random = () => { a = (a * 16807) % 2147483647; return a / 2147483647; };\n  const reasons = ['H4 zone', 'Fib pocket', 'Liquidity sweep', 'Rejection', 'Structure break', 'Reclaim', 'Session open'];\n  const notes = ['Swept the Asia low into the zone, then a rejection candle on the 15-minute chart.',\n    'Retest of the broken high, with the reclaim holding on the close.',\n    'Pullback into the pocket of the last impulse after a sweep of the previous day low.',\n    'London open ran the stops above the Asia high and rejected the zone.'];\n  const results = [2, -1, -1, 2, -1, -1, 0, 2, -1, -1, -1, 2, -1, 2, -1, -1, 1.4, -1, 2, -1, -1, 2, -1, -1];\n  const now = clock();\n  const setups = results.map((r, i) => {\n    const symbol = random() < 0.72 ? 'XAUUSD' : 'BTCUSD';\n    const side = random() < 0.55 ? 'buy' : 'sell';\n    const px = symbol === 'XAUUSD' ? 3700 + random() * 80 : Math.round(62000 + random() * 3000);\n    const risk = symbol === 'XAUUSD' ? 8 + Math.round(random() * 10) : 250 + Math.round(random() * 250);\n    const dir = side === 'buy' ? 1 : -1;\n    const created = now - (results.length - i) * 17 * 3600 - Math.round(random() * 3600);\n    const entry = Math.round(px * 100) / 100;\n    const s = {\n      n: i + 1, symbol, side, kind: 'market', entry, sl: entry - dir * risk, tp: entry + dir * risk * 2, created, expires: null,\n      tags: reasons.filter(() => random() < 0.35).slice(0, 4), note: notes[i % notes.length], author: 'Lewis', photo: false,\n      filled: created, fill: entry, test: false, ref: Math.floor(random() * 0xffffffff).toString(16).padStart(8, '0'),\n      engine: { sessions: random() < 0.6 ? ['london'] : ['newyork'], vol: random(), trend: random(), noEdge: 0.333 },\n    };\n    const reason = r === 2 ? 'tp' : r === -1 ? 'sl' : r === 0 ? 'be' : 'trail';\n    s.stop = reason === 'be' ? entry : reason === 'trail' ? entry + dir * risk * r : s.sl;\n    return { ...s, status: r > 0 ? 'won' : r < 0 ? 'lost' : 'scratch', closed: created + 3600 + Math.round(random() * 5 * 3600), exit: entry + dir * risk * r, r, reason };\n  });\n  const gold = quoteOf('XAUUSD');\n  const btcNow = quoteOf('BTCUSD');\n  const gp = gold ? gold.price : 3742.5;\n  const bp = btcNow ? btcNow.price : 64000;\n  const cents = (v) => Math.round(v * 100) / 100;\n  setups.push({\n    n: 25, symbol: 'XAUUSD', side: 'buy', kind: 'market', entry: cents(gp - 4), sl: cents(gp - 16), stop: cents(gp - 16),\n    tp: cents(gp + 20), created: now - 2 * 3600, expires: null, tags: ['Liquidity sweep', 'H4 zone'], note: notes[0],\n    author: 'Lewis', photo: false, status: 'open', filled: now - 2 * 3600, fill: cents(gp - 4), closed: null, exit: null,\n    r: null, reason: null, test: false, ref: '4c1e9a07', engine: { sessions: ['london', 'newyork'], vol: 0.6, trend: 0.4, noEdge: 0.333 },\n  });\n  setups.push({\n    n: 26, symbol: 'BTCUSD', side: 'sell', kind: 'limit', entry: Math.round(bp + 600), sl: Math.round(bp + 1100), stop: Math.round(bp + 1100), tp: Math.round(bp - 400),\n    created: now - 1800, expires: now + 22 * 3600, tags: ['Fib pocket'], note: notes[2], author: 'Lewis', photo: false, status: 'pending',\n    filled: null, fill: null, closed: null, exit: null, r: null, reason: null, test: false, ref: 'b27f10d3',\n    engine: { sessions: ['london'], vol: 0.4, trend: 0.3, noEdge: 0.333 },\n  });\n  setups.reverse();\n  pb.demo = { ready: true, mode: 'live', canPost: true, setups, tags: reasons, record: { entries: 60, head: '9e03c2b1' } };\n  pb.demo.stats = recordStats(setups);\n  return pb.demo;\n}\n\nfunction pbDemoAdd(plan) {\n  const d = pbDemo();\n  const s = { ...openSetup(plan, clock()), n: Math.max(...d.setups.map((x) => x.n)) + 1, author: 'Demo', photo: false, test: false, ref: 'demo0000',\n    engine: { sessions: [], vol: null, trend: null, noEdge: noEdgeOdds(plan) } };\n  d.setups.unshift(s);\n  d.stats = recordStats(d.setups);\n}\n\nfunction pbDemoAct(n, action, price) {\n  const d = pbDemo();\n  const i = d.setups.findIndex((s) => s.n === n);\n  const s = d.setups[i];\n  const q = quoteOf(s.symbol);\n  const now = clock();\n  const next = action === 'close' ? closeSetup(s, now, q.price) : action === 'cancel' ? cancelSetup(s, now)\n    : moveSetupStop(s, now, action === 'breakeven' ? s.fill : price);\n  d.setups[i] = next.setup;\n  d.stats = recordStats(d.setups);\n}\n\n// TCP Quant Terminal: the page's session briefs, on the AI tab. build.mjs puts the shared maths\n// (lib.js, playbook-lib.js, brief-lib.js) and the Playbook's page code in front of this file and\n// app.js after it, all in one script. Nothing here runs on load: the functions use app.js's\n// helpers ($, call, tg, demo, quoteOf, ...) and the Playbook's (pbSend, pbToast, pbConfirm,\n// pbEsc) when they're called, and app.js calls brInit() once the member is signed in.\n\nconst br = {\n  data: null, // the last answer from /api/briefs\n  at: 0,\n  loading: null,\n  form: { session: null, symbol: 'XAUUSD', charts: [], note: '' }, // charts: [{ blob, url }]\n  step: 'charts', // the sheet: charts, reading or draft\n  brief: null, // the brief being checked\n  edit: null, // the draft as edited: { headline, bias, reason, zones, plan, chart, lesson }\n  busy: false,\n  readStart: 0,\n  thumbs: {}, // 'id:k' -> object URL of a chart the Worker kept\n  photos: {}, // brief id -> object URL of its posted chart\n  opened: new Set(), // history rows showing their detail\n  demo: null,\n};\nconst BR_BIAS = { long: 'Long', short: 'Short', neutral: 'Neutral' };\nconst brSessionName = (id) => (briefSession(id) || { name: id }).name;\nconst brPrice = (symbol, v) => fmtNum(v, MARKETS[symbol].digits);\nconst brRange = (symbol, z) => (z.low === z.high ? brPrice(symbol, z.low) : `${brPrice(symbol, z.low)}–${brPrice(symbol, z.high)}`);\nconst brZoneName = (z) => z.label || [z.tf, BRIEF.kinds[z.kind]].filter(Boolean).join(' ');\nconst brUntil = (t) => { const s = t - clock(); return s > 0 ? `in ${fmtDuration(s)}` : `${fmtDuration(-s)} ago`; };\n\n// ------------------------------------------------------------------- data\nfunction brLoad(force = false) {\n  if (!force && br.data && !br.data.error && clock() - br.at < 30) return Promise.resolve();\n  if (br.loading) return force ? br.loading.then(() => brLoad(true)) : br.loading;\n  br.loading = (async () => {\n    try {\n      br.data = demo ? brDemo() : await call('/api/briefs');\n      br.at = clock();\n    } catch (err) {\n      if (!br.data || br.data.error) br.data = { error: err.message };\n    }\n    brRender();\n    renderChartZones();\n  })().finally(() => { br.loading = null; });\n  return br.loading;\n}\n\nconst brPoster = () => !!(br.data && br.data.ready && br.data.canPost);\n\nfunction brFab() {\n  $('brNew').hidden = !(brPoster() && !$('ai').hidden);\n  document.body.classList.toggle('with-fab', !$('brNew').hidden || !$('pbNew').hidden);\n}\n\n// The newest posted brief whose session is still to come or running, for the Markets chart.\nfunction brActive(symbol) {\n  const d = br.data;\n  const b = d && d.briefs && d.briefs.find((x) => x.status === 'posted' && x.symbol === symbol && x.closes > clock() && x.final);\n  return b ? [b] : [];\n}\n\n// ----------------------------------------------------------------- render\nfunction brRender() {\n  const d = br.data;\n  brFab();\n  brMemory();\n  if (!d) return;\n  if (d.error || !d.ready) {\n    $('brMode').hidden = true;\n    $('brNext').hidden = true;\n    $('brRecordCard').hidden = true;\n    $('brHistoryCard').hidden = true;\n    $('brList').innerHTML = `<p class=\"pb-empty card-empty\">${pbEsc(d.error || 'Session briefs start soon: before each session, Lewis\\'s charts read by TCP AI, the zones to watch and a plan, and every zone scored afterwards.')}</p>`;\n    return;\n  }\n  $('brMode').hidden = !d.canPost;\n  $('brMode').textContent = d.mode === 'live' ? 'Live' : 'Test mode';\n  $('brMode').className = `state ${d.mode === 'live' ? 'live' : 'testing'}`;\n  brNext();\n  brList();\n  brHistory();\n  brRecord();\n  brLive();\n}\n\nfunction brNext() {\n  const w = briefDefault(clock());\n  $('brNext').hidden = !w;\n  if (!w) return;\n  const s = briefSession(w.id);\n  const has = br.data.briefs.some((b) => b.session === w.id && b.day === w.key && b.status === 'posted');\n  $('brNextIcon').textContent = s.icon;\n  $('brNextName').textContent = `${s.name}${w.weekly ? ' · week ahead' : ''}`;\n  $('brNextWhen').dataset.open = w.open;\n  $('brNextTag').textContent = has ? 'brief out' : br.data.canPost ? 'your brief' : 'brief before the open';\n  $('brAsk').hidden = !br.data.canPost || has;\n  $('brAsk').innerHTML = `Charts to send: ${briefAsk(w).map((t) => `<b>${t}</b>`).join(' ')}`;\n}\n\n// Cards for today's briefs: running or still to come, plus the poster's drafts; the rest are history.\nfunction brList() {\n  const d = br.data;\n  const now = clock();\n  const cards = d.briefs.filter((b) => (b.status === 'posted' && b.closes > now - 6 * 3600) || (d.canPost && ['reading', 'draft', 'failed'].includes(b.status)));\n  if (!d.briefs.length) {\n    $('brList').innerHTML = `<p class=\"pb-empty card-empty\">${d.canPost\n      ? d.mode === 'live' ? 'No briefs yet. Tap + SEND CHARTS before a session: TCP AI reads them and you check the draft before it posts.'\n        : 'Test mode: briefs you post go to the team group only. Tap + SEND CHARTS to try it. Switch BRIEF_MODE to live when you are ready.'\n      : 'Before each session, Lewis\\'s brief lands here and in the Inner Circle: the zones to watch, the plan, and the odds of price reaching each zone.'}</p>`;\n    return;\n  }\n  $('brList').innerHTML = cards.map((b) => (b.status === 'posted' ? brCard(b) : brDraftCard(b))).join('');\n}\n\nfunction brDraftCard(b) {\n  const s = briefSession(b.session);\n  const what = b.status === 'reading' ? 'TCP AI is reading your charts…' : b.status === 'failed' ? pbEsc(b.error || 'The read failed.') : 'Ready for you to check.';\n  return `<div class=\"card br-card draft\">\n    <div class=\"br-top\"><span class=\"br-icon\">${s.icon}</span><b>${s.name}</b><span class=\"br-sym\">${b.symbol}</span>\n      <span class=\"pb-state ${b.status === 'reading' ? 'pending' : 'test'}\">${b.status === 'reading' ? 'READING' : b.status === 'failed' ? 'NOT READ' : 'DRAFT'}</span></div>\n    <p class=\"br-reason\">${what}</p>\n    <div class=\"pb-buttons\"><button type=\"button\" class=\"gold\" data-open=\"${b.id}\"${b.status === 'reading' ? ' disabled' : ''}>${b.status === 'failed' ? 'TRY AGAIN OR WRITE IT' : 'CHECK AND POST'}</button></div>\n  </div>`;\n}\n\nfunction brCard(b) {\n  const s = briefSession(b.session);\n  const f = b.final;\n  const now = clock();\n  const state = b.review ? 'done' : now < b.opens ? 'soon' : now < b.closes ? 'live' : 'closed';\n  const word = { soon: `OPENS ${brUntil(b.opens).toUpperCase()}`, live: 'SESSION OPEN', closed: 'SCORING', done: 'SCORED' }[state];\n  const zones = brZones(b).map((z, i) => `<div class=\"br-zone ${z.kind}\">\n      <i aria-hidden=\"true\"></i><div><b>${brRange(b.symbol, z)}</b><span>${pbEsc(brZoneName(z))}${z.why ? ` · ${pbEsc(z.why)}` : ''}</span></div>\n      <em data-zone=\"${b.id}:${i}\" class=\"${brZoneStatus(b, z).cls}\">${brZoneStatus(b, z).text}</em></div>`).join('');\n  const r = b.review;\n  return `<div class=\"card br-card${b.test ? ' test' : ''}\">\n    <div class=\"br-top\"><span class=\"br-icon\">${s.icon}</span><b>${s.name}</b><span class=\"br-sym\">${b.symbol}</span>\n      <span class=\"pb-state ${state === 'live' ? 'open' : state === 'soon' ? 'pending' : ''}\" data-when=\"${b.id}\">${word}</span>${b.test ? '<span class=\"pb-state test\">TEST</span>' : ''}</div>\n    <h3 class=\"br-headline\">${pbEsc(f.headline)}</h3>\n    <p class=\"br-reason\"><span class=\"br-bias ${f.bias}\">${f.bias.toUpperCase()}</span>${pbEsc(f.reason || '')}</p>\n    <div class=\"br-zones\">${zones}</div>\n    <div class=\"br-plan\"><b>PLAN</b><ul>${f.plan.map((l) => `<li>${pbEsc(l)}</li>`).join('')}</ul></div>\n    ${r ? `<div class=\"br-wrap\">${r.counted ? `Reached <b>${r.reached} of ${r.counted}</b> · a random walk would reach <b>${fmtNum(r.expected, 1)}</b>` : 'Price was inside every zone when it went out.'}</div>` : ''}\n    <div class=\"pb-meta\">${b.ai ? `Charts read by TCP AI, checked by ${pbEsc(b.author)}` : `By ${pbEsc(b.author)}`} · ${timeLabel(b.posted)} · brief #${b.id}</div>\n    ${b.photo ? `<div class=\"pb-buttons\"><button type=\"button\" data-chart=\"${b.id}\">VIEW CHART</button></div>` : ''}\n  </div>`;\n}\n\n// A posted brief's zones, highest first: once the session is scored, with what price did at each.\nconst brZones = (b) => [...(b.review ? b.review.zones : b.final.zones)].sort((x, y) => y.high - x.high);\n\n// Where a zone stands: after the session, the review; before and during it, whether price has\n// reached it since the brief went out (15-minute bars and the live price), else the odds it will\n// before the close from here, if price moves at random.\nfunction brZoneStatus(b, z) {\n  const r = z.review;\n  if (r) {\n    if (r.reached === null) return { text: 'was there', cls: '' };\n    if (!r.reached) return { text: `not reached · ${pct(z.odds)}`, cls: 'br-miss' };\n    return { text: `✓ ${brPrice(b.symbol, r.away)} back · ${brPrice(b.symbol, r.through)} on`, cls: 'br-hit' };\n  }\n  const d = state.data[b.symbol];\n  const q = quoteOf(b.symbol);\n  const now = clock();\n  if (!d || d.error || !q || !(q.price > 0)) return { text: `${pct(z.odds)} to reach`, cls: '' };\n  const bars = (d.bars || []).map(([t, o, h, l, c]) => ({ t, o, h, l, c }));\n  const seen = reviewZone(z, bars, { from: b.posted + 900, to: now + 900, price: b.price, atr: null, step: 900 });\n  if (seen.reached === null) return { text: 'here at the post', cls: '' };\n  if (seen.reached || zoneSide(z, q.price) === 'inside' || (zoneSide(z, b.price) === 'below' ? q.price <= z.high : q.price >= z.low)) return { text: '✓ reached', cls: 'br-hit' };\n  if (now >= b.closes || !d.engine) return { text: `${pct(z.odds)} to reach`, cls: '' };\n  const odds = zoneOdds(z, q.price, varianceBetween(d.engine.profile, now, b.closes));\n  return { text: `${pct(odds)} to reach`, cls: '' };\n}\n\n// Every second on the AI tab: countdowns and each zone's live odds.\nfunction brLive() {\n  const d = br.data;\n  if (!d || !d.briefs || $('ai').hidden) return;\n  const w = $('brNextWhen');\n  if (w.dataset.open) {\n    const s = Number(w.dataset.open) - clock();\n    w.textContent = s > 0 ? `opens in ${fmtDuration(s)}` : `opened ${fmtDuration(-s)} ago`;\n  }\n  for (const b of d.briefs) {\n    if (b.status !== 'posted' || !b.final) continue;\n    brZones(b).forEach((z, i) => {\n      const el = document.querySelector(`[data-zone=\"${b.id}:${i}\"]`);\n      if (!el) return;\n      const st = brZoneStatus(b, z);\n      if (el.textContent !== st.text) el.textContent = st.text;\n      el.className = st.cls;\n    });\n  }\n}\n\nfunction brHistory() {\n  const d = br.data;\n  const now = clock();\n  const old = d.briefs.filter((b) => b.status === 'posted' && b.closes <= now - 6 * 3600);\n  $('brHistoryCard').hidden = !old.length;\n  if (!old.length) return;\n  $('brCount').textContent = `${old.length} earlier`;\n  $('brHistory').innerHTML = old.slice(0, 20).map((b) => {\n    const s = briefSession(b.session);\n    const r = b.review;\n    const open = br.opened.has(b.id);\n    return `<div class=\"pb-row br-row\" data-brrow=\"${b.id}\" role=\"button\" tabindex=\"0\" aria-expanded=\"${open}\">\n        <span class=\"n\">${s.icon}</span>\n        <span class=\"what\">${s.name} · ${b.symbol}${b.test ? ' · TEST' : ''}<small>${pbEsc(b.final.headline)} · ${pbDate(b.posted)}</small></span>\n        <span class=\"r\">${r ? `${r.reached}/${r.counted}` : '—'}<small>${r ? 'reached' : 'not scored'}</small></span>\n      </div>${open ? `<div class=\"pb-detail\">${brCard(b).replace(/^<div class=\"card br-card[^\"]*\">/, '<div class=\"br-inline\">')}</div>` : ''}`;\n  }).join('');\n}\n\nfunction brRecord() {\n  const st = br.data.stats;\n  $('brRecordCard').hidden = !st || !st.zones;\n  if (!st || !st.zones) return;\n  $('brBriefs').textContent = st.briefs;\n  $('brZoneCount').textContent = st.zones;\n  $('brReached').innerHTML = `${st.reached}<small>of ${st.zones}</small>`;\n  $('brTurn').innerHTML = st.turn.n ? `${st.turn.avg > 0 ? '+' : st.turn.avg < 0 ? '−' : ''}${fmtNum(Math.abs(st.turn.avg), 2)}<small>ATR</small>` : '—';\n  const v = brVerdict(st);\n  $('brVerdict').className = `pb-verdict ${v.cls}`;\n  $('brVerdict').innerHTML = `<span class=\"icon\" aria-hidden=\"true\">${v.icon}</span><div><b>${v.title}</b><span>${v.text}</span></div>` +\n    (v.progress != null ? `<div class=\"pb-progress\"><i style=\"width:${Math.round(v.progress * 100)}%\"></i></div>` : '');\n  $('brReach').innerHTML = `Reached <b>${st.reached} of ${st.zones}</b> (${pct(st.reach.rate)}), where a random walk would reach <b>${fmtNum(st.expected, 1)}</b> (${pct(st.reach.noEdge)}).`;\n  const rows = st.turn.n < st.firstRead ? [] : [...st.byKind.map((g) => [g, BRIEF.kinds[g.key]]), ...st.bySession.map((g) => [g, brSessionName(g.key)])].filter(([g]) => g.turns >= 5);\n  $('brReads').hidden = !rows.length;\n  $('brReads').innerHTML = rows.map(([g, name]) => {\n    const w = Math.min(50, Math.abs(g.turn) * 100);\n    const bar = g.turn >= 0 ? `left:50%;width:${w}%;background:var(--up)` : `left:${50 - w}%;width:${w}%;background:var(--down)`;\n    return `<div class=\"pb-read\"><span>${pbEsc(name)} <small>${g.reached}/${g.zones}</small></span><span class=\"bar\"><i style=\"${bar}\"></i></span><b>${g.turn > 0 ? '+' : ''}${fmtNum(g.turn, 2)}</b></div>`;\n  }).join('');\n}\n\nfunction brVerdict(st) {\n  const n = st.turn.n;\n  if (st.verdict === 'collecting') {\n    return { cls: 'collecting', icon: n, progress: n / st.firstRead, title: `Collecting: ${n} of ${st.firstRead} zones reached`,\n      text: `The first read comes at ${st.firstRead} reached zones. Until then, any average is mostly luck.` };\n  }\n  const band = `${fmtNum(st.turn.band[0], 2)} to ${fmtNum(st.turn.band[1], 2)} ATR`;\n  if (st.verdict === 'turning') return { cls: 'ahead', icon: '▲', title: 'Zones turn price', text: `After ${n} reached zones the whole band (${band}) is above zero: price has gone back from them more than chance explains.` };\n  if (st.verdict === 'breaking') return { cls: 'behind', icon: '▼', title: 'Price goes through', text: `After ${n} reached zones the whole band (${band}) is below zero: price has gone on through them more than back.` };\n  return { cls: 'unclear', icon: '≈', title: 'Too close to call', text: `After ${n} reached zones the band (${band}) still spans zero: no sign yet that the zones turn price more than chance.` };\n}\n\n// The memory card: what TCP AI reads before each brief, and the Playbook it will learn from.\nfunction brMemory() {\n  const m = br.data && br.data.memory;\n  $('memCharts').textContent = m ? m.charts : 0;\n  $('memLessons').textContent = m ? m.lessons : 0;\n  $('memZones').textContent = br.data && br.data.stats ? br.data.stats.zones : 0;\n  $('brTeach').hidden = !brPoster();\n  $('brExport').hidden = !brPoster();\n}\n\n// ------------------------------------------------------------- the sheet\nasync function brShrink(file) {\n  // Charts go up as JPEGs at most 2,576 pixels on the long side: the most TCP AI reads, and\n  // enough for the panel's small text.\n  try {\n    const bitmap = await createImageBitmap(file);\n    const scale = Math.min(1, 2576 / Math.max(bitmap.width, bitmap.height));\n    const canvas = document.createElement('canvas');\n    canvas.width = Math.round(bitmap.width * scale);\n    canvas.height = Math.round(bitmap.height * scale);\n    canvas.getContext('2d').drawImage(bitmap, 0, 0, canvas.width, canvas.height);\n    return await new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.9));\n  } catch {\n    return file.size <= 8e6 ? file : null;\n  }\n}\n\nfunction brSheet(open, { session = null, brief = null } = {}) {\n  $('brSheet').hidden = !open;\n  document.body.style.overflow = open ? 'hidden' : '';\n  if (!open) return;\n  if (brief) return brOpenDraft(brief);\n  const f = br.form;\n  for (const c of f.charts) URL.revokeObjectURL(c.url);\n  const w = briefDefault(clock());\n  Object.assign(f, { session: session || (w && w.id) || 'london', symbol: state.symbol, charts: [], note: '' });\n  $('brNote').value = '';\n  br.brief = null;\n  br.edit = null;\n  brStep('charts');\n}\n\nfunction brStep(step) {\n  br.step = step;\n  for (const s of ['charts', 'reading', 'draft']) $(`brStep_${s}`).hidden = s !== step;\n  $('brSheetTitle').textContent = step === 'draft' ? `${brSessionName(br.brief ? br.brief.session : br.form.session)} brief` : 'Session brief';\n  $('brError').hidden = true;\n  if (step === 'charts') brChartsForm();\n  if (step === 'draft') brDraftForm();\n  $('brSheet').querySelector('.sheet-body').scrollTop = 0;\n}\n\nfunction brChartsForm() {\n  const f = br.form;\n  const d = br.data || {};\n  const now = clock();\n  $('brSession').innerHTML = BRIEF.sessions.map((s) => {\n    const w = briefWindow(s.id, now);\n    const when = !w ? '' : w.open > now ? ` · ${fmtDuration(w.open - now)}` : ' · open';\n    return `<button type=\"button\" data-v=\"${s.id}\" aria-pressed=\"${f.session === s.id}\">${s.name}${when}</button>`;\n  }).join('');\n  for (const b of $('brSymbol').querySelectorAll('button')) b.setAttribute('aria-pressed', String(b.dataset.v === f.symbol));\n  const w = briefWindow(f.session, now);\n  $('brAskLine').innerHTML = `TCP AI asks for ${briefAsk(w).map((t) => `<b>${t}</b>`).join(' ')}: pick them all at once, in any order.`;\n  $('brThumbs').innerHTML = f.charts.map((c, i) => `<figure><img src=\"${c.url}\" alt=\"Chart ${i + 1}\"><button type=\"button\" data-drop=\"${i}\" aria-label=\"Remove chart ${i + 1}\">×</button><figcaption>${i + 1}</figcaption></figure>`).join('');\n  $('brPickText').textContent = f.charts.length ? `${f.charts.length} chart${f.charts.length === 1 ? '' : 's'} · tap to add more` : 'Add your chart screenshots';\n  const ai = d.ai || demo;\n  $('brRead').textContent = ai ? 'READ MY CHARTS' : 'KEEP THE CHARTS AND WRITE IT';\n  $('brRead').disabled = !f.charts.length || br.busy;\n  const me = d.me;\n  $('brReadNote').textContent = ai\n    ? `TCP AI reads them with the terminal's numbers and drafts the brief. Nothing posts until you've checked it.${me ? ` ${me.readsToday} of ${me.limit} reads today.` : ''}`\n    : 'TCP AI is off (no ANTHROPIC_API_KEY): the charts are kept, and you write the brief.';\n}\n\nasync function brAddCharts(files) {\n  const f = br.form;\n  const room = BRIEF.maxCharts - f.charts.length;\n  if (files.length > room) pbToast(`Up to ${BRIEF.maxCharts} charts: the first ${Math.max(0, room)} were added.`);\n  $('brPickText').textContent = 'Preparing the pictures…';\n  for (const file of [...files].slice(0, Math.max(0, room))) {\n    const blob = await brShrink(file);\n    if (blob) f.charts.push({ blob, url: URL.createObjectURL(blob) });\n  }\n  brChartsForm();\n}\n\nasync function brSubmit() {\n  if (br.busy || !br.form.charts.length) return;\n  const f = br.form;\n  f.note = $('brNote').value;\n  br.busy = true;\n  br.readStart = clock();\n  const ai = (br.data && br.data.ai) || demo;\n  if (ai) brStep('reading');\n  try {\n    let res;\n    if (demo) {\n      await new Promise((r) => setTimeout(r, 2400));\n      res = { brief: brDemoRead() };\n    } else {\n      const form = new FormData();\n      form.append('brief', JSON.stringify({ symbol: f.symbol, session: f.session, note: f.note }));\n      f.charts.forEach((c, i) => form.append('chart', c.blob, `chart-${i + 1}.jpg`));\n      res = await pbSend('/api/briefs', form);\n    }\n    if (res.warning) pbToast(res.warning);\n    br.brief = res.brief;\n    br.edit = null;\n    brStep('draft');\n    brLoad(true);\n  } catch (err) {\n    brStep('charts');\n    brError(err.message);\n  } finally {\n    br.busy = false;\n    if (br.step === 'charts') brChartsForm();\n  }\n}\n\n// The reading screen's clock.\nfunction brReadingTick() {\n  if (br.step !== 'reading' || $('brSheet').hidden) return;\n  const s = clock() - br.readStart;\n  $('brElapsed').textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;\n  $('brReadingWhat').textContent = `TCP AI is reading your ${br.form.charts.length} chart${br.form.charts.length === 1 ? '' : 's'}`;\n}\n\nasync function brOpenDraft(id) {\n  const b = br.data && br.data.briefs.find((x) => x.id === id);\n  if (!b) return pbToast('That brief is gone.');\n  br.brief = b;\n  br.edit = null;\n  br.form.charts = [];\n  brStep('draft');\n}\n\n// The draft as the poster edits it: TCP AI's, or empty when there's no read.\nfunction brEditOf(b) {\n  const d = b.draft || { headline: '', bias: 'neutral', reason: '', zones: [], plan: [], chart: 1, warnings: [] };\n  return {\n    headline: d.headline, bias: d.bias, reason: d.reason,\n    zones: d.zones.map((z) => ({ kind: z.kind, low: z.low, high: z.high, tf: z.tf || '', label: z.label || '', why: z.why || '' })),\n    plan: d.plan.join('\\n'), chart: d.chart || 1, lesson: '',\n  };\n}\n\nfunction brDraftForm() {\n  const b = br.brief;\n  br.edit ||= brEditOf(b);\n  const e = br.edit;\n  const failed = b.status === 'failed';\n  $('brFailed').hidden = !failed;\n  $('brFailedText').textContent = b.error || '';\n  const warn = (b.draft && b.draft.warnings) || [];\n  $('brWarnings').hidden = !warn.length;\n  $('brWarnings').innerHTML = warn.map((w) => `<div>⚠︎ ${pbEsc(w)}</div>`).join('');\n  $('brReadCard').hidden = !b.read;\n  if (b.read) {\n    const r = b.read;\n    $('brReadBody').innerHTML = [\n      ...r.charts.map((c) => `<div class=\"br-readrow\"><b>${c.chart ?? '?'} · ${pbEsc(c.timeframe)}</b><span>${c.trend}${c.price ? ` · ${brPrice(b.symbol, c.price)}` : ''} — ${pbEsc(c.summary)}</span></div>`),\n      r.panel.length ? `<div class=\"br-panel\">${r.panel.map((p) => `<div><span>${pbEsc(p.section ? `${p.section} · ` : '')}${pbEsc(p.row)}</span><b>${pbEsc(p.value)}</b></div>`).join('')}</div>` : '',\n      r.unreadable.length ? `<div class=\"br-readrow\"><b>Couldn't read</b><span>${r.unreadable.map(pbEsc).join('; ')}</span></div>` : '',\n      `<div class=\"pb-meta\">${pbEsc(b.model || '')}${b.cost != null ? ` · this read cost about $${b.cost.toFixed(2)}` : ''}${r.confidence ? ` · confidence ${r.confidence}` : ''}</div>`,\n    ].join('');\n  }\n  $('brHeadline').value = e.headline;\n  for (const x of $('brBias').querySelectorAll('button')) x.setAttribute('aria-pressed', String(x.dataset.v === e.bias));\n  $('brReason').value = e.reason;\n  brZoneRows();\n  $('brPlan').value = e.plan;\n  $('brLesson').value = e.lesson;\n  brPostCharts();\n  const live = br.data && br.data.mode === 'live';\n  $('brPost').textContent = live ? 'POST TO THE INNER CIRCLE' : 'POST TO THE TEAM (TEST)';\n  $('brPostNote').textContent = live\n    ? 'Posted to the Inner Circle with the zones\\' odds. After the session, each zone is scored and the wrap is posted as a reply.'\n    : 'Test mode: posted to the team group only, and left out of the record.';\n}\n\nfunction brZoneRows() {\n  const b = br.brief;\n  const e = br.edit;\n  $('brZones').innerHTML = e.zones.map((z, i) => `<div class=\"br-zrow ${z.kind}\" data-i=\"${i}\">\n      <select data-f=\"kind\" aria-label=\"Kind of zone ${i + 1}\">${Object.entries(BRIEF.kinds).map(([k, v]) => `<option value=\"${k}\"${k === z.kind ? ' selected' : ''}>${v}</option>`).join('')}</select>\n      <input data-f=\"low\" inputmode=\"decimal\" value=\"${z.low ?? ''}\" aria-label=\"Low of zone ${i + 1}\" placeholder=\"Low\">\n      <input data-f=\"high\" inputmode=\"decimal\" value=\"${z.high ?? ''}\" aria-label=\"High of zone ${i + 1}\" placeholder=\"High\">\n      <button type=\"button\" class=\"br-x\" data-zdrop=\"${i}\" aria-label=\"Remove zone ${i + 1}\">×</button>\n      <input data-f=\"label\" value=\"${pbEsc(z.label)}\" maxlength=\"40\" placeholder=\"Name, e.g. 4H demand\" aria-label=\"Name of zone ${i + 1}\">\n      <input data-f=\"why\" value=\"${pbEsc(z.why)}\" maxlength=\"200\" placeholder=\"Why it matters\" aria-label=\"Why zone ${i + 1} matters\">\n      <small data-zodds=\"${i}\">${brEditOdds(b, z)}</small>\n    </div>`).join('') || '<p class=\"fine\" style=\"margin:0 0 8px\">No zones yet: add the ones that matter this session.</p>';\n  $('brAddZone').hidden = e.zones.length >= BRIEF.maxZones;\n}\n\n// A zone's odds while it's edited: from the live price to the session's close, moving at random.\nfunction brEditOdds(b, z) {\n  const low = parseFloat(String(z.low).replace(/,/g, ''));\n  const high = parseFloat(String(z.high === '' ? z.low : z.high).replace(/,/g, ''));\n  const d = state.data[b.symbol];\n  const q = quoteOf(b.symbol);\n  if (!(low > 0) || !(high > 0) || !d || !d.engine || !q) return '';\n  const zone = { low: Math.min(low, high), high: Math.max(low, high) };\n  if (zoneSide(zone, q.price) === 'inside') return 'price is in it now';\n  const odds = zoneOdds(zone, q.price, varianceBetween(d.engine.profile, clock(), b.closes));\n  return `${pct(odds)} chance price reaches it before ${brSessionName(b.session)} closes, moving at random`;\n}\n\nfunction brPostCharts() {\n  const b = br.brief;\n  const e = br.edit;\n  const local = br.form.charts;\n  const count = local.length || (b.charts ? b.charts.length : 0);\n  $('brChartPick').innerHTML = Array.from({ length: count }, (_, i) => {\n    const k = i + 1;\n    const url = local[i] ? local[i].url : br.thumbs[`${b.id}:${k}`] || '';\n    return `<button type=\"button\" data-k=\"${k}\" aria-pressed=\"${e.chart === k}\">${url ? `<img src=\"${url}\" alt=\"Chart ${k}\">` : `<span>${k}</span>`}</button>`;\n  }).join('');\n  $('brChartField').hidden = !count;\n  if (!local.length && !demo && b.charts) {\n    for (const c of b.charts) {\n      const key = `${b.id}:${c.k}`;\n      if (!c.kept || br.thumbs[key]) continue;\n      br.thumbs[key] = '';\n      fetch(`/api/briefs/${b.id}/chart/${c.k}`, { headers: { authorization: 'tma ' + (tg ? tg.initData : '') } })\n        .then((r) => (r.ok ? r.blob() : null)).then((blob) => {\n          if (!blob) return;\n          br.thumbs[key] = URL.createObjectURL(blob);\n          if (br.brief && br.brief.id === b.id && br.step === 'draft') brPostCharts();\n        }).catch(() => {});\n    }\n  }\n}\n\n// Reads the editor into br.edit.\nfunction brCollect() {\n  const e = br.edit;\n  e.headline = $('brHeadline').value;\n  e.reason = $('brReason').value;\n  e.plan = $('brPlan').value;\n  e.lesson = $('brLesson').value;\n  e.zones = [...$('brZones').querySelectorAll('.br-zrow')].map((row) => {\n    const get = (k) => row.querySelector(`[data-f=\"${k}\"]`).value;\n    const num = (v) => (String(v).trim() === '' ? '' : parseFloat(String(v).replace(/,/g, '')));\n    return { kind: get('kind'), low: num(get('low')), high: num(get('high')), label: get('label'), why: get('why'), tf: '' };\n  }).map((z, i) => ({ ...z, tf: (br.edit.zones[i] && br.edit.zones[i].tf) || '' }));\n  return e;\n}\n\nasync function brPost() {\n  if (br.busy) return;\n  const e = brCollect();\n  const b = br.brief;\n  if (!e.headline.trim()) return brError('Add a headline.');\n  if (!e.zones.length) return brError('Add at least one zone.');\n  if (!e.plan.trim()) return brError('Write the plan.');\n  const live = br.data && br.data.mode === 'live';\n  if (!(await pbConfirm(live ? `Post the ${brSessionName(b.session)} brief to the Inner Circle?` : 'Test mode: post this brief to the team group?'))) return;\n  br.busy = true;\n  $('brPost').disabled = true;\n  $('brPost').textContent = 'POSTING…';\n  try {\n    const body = { headline: e.headline, bias: e.bias, reason: e.reason, zones: e.zones.map((z) => ({ ...z, high: z.high === '' ? z.low : z.high })), plan: e.plan, chart: e.chart, lesson: e.lesson };\n    const res = demo ? { brief: brDemoPost(b, body) } : await pbSend(`/api/briefs/${b.id}/post`, body);\n    pbToast(res.warning || `Brief #${res.brief.id} posted.`);\n    try { tg && tg.HapticFeedback.notificationOccurred('success'); } catch {}\n    brSheet(false);\n    await brLoad(true);\n  } catch (err) {\n    brError(err.message);\n  } finally {\n    br.busy = false;\n    $('brPost').disabled = false;\n    if (br.step === 'draft') brDraftForm();\n  }\n}\n\nasync function brDiscard() {\n  const b = br.brief;\n  if (!(await pbConfirm('Drop this draft? Nothing is posted.'))) return;\n  try {\n    if (demo) brDemoDrop(b.id);\n    else await pbSend(`/api/briefs/${b.id}/discard`, {});\n    brSheet(false);\n    brLoad(true);\n  } catch (err) {\n    brError(err.message);\n  }\n}\n\nasync function brRetry() {\n  const b = br.brief;\n  br.busy = true;\n  br.readStart = clock();\n  brStep('reading');\n  try {\n    const res = demo ? { brief: brDemoRead() } : await pbSend(`/api/briefs/${b.id}/read`, {});\n    br.brief = res.brief;\n    br.edit = null;\n    brStep('draft');\n    brLoad(true);\n  } catch (err) {\n    brStep('draft');\n    brError(err.message);\n  } finally {\n    br.busy = false;\n  }\n}\n\nfunction brError(message) {\n  $('brError').textContent = message;\n  $('brError').hidden = !message;\n  if (message) $('brError').scrollIntoView({ block: 'nearest', behavior: 'smooth' });\n}\n\n// ------------------------------------------------------------- teach\nfunction brTeachSheet(open) {\n  $('brTeachSheet').hidden = !open;\n  document.body.style.overflow = open ? 'hidden' : '';\n  if (open) brTeachRender();\n}\n\nfunction brTeachRender() {\n  const me = (br.data && br.data.me) || { guide: '', prefs: { remind: false, sessions: [], lead: BRIEF.lead }, lessons: [] };\n  $('brGuide').value = me.guide;\n  const p = me.prefs;\n  for (const x of $('brRemind').querySelectorAll('button')) x.setAttribute('aria-pressed', String((x.dataset.v === 'on') === p.remind));\n  $('brRemindSessions').innerHTML = BRIEF.sessions.map((s) => `<button type=\"button\" data-v=\"${s.id}\" aria-pressed=\"${p.sessions.includes(s.id)}\">${s.name}</button>`).join('');\n  for (const x of $('brLead').querySelectorAll('button')) x.setAttribute('aria-pressed', String(Number(x.dataset.v) === p.lead));\n  $('brLessons').innerHTML = me.lessons.length\n    ? me.lessons.map((l) => `<div class=\"br-lesson\"><span><small>${pbDate(l.created)} · ${l.kind === 'edit' ? 'your edits' : 'you said'}</small>${pbEsc(l.text)}</span><button type=\"button\" data-forget=\"${l.i}\">FORGET</button></div>`).join('')\n    : '<p class=\"fine\" style=\"margin:0\">Nothing yet. When you change TCP AI\\'s draft before posting, what you changed is kept here and read before the next brief.</p>';\n}\n\nasync function brTeachSave(extra = {}) {\n  const me = br.data && br.data.me;\n  if (!me) return;\n  const prefs = {\n    remind: $('brRemind').querySelector('[aria-pressed=\"true\"]').dataset.v === 'on',\n    sessions: [...$('brRemindSessions').querySelectorAll('[aria-pressed=\"true\"]')].map((x) => x.dataset.v),\n    lead: Number(($('brLead').querySelector('[aria-pressed=\"true\"]') || { dataset: { v: BRIEF.lead } }).dataset.v),\n  };\n  const body = { guide: $('brGuide').value, prefs, ...extra };\n  const lesson = $('brNewLesson').value.trim();\n  if (lesson && !extra.forget) body.lesson = lesson;\n  try {\n    if (demo) {\n      Object.assign(me, { guide: body.guide, prefs });\n      if (body.lesson) me.lessons.unshift({ i: Date.now(), created: clock(), kind: 'note', text: body.lesson });\n      if (extra.forget) me.lessons = me.lessons.filter((l) => l.i !== extra.forget);\n    } else {\n      br.data.me = (await pbSend('/api/briefs/teach', body)).me;\n    }\n    $('brNewLesson').value = '';\n    brTeachRender();\n    if (!extra.forget) pbToast('Saved. TCP AI reads this before every brief.');\n  } catch (err) {\n    pbToast(err.message);\n  }\n}\n\nasync function brExportAll() {\n  if (demo) return pbToast('Demo: there is no data to send.');\n  try {\n    const res = await pbSend('/api/briefs/export', {});\n    pbToast(`Sent to you in Telegram: ${res.briefs} briefs and ${res.lessons} lessons.`);\n  } catch (err) {\n    pbToast(err.message);\n  }\n}\n\nasync function brViewChart(id) {\n  try {\n    let url = br.photos[id];\n    if (!url) {\n      if (demo) throw new Error('Demo: there is no chart to show.');\n      const res = await fetch(`/api/briefs/${id}/chart`, { headers: { authorization: 'tma ' + (tg ? tg.initData : '') } });\n      if (!res.ok) throw new Error(\"The chart isn't available right now.\");\n      url = br.photos[id] = URL.createObjectURL(await res.blob());\n    }\n    $('pbViewerImg').src = url;\n    $('pbViewer').hidden = false;\n  } catch (err) {\n    pbToast(err.message);\n  }\n}\n\n// ------------------------------------------------------------------- wiring\nfunction brInit() {\n  $('brNew').addEventListener('click', () => { haptic(); brSheet(true); });\n  $('brClose').addEventListener('click', () => brSheet(false));\n  $('brSheet').addEventListener('click', (e) => { if (e.target === $('brSheet')) brSheet(false); });\n  $('brSession').addEventListener('click', (e) => {\n    const x = e.target.closest('button[data-v]');\n    if (!x) return;\n    haptic();\n    br.form.session = x.dataset.v;\n    brChartsForm();\n  });\n  $('brSymbol').addEventListener('click', (e) => {\n    const x = e.target.closest('button[data-v]');\n    if (!x) return;\n    haptic();\n    br.form.symbol = x.dataset.v;\n    if (!state.data[x.dataset.v]) loadMarket(x.dataset.v);\n    brChartsForm();\n  });\n  $('brFiles').addEventListener('change', async () => {\n    const files = $('brFiles').files;\n    if (files && files.length) await brAddCharts(files);\n    $('brFiles').value = '';\n  });\n  $('brThumbs').addEventListener('click', (e) => {\n    const x = e.target.closest('[data-drop]');\n    if (!x) return;\n    const [c] = br.form.charts.splice(Number(x.dataset.drop), 1);\n    if (c) URL.revokeObjectURL(c.url);\n    brChartsForm();\n  });\n  $('brRead').addEventListener('click', brSubmit);\n  $('brBias').addEventListener('click', (e) => {\n    const x = e.target.closest('button[data-v]');\n    if (!x) return;\n    haptic();\n    brCollect().bias = x.dataset.v;\n    brDraftForm();\n  });\n  $('brZones').addEventListener('input', (e) => {\n    const row = e.target.closest('.br-zrow');\n    if (!row) return;\n    const i = Number(row.dataset.i);\n    const z = brCollect().zones[i];\n    if (e.target.dataset.f === 'kind') row.className = `br-zrow ${z.kind}`;\n    const odds = row.querySelector('[data-zodds]');\n    odds.textContent = brEditOdds(br.brief, z);\n  });\n  $('brZones').addEventListener('click', (e) => {\n    const x = e.target.closest('[data-zdrop]');\n    if (!x) return;\n    brCollect().zones.splice(Number(x.dataset.zdrop), 1);\n    brZoneRows();\n  });\n  $('brAddZone').addEventListener('click', () => {\n    const e = brCollect();\n    if (e.zones.length >= BRIEF.maxZones) return;\n    e.zones.push({ kind: 'level', low: '', high: '', label: '', why: '', tf: '' });\n    brZoneRows();\n    const rows = $('brZones').querySelectorAll('.br-zrow');\n    rows[rows.length - 1].querySelector('[data-f=\"low\"]').focus();\n  });\n  $('brChartPick').addEventListener('click', (e) => {\n    const x = e.target.closest('button[data-k]');\n    if (!x) return;\n    brCollect().chart = Number(x.dataset.k);\n    brPostCharts();\n  });\n  $('brPost').addEventListener('click', brPost);\n  $('brDrop').addEventListener('click', brDiscard);\n  $('brRetry').addEventListener('click', brRetry);\n  $('brManual').addEventListener('click', () => { $('brFailed').hidden = true; $('brHeadline').focus(); });\n\n  $('brTeach').addEventListener('click', () => brTeachSheet(true));\n  $('brTeachClose').addEventListener('click', () => brTeachSheet(false));\n  $('brTeachSheet').addEventListener('click', (e) => { if (e.target === $('brTeachSheet')) brTeachSheet(false); });\n  for (const id of ['brRemind', 'brLead']) {\n    $(id).addEventListener('click', (e) => {\n      const x = e.target.closest('button[data-v]');\n      if (!x) return;\n      for (const y of $(id).querySelectorAll('button')) y.setAttribute('aria-pressed', String(y === x));\n    });\n  }\n  $('brRemindSessions').addEventListener('click', (e) => {\n    const x = e.target.closest('button[data-v]');\n    if (x) x.setAttribute('aria-pressed', String(x.getAttribute('aria-pressed') !== 'true'));\n  });\n  $('brTeachSave').addEventListener('click', () => brTeachSave());\n  $('brLessons').addEventListener('click', (e) => {\n    const x = e.target.closest('[data-forget]');\n    if (x) brTeachSave({ forget: Number(x.dataset.forget) });\n  });\n  $('brExport').addEventListener('click', brExportAll);\n\n  const clicks = (e) => {\n    const chart = e.target.closest('[data-chart]');\n    if (chart) return brViewChart(Number(chart.dataset.chart));\n    const open = e.target.closest('[data-open]');\n    if (open) { haptic(); $('brSheet').hidden = false; document.body.style.overflow = 'hidden'; return brOpenDraft(Number(open.dataset.open)); }\n    const row = e.target.closest('[data-brrow]');\n    if (row) {\n      const id = Number(row.dataset.brrow);\n      if (br.opened.has(id)) br.opened.delete(id);\n      else br.opened.add(id);\n      haptic();\n      brHistory();\n    }\n  };\n  $('brList').addEventListener('click', clicks);\n  $('brHistoryCard').addEventListener('click', clicks);\n  $('brHistoryCard').addEventListener('keydown', (e) => { if ((e.key === 'Enter' || e.key === ' ') && e.target.closest('[data-brrow]')) { e.preventDefault(); clicks(e); } });\n\n  // Opened from the reminder's button (?brief=london): the AI tab, and the charts sheet for a poster.\n  const asked = new URLSearchParams(location.search).get('brief');\n  brLoad().then(() => {\n    if (!asked || !briefSession(asked)) return;\n    showTab('ai');\n    if (!brPoster()) return;\n    const draft = br.data.briefs.find((b) => b.session === asked && ['draft', 'failed'].includes(b.status));\n    if (draft) { $('brSheet').hidden = false; document.body.style.overflow = 'hidden'; brOpenDraft(draft.id); } else brSheet(true, { session: asked });\n  });\n}\n\n// -------------------------------------------------------------------- demo\n// Made-up briefs for design work (?demo), around the demo price. The zone record sits at the\n// random walk's line on purpose, so a screenshot of it can't pass for a record that shows an edge.\nfunction brDemo() {\n  if (br.demo) return br.demo;\n  const now = clock();\n  const q = quoteOf('XAUUSD');\n  const p = q ? q.price : 3742.5;\n  const cents = (v) => Math.round(v * 100) / 100;\n  const london = briefWindows(now).filter((w) => w.id === 'london' && w.close > now - 3600)[0];\n  const asia = briefWindows(now).filter((w) => w.id === 'asia' && w.open < now).pop();\n  const zonesAt = (x) => [\n    { kind: 'supply', low: cents(x + 12), high: cents(x + 16.5), tf: '4H', label: '4H supply', why: 'Sellers twice last week', odds: 0.31 },\n    { kind: 'liquidity', low: cents(x + 7.5), high: cents(x + 7.5), tf: '1H', label: 'Asia high', why: 'Stops above it', odds: 0.52 },\n    { kind: 'demand', low: cents(x - 14), high: cents(x - 9.5), tf: '4H', label: '4H demand', why: 'H4 zone at the fib pocket, first tap', odds: 0.44 },\n  ];\n  const briefs = [];\n  let id = 30;\n  // Earlier briefs, scored: reached about as often as a random walk would, turning either way.\n  let a = 7;\n  const random = () => { a = (a * 16807) % 2147483647; return a / 2147483647; };\n  for (let k = 9; k >= 1; k--) {\n    const posted = now - k * 26 * 3600;\n    const plain = zonesAt(p - 20 + random() * 40);\n    const zones = plain.map((z) => {\n      const reached = random() < z.odds;\n      const turn = (random() - 0.5) * 0.8;\n      return { ...z, review: reached ? { reached: true, at: posted + 3600 * (1 + random() * 4), away: cents(8 + turn * 10), through: cents(8 - turn * 10), turn } : { reached: false } };\n    });\n    const reached = zones.filter((z) => z.review.reached).length;\n    const session = ['asia', 'london', 'newyork'][k % 3];\n    briefs.push({\n      id: id--, session, day: '', opens: posted + 1800, closes: posted + 9 * 3600, symbol: 'XAUUSD', author: 'Lewis', status: 'posted', test: false,\n      posted, price: p, photo: false, ai: true, reviewed: posted + 9 * 3600,\n      final: { headline: ['Range day: fade the edges', 'Buyers in control above the Asia low', 'Sellers defend last week\\'s high'][k % 3], bias: ['neutral', 'long', 'short'][k % 3],\n        reason: 'The 4H matrix is split and the day is inside value.', zones: plain, plan: ['Wait for the edge, then the reaction.'], chart: 1 },\n      review: { zones, counted: 3, reached, expected: 1.27 },\n    });\n  }\n  if (asia) {\n    const zones = zonesAt(p + 3);\n    const scored = asia.close < now;\n    const reviewed = zones.map((z, i) => ({ ...z, review: i === 2 ? { reached: true, at: asia.open + 5400, away: 9.4, through: 2.1, turn: 0.36 } : { reached: false } }));\n    briefs.push({ id: 31, session: 'asia', day: asia.key, opens: asia.open, closes: asia.close, symbol: 'XAUUSD', author: 'Lewis', status: 'posted', test: false,\n      posted: asia.open - 1500, price: p + 3, photo: false, ai: true, reviewed: scored ? asia.close + 300 : null,\n      final: { headline: 'Quiet Asia: the range is the plan', bias: 'neutral', reason: 'No sweep yet; the 4H is still inside last week\\'s value.', zones, plan: ['Fade the range edges while it holds.'], chart: 1 },\n      review: scored ? { zones: reviewed, counted: 3, reached: 1, expected: 1.27 } : null });\n  }\n  if (london) {\n    briefs.push({ id: 32, session: 'london', day: london.key, opens: london.open, closes: london.close, symbol: 'XAUUSD', author: 'Lewis', status: 'posted', test: false,\n      posted: Math.min(now - 600, london.open - 1500), price: p, photo: false, ai: true, reviewed: null, review: null,\n      final: { headline: 'Buyers defending the 4H demand into London', bias: 'long', reason: 'Asia held the zone twice and the trend matrix is bull 3/4.',\n        zones: zonesAt(p), plan: ['A sweep of the demand that closes back above is the long, toward the Asia high.', 'A close below the demand: stand aside until New York.'], chart: 2 } });\n  }\n  briefs.sort((x, y) => y.id - x.id);\n  br.demo = {\n    ready: true, ai: true, mode: 'live', canPost: true, briefs, next: null,\n    me: { guide: '', prefs: { remind: true, sessions: ['asia', 'london', 'newyork'], lead: 45 }, lessons: [\n      { i: 2, created: now - 90000, kind: 'edit', text: 'London, XAUUSD: bias long → neutral; removed Asia high; rewrote the plan' },\n      { i: 1, created: now - 200000, kind: 'note', text: 'The Asia high only matters once it has been swept.' }], readsToday: 1, limit: 12 },\n  };\n  br.demo.stats = briefStats(briefs);\n  br.demo.memory = { briefs: briefs.length, charts: briefs.length * 5, reads: briefs.length, lessons: 2 };\n  return br.demo;\n}\n\n// A made-up read of the demo's charts.\nfunction brDemoRead() {\n  const d = brDemo();\n  const q = quoteOf(br.form.symbol) || quoteOf('XAUUSD');\n  const p = q ? q.price : 3742.5;\n  const w = briefWindow(br.form.session, clock()) || briefDefault(clock());\n  const cents = (v) => Math.round(v * 100) / 100;\n  const b = {\n    id: 40, session: w.id, day: w.key, opens: w.open, closes: w.close, symbol: br.form.symbol, author: 'Demo', status: 'draft', test: false,\n    charts: br.form.charts.map((c, i) => ({ k: i + 1, kept: true })), model: 'claude-opus-5', cost: 0.21, ai: true,\n    read: {\n      charts: br.form.charts.map((c, i) => ({ chart: i + 1, timeframe: ['5M', '15M', '30M', '1H', '4H', '1D'][i] || '?', price: cents(p), trend: i < 3 ? 'up' : 'sideways', summary: i < 3 ? 'Higher lows since the Asia low was swept.' : 'Inside last week\\'s range.' })),\n      panel: [{ section: 'trend matrix', row: 'aligned', value: 'bull 3/4 · bull 3/4' }, { section: 'setup', row: 'next H4 zone', value: `${brPrice('XAUUSD', p - 9.5)} · ${brPrice('XAUUSD', p + 12)}` }],\n      unreadable: [], confidence: 'medium',\n    },\n    draft: {\n      headline: 'Buyers defending the 4H demand into the open', bias: 'long', reason: 'The zone held in Asia and the matrix is bull 3/4.',\n      zones: [\n        { kind: 'supply', low: cents(p + 12), high: cents(p + 16.5), tf: '4H', label: '4H supply', why: 'Sellers twice last week', odds: 0.31 },\n        { kind: 'demand', low: cents(p - 14), high: cents(p - 9.5), tf: '4H', label: '4H demand', why: 'H4 zone at the fib pocket', odds: 0.44 },\n      ],\n      plan: ['A sweep of the demand that closes back above is the long.', 'A close below it: wait for New York.'], chart: Math.min(2, br.form.charts.length || 1),\n      warnings: br.form.charts.length < 5 ? [`Not among the charts: ${['5M', '15M', '30M', '1H', '4H'].slice(br.form.charts.length).join(', ')}.`] : [],\n    },\n  };\n  d.briefs = d.briefs.filter((x) => x.id !== 40);\n  d.briefs.unshift(b);\n  return b;\n}\n\nfunction brDemoPost(b, body) {\n  const d = brDemo();\n  const q = quoteOf(b.symbol);\n  const posted = { ...b, status: 'posted', posted: clock(), price: q ? q.price : 3742.5, final: { ...body, plan: String(body.plan).split('\\n').filter(Boolean), zones: body.zones.map((z) => ({ ...z, odds: 0.4 })) } };\n  d.briefs = d.briefs.filter((x) => x.id !== b.id);\n  d.briefs.unshift(posted);\n  return posted;\n}\n\nfunction brDemoDrop(id) {\n  const d = brDemo();\n  d.briefs = d.briefs.filter((x) => x.id !== id);\n}\n\n// TCP Quant Terminal: the page. build.mjs puts lib.js in front of this file and\n// both inside app.html, so every name from lib.js is in scope here.\n// ------------------------------------------------------------------ setup\nconst BOT = 'TCPInnerCircleBot';\nconst tg = window.Telegram && window.Telegram.WebApp;\nconst demo = new URLSearchParams(location.search).has('demo');\nconst $ = (id) => document.getElementById(id);\nconst store = {\n  get: (k) => { try { return localStorage.getItem('tcp.' + k); } catch { return null; } },\n  set: (k, v) => { try { localStorage.setItem('tcp.' + k, v); } catch {} },\n};\nfor (const el of document.querySelectorAll('[data-crown]')) el.replaceWith($('crown').content.cloneNode(true));\nif (tg) {\n  tg.ready();\n  tg.expand();\n  try { tg.setHeaderColor('#0E0D0B'); tg.setBackgroundColor('#0E0D0B'); tg.disableVerticalSwipes && tg.disableVerticalSwipes(); } catch {}\n}\nconst haptic = () => { try { tg && tg.HapticFeedback.selectionChanged(); } catch {} };\nconst clock = () => Math.floor(Date.now() / 1000);\nconst money = (v, ccy) => (ccy === 'GBP' ? '£' : ccy === 'EUR' ? '€' : '$') + fmtNum(v, 2);\nconst signed = (v, d) => (v > 0 ? '+' : v < 0 ? '−' : '') + fmtNum(Math.abs(v), d);\nconst pct = (p) => (p == null ? '—' : p >= 0.995 ? '>99%' : p < 0.005 ? '<1%' : `${Math.round(p * 100)}%`);\nconst ago = (t) => { const s = clock() - t; return s < 10 ? 'just now' : s < 90 ? `${s}s ago` : `${fmtDuration(s)} ago`; };\nconst ordinal = (n) => n + (n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] || 'th');\nconst tzOffset = () => -new Date().getTimezoneOffset() * 60; // the chart shows the member's local time\n\n// ------------------------------------------------------------------- data\nasync function call(path) {\n  const res = await fetch(path, { headers: { authorization: 'tma ' + (tg ? tg.initData : '') } });\n  const body = await res.json().catch(() => ({}));\n  if (!res.ok) throw Object.assign(new Error(body.message || 'Something went wrong'), { code: body.error, status: res.status });\n  return body;\n}\n\nasync function post(path, body) {\n  const res = await fetch(path, {\n    method: 'POST',\n    headers: { authorization: 'tma ' + (tg ? tg.initData : ''), 'content-type': 'application/json' },\n    body: JSON.stringify(body),\n  });\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw Object.assign(new Error(data.message || 'Something went wrong'), { code: data.error });\n  return data;\n}\n\n// Demo mode (?demo): two months of made-up prices, run through the same engine. No member data.\nconst demoWalk = {};\nfunction demoData(symbol) {\n  const m = MARKETS[symbol];\n  let seed = symbol === 'XAUUSD' ? 11 : 29;\n  const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);\n  const normal = () => Math.sqrt(-2 * Math.log(rand() + 1e-12)) * Math.cos(2 * Math.PI * rand());\n  const now = clock();\n  const quiet = symbol === 'XAUUSD' ? 0.0011 : 0.0035;\n  const hourSd = (h) => (h >= 8 && h < 12 ? quiet * 2.6 : h >= 3 && h < 8 ? quiet * 1.6 : quiet);\n  const bars = [];\n  let price = symbol === 'XAUUSD' ? 3712 : 64250;\n  for (let t = Math.floor((now - 90 * 86400) / 900) * 900; t <= now - 900; t += 900) {\n    if (!marketOpen(t, m)) continue;\n    const sd = hourSd(nyHour(t)) / 2 / Math.sqrt(3);\n    const o = price;\n    let h = o;\n    let l = o;\n    for (let k = 0; k < 3; k++) { price *= Math.exp(sd * normal()); h = Math.max(h, price); l = Math.min(l, price); }\n    bars.push({ t, o, h, l, c: price });\n  }\n  // ?demo&gold=4286&btc=84460 moves the made-up prices to today's level, for promo footage.\n  const target = parseFloat(new URLSearchParams(location.search).get(symbol === 'XAUUSD' ? 'gold' : 'btc'));\n  if (target > 0) {\n    const k = target / price;\n    for (const b of bars) { b.o *= k; b.h *= k; b.l *= k; b.c *= k; }\n  }\n  const hourly = groupBars(bars, (b) => Math.floor(b.t / 3600)).map((b) => ({ t: Math.floor(b.t / 3600) * 3600, o: b.o, h: b.h, l: b.l, c: b.c }));\n  const snap = snapshot(m, toDays(hourly, m), bars.slice(-400), now);\n  const profile = volProfile(hourly);\n  demoWalk[symbol] = { price: snap.price, sd: (t) => hourSd(nyHour(t)), normal };\n  return {\n    ...snap,\n    engine: { profile, dayEnd: dayEnd(snap.day, m), state: marketState([...hourly, { t: now, o: snap.price, h: snap.price, l: snap.price, c: snap.price }], profile), check: calibrate(hourly, m) },\n    spark: hourly.slice(-47).map((b) => b.c).concat(snap.price),\n    bars: bars.slice(-192).map((b) => [b.t, b.o, b.h, b.l, b.c]),\n    source: 'demo data', updated: now - 20, stale: false, fx: { USD: 1, GBP: 1.34, EUR: 1.17 },\n  };\n}\n\n// ------------------------------------------------------------------ state\nconst state = { symbol: store.get('symbol') === 'BTCUSD' ? 'BTCUSD' : 'XAUUSD', data: {}, fx: null, streaming: false };\nconst live = {}; // symbol -> { price, high, low, t }\nconst current = () => state.data[state.symbol];\nfunction quoteOf(symbol) {\n  const d = state.data[symbol];\n  const l = live[symbol];\n  if (!d || d.error) return null;\n  return { price: l ? l.price : d.price, high: l ? l.high : d.dayHigh, low: l ? l.low : d.dayLow };\n}\n\n// A new price from the stream (or the demo): the quote, today's range, the last candle and the odds follow it.\nfunction onTick(symbol, price, t) {\n  const d = state.data[symbol];\n  if (!d || d.error || !(price > 0)) return;\n  const m = MARKETS[symbol];\n  const l = (live[symbol] ||= { price: d.price, high: d.dayHigh ?? d.price, low: d.dayLow ?? d.price });\n  const direction = Math.sign(price - l.price);\n  l.price = price;\n  l.t = t;\n  if (dayKey(t, m) !== d.day) { loadMarket(symbol); return; }\n  l.high = Math.max(l.high, price);\n  l.low = Math.min(l.low, price);\n  const slot = Math.floor(t / 900) * 900;\n  const last = d.bars[d.bars.length - 1];\n  if (last && last[0] === slot) { last[2] = Math.max(last[2], price); last[3] = Math.min(last[3], price); last[4] = price; }\n  else if (!last || slot > last[0]) d.bars.push([slot, last ? last[4] : price, Math.max(price, last ? last[4] : price), Math.min(price, last ? last[4] : price), price]);\n  if (symbol === state.symbol) {\n    if (series) series.update(candle(d.bars[d.bars.length - 1]));\n    frame(direction);\n  }\n}\n\nlet pendingDirection = 0;\nlet framed = false;\nfunction frame(direction = 0) {\n  if (direction) pendingDirection = direction;\n  if (framed) return;\n  framed = true;\n  requestAnimationFrame(() => {\n    framed = false;\n    renderPrice(pendingDirection);\n    pendingDirection = 0;\n    renderOdds();\n    renderTesting();\n    queueBriefing();\n  });\n}\n\n// The briefing follows the price at most once a second, always ending on the latest tick.\nlet briefTimer = 0;\nfunction queueBriefing() {\n  if (!briefTimer) briefTimer = setTimeout(() => { briefTimer = 0; renderBriefing(); }, 1000);\n}\n\n// Bitcoin streams tick by tick, first from the exchange the Worker's prices came from.\n// A stream that won't connect or goes quiet hands over to the next exchange.\nconst STREAMS = {\n  coinbase: {\n    name: 'Coinbase', url: 'wss://ws-feed.exchange.coinbase.com',\n    hello: { type: 'subscribe', product_ids: ['BTC-USD'], channels: ['ticker'] },\n    tick: (m) => (m.type === 'ticker' && m.product_id === 'BTC-USD' ? [+m.price, Date.parse(m.time) / 1000] : null),\n  },\n  bitstamp: {\n    name: 'Bitstamp', url: 'wss://ws.bitstamp.net',\n    hello: { event: 'bts:subscribe', data: { channel: 'live_trades_btcusd' } },\n    tick: (m) => (m.event === 'trade' && m.data ? [+m.data.price, +m.data.timestamp] : null),\n  },\n  kraken: {\n    name: 'Kraken', url: 'wss://ws.kraken.com/v2',\n    hello: { method: 'subscribe', params: { channel: 'ticker', symbol: ['BTC/USD'] } },\n    tick: (m) => (m.channel === 'ticker' && Array.isArray(m.data) && m.data[0] ? [+m.data[0].last, 0] : null),\n  },\n  binance: {\n    name: 'Binance', url: 'wss://data-stream.binance.vision/ws/btcusdt@miniTicker',\n    hello: null,\n    tick: (m) => (m.e === '24hrMiniTicker' ? [+m.c, m.E / 1000] : null),\n  },\n};\nlet ws = null;\nlet wsTimer = null;\nlet wsQuiet = null;\nconst wsFailed = new Set(); // exchanges that gave no price since the last one that did\nlet wsRounds = 0; // full rounds of exchanges with no price, for the back-off\nfunction streamBitcoin(on) {\n  if (demo) return;\n  clearTimeout(wsTimer);\n  if (!on) {\n    if (ws) { ws.onclose = null; ws.close(); ws = null; }\n    clearTimeout(wsQuiet);\n    state.streaming = false;\n    return;\n  }\n  if (ws) return;\n  const d = state.data.BTCUSD;\n  const first = d && STREAMS[d.feed] ? d.feed : 'coinbase';\n  const order = [first, ...Object.keys(STREAMS).filter((k) => k !== first)];\n  if (order.every((k) => wsFailed.has(k))) { wsFailed.clear(); wsRounds++; }\n  const key = order.find((k) => !wsFailed.has(k));\n  const feed = STREAMS[key];\n  let heard = false;\n  let sock;\n  const retry = () => {\n    // The next exchange straight away; after a whole round with no price, wait longer each time.\n    const wait = wsFailed.size < order.length ? 1000 : Math.min(60e3, 5000 * 2 ** wsRounds);\n    if (state.symbol === 'BTCUSD' && document.visibilityState === 'visible') wsTimer = setTimeout(() => streamBitcoin(true), wait);\n  };\n  try { sock = ws = new WebSocket(feed.url); } catch { ws = null; wsFailed.add(key); retry(); return; }\n  // Nothing for 10 seconds (30 once prices have been flowing): close it and try again.\n  const watch = () => { clearTimeout(wsQuiet); wsQuiet = setTimeout(() => sock.close(), heard ? 30e3 : 10e3); };\n  watch();\n  sock.onopen = () => { if (feed.hello) sock.send(JSON.stringify(feed.hello)); };\n  sock.onmessage = (e) => {\n    let msg;\n    try { msg = JSON.parse(e.data); } catch { return; }\n    const tick = feed.tick(msg);\n    if (!tick || !(tick[0] > 0)) return;\n    if (!heard) { heard = true; wsFailed.clear(); wsRounds = 0; }\n    watch();\n    state.streaming = key;\n    onTick('BTCUSD', tick[0], tick[1] > 0 ? tick[1] : clock());\n  };\n  sock.onclose = () => {\n    if (ws !== sock) return;\n    ws = null;\n    clearTimeout(wsQuiet);\n    state.streaming = false;\n    if (!heard) wsFailed.add(key); // a stream that gave prices and dropped reconnects to the same exchange\n    retry();\n  };\n  sock.onerror = () => sock.close();\n}\n\n// Demo ticks: the same random walk, second by second, so previews move like the real thing.\nfunction demoTick() {\n  const w = demoWalk[state.symbol];\n  const m = MARKETS[state.symbol];\n  const now = Date.now() / 1000;\n  if (!w || !marketStatus(m, now).open) return;\n  w.price *= Math.exp(w.sd(now) * Math.sqrt(1.5 / 3600) * 2.2 * w.normal());\n  onTick(state.symbol, w.price, now);\n}\n\n// ---------------------------------------------------------------- engine strip\nfunction renderEngine(now) {\n  const d = current();\n  const m = MARKETS[state.symbol];\n  const open = marketStatus(m, now).open;\n  const el = $('engine');\n  let mode = 'live';\n  let text = 'starting…';\n  if (d && !d.error) {\n    if (demo) text = 'demo prices · ticking';\n    else if (!open) { mode = 'closed'; const s = marketStatus(m, now); text = `opens in ${fmtDuration(s.opensAt - now)}`; }\n    else if (d.stale) { mode = 'delayed'; text = `last prices ${ago(d.updated)}`; }\n    else if (state.symbol === 'BTCUSD' && state.streaming) text = `${STREAMS[state.streaming].name} ticks`;\n    else text = `synced ${ago(d.updated)}`;\n  }\n  el.className = `engine ${mode}`;\n  $('engineState').textContent = demo ? 'DEMO' : mode === 'live' ? 'LIVE' : mode === 'closed' ? 'CLOSED' : 'DELAYED';\n  $('engineSync').textContent = text;\n}\n\n// ------------------------------------------------------------------ quote\nfunction renderStatus(now) {\n  const m = MARKETS[state.symbol];\n  const s = marketStatus(m, now);\n  const pill = $('status');\n  pill.classList.toggle('open', s.open);\n  pill.lastElementChild.textContent = m.day === 'utc' ? 'Open 24/7'\n    : s.open ? `Open · ${s.weekendClose ? 'weekend' : 'break'} in ${fmtDuration(s.closesAt - now)}`\n    : `${s.reason === 'weekend' ? 'Weekend' : 'Break'} · opens in ${fmtDuration(s.opensAt - now)}`;\n}\n\nfunction renderPrice(direction = 0) {\n  const d = current();\n  const q = quoteOf(state.symbol);\n  if (!q) return;\n  const el = $('price');\n  el.textContent = fmtNum(q.price, d.digits);\n  if (direction) {\n    el.classList.remove('tick-up', 'tick-down');\n    void el.offsetWidth; // restart the flash\n    el.classList.add(direction > 0 ? 'tick-up' : 'tick-down');\n  }\n  const change = d.dayOpen != null ? q.price - d.dayOpen : null;\n  const ch = $('change');\n  ch.className = 'change ' + (change > 0 ? 'up' : change < 0 ? 'down' : '');\n  ch.textContent = change == null ? 'No trading yet today' : `${signed(change, d.digits)} (${signed((change / d.dayOpen) * 100, 2)}%) today`;\n  if (!direction || Date.now() - sparkAt > 2000) { sparkAt = Date.now(); renderSpark(d, q.price); }\n}\nlet sparkAt = 0;\n\nfunction renderSpark(d, price) {\n  const values = d.spark.slice(0, -1).concat(price);\n  const lo = Math.min(...values);\n  const hi = Math.max(...values);\n  const x = (i) => (i / (values.length - 1)) * 110 + 1;\n  const y = (v) => 44 - ((v - lo) / (hi - lo || 1)) * 40;\n  const path = values.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');\n  const rising = price >= values[0];\n  const color = rising ? '#35A68C' : '#E0613F';\n  $('spark').innerHTML = `<defs><linearGradient id=\"sparkFill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"${color}\" stop-opacity=\".28\"/><stop offset=\"1\" stop-color=\"${color}\" stop-opacity=\"0\"/></linearGradient></defs>` +\n    `<path d=\"${path} L111 46 L1 46 Z\" fill=\"url(#sparkFill)\"/><path d=\"${path}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/>` +\n    `<circle cx=\"${x(values.length - 1)}\" cy=\"${y(price)}\" r=\"2.6\" fill=\"${color}\"><animate attributeName=\"r\" values=\"2.6;5;2.6\" dur=\"1.8s\" repeatCount=\"indefinite\"/><animate attributeName=\"opacity\" values=\"1;.5;1\" dur=\"1.8s\" repeatCount=\"indefinite\"/></circle>`;\n}\n\n// ------------------------------------------------------------------ chart\nlet chart = null;\nlet series = null;\nlet lines = [];\nlet coneLines = [];\nlet framedFor = null;\nconst candle = ([t, o, h, l, c]) => ({ time: t + tzOffset(), open: o, high: h, low: l, close: c });\n\nfunction ensureChart() {\n  if (chart || !window.LightweightCharts) return !!chart;\n  if ($('chartNote')) $('chartNote').remove();\n  chart = LightweightCharts.createChart($('chart'), {\n    autoSize: true,\n    layout: { background: { type: 'solid', color: 'transparent' }, textColor: '#A69D8C', fontFamily: 'JetBrains Mono', fontSize: 10 },\n    grid: { vertLines: { color: 'rgba(58,52,41,.35)' }, horzLines: { color: 'rgba(58,52,41,.35)' } },\n    rightPriceScale: { borderColor: '#2E2A22', scaleMargins: { top: 0.1, bottom: 0.08 } },\n    timeScale: { borderColor: '#2E2A22', timeVisible: true, secondsVisible: false, rightOffset: 2 },\n    crosshair: { mode: 1, vertLine: { color: '#6B6352', labelBackgroundColor: '#3A3429' }, horzLine: { color: '#6B6352', labelBackgroundColor: '#3A3429' } },\n  });\n  series = chart.addCandlestickSeries({ upColor: '#35A68C', downColor: '#E0613F', borderVisible: false, wickUpColor: '#35A68C', wickDownColor: '#E0613F' });\n  coneLines = [\n    ['rgba(166,157,140,.75)', 1], ['rgba(227,192,109,.9)', 2], ['rgba(227,192,109,.9)', 2], ['rgba(166,157,140,.75)', 1],\n  ].map(([color, lineStyle]) => chart.addLineSeries({ color, lineWidth: 1, lineStyle, priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false }));\n  return true;\n}\n\nconst LINE_STYLE = {\n  pdh: ['PDH', '#D8AD4E', 2], pdl: ['PDL', '#D8AD4E', 2], pwh: ['PWH', '#E3C06D', 0], pwl: ['PWL', '#E3C06D', 0],\n  tokyo_h: ['Asia H', '#8C7BD1', 2], tokyo_l: ['Asia L', '#8C7BD1', 2],\n};\n\nfunction renderChart(d) {\n  if (!ensureChart()) {\n    if (!window.LightweightCharts && $('chartNote')) $('chartNote').textContent = \"The chart couldn't load. Everything else is live.\";\n    return;\n  }\n  series.applyOptions({ priceFormat: { type: 'price', precision: d.digits, minMove: 1 / 10 ** d.digits } });\n  series.setData(d.bars.map(candle));\n  for (const l of lines) series.removePriceLine(l);\n  lines = d.levels.filter((l) => LINE_STYLE[l.id]).map((l) => {\n    const [title, color, lineStyle] = LINE_STYLE[l.id];\n    return series.createPriceLine({ price: l.price, color, lineWidth: 1, lineStyle, axisLabelVisible: true, title });\n  });\n  renderChartZones();\n  const points = renderCone(clock());\n  if (framedFor !== state.symbol) {\n    framedFor = state.symbol;\n    chart.timeScale().setVisibleLogicalRange({ from: Math.max(0, d.bars.length - 88), to: d.bars.length + Math.min(points, 40) + 1 });\n  }\n}\n\n// The zones of posted session briefs, while their session is to come or running.\nlet zoneLines = [];\nconst ZONE_COLOR = { demand: 'rgba(53,166,140,.85)', supply: 'rgba(224,97,63,.85)', liquidity: 'rgba(227,192,109,.85)', level: 'rgba(166,157,140,.85)' };\nfunction renderChartZones() {\n  if (!series) return;\n  for (const l of zoneLines) series.removePriceLine(l);\n  zoneLines = [];\n  const briefs = brActive(state.symbol);\n  $('zoneKey').hidden = !briefs.length;\n  for (const b of briefs) {\n    for (const z of b.final.zones) {\n      const edges = z.low === z.high ? [z.low] : [z.high, z.low];\n      edges.forEach((price, i) => zoneLines.push(series.createPriceLine({\n        price, color: ZONE_COLOR[z.kind], lineWidth: 1, lineStyle: 3, axisLabelVisible: i === 0, title: i === 0 ? brZoneName(z) : '',\n      })));\n    }\n  }\n}\n\n// The 68% and 95% cones from now to the close, on the chart's 15-minute grid.\nfunction renderCone(now) {\n  const d = current();\n  if (!chart || !d || d.error) return 0;\n  const m = MARKETS[state.symbol];\n  const q = quoteOf(state.symbol);\n  const empty = () => { for (const s of coneLines) s.setData([]); return 0; };\n  if (!marketStatus(m, now).open || !d.engine) return empty();\n  const slot = Math.floor(now / 900) * 900;\n  const points = cone(q.price, d.engine.profile, now, d.engine.dayEnd).filter((p) => p.t % 900 === 0 || p.t === d.engine.dayEnd);\n  if (!points.length) return empty();\n  const off = tzOffset();\n  const apex = { time: slot + off, value: q.price };\n  ['u2', 'u1', 'l1', 'l2'].forEach((key, i) => coneLines[i].setData([apex, ...points.filter((p) => p.t > slot).map((p) => ({ time: p.t + off, value: p[key] }))]));\n  return points.length;\n}\n\n// ------------------------------------------------------------ probability\nlet levelOrder = '';\nfunction renderOdds() {\n  const d = current();\n  const q = quoteOf(state.symbol);\n  if (!d || d.error || !q || !d.engine) return;\n  const now = clock();\n  const m = MARKETS[state.symbol];\n  const open = marketStatus(m, now).open;\n  const variance = open ? varianceBetween(d.engine.profile, now, d.engine.dayEnd) : 0;\n  $('closeIn').textContent = open ? `close in ${fmtDuration(d.engine.dayEnd - now)}` : 'market closed';\n  if (variance > 0) {\n    const [l1, u1] = band(q.price, variance, 1);\n    const [l2, u2] = band(q.price, variance, 2);\n    const pair = (lo, hi) => `<small>HIGH</small>${fmtNum(hi, d.digits)}<br><small>LOW&nbsp;</small>${fmtNum(lo, d.digits)}`;\n    $('band68').innerHTML = pair(l1, u1);\n    $('band95').innerHTML = pair(l2, u2);\n  } else {\n    $('band68').textContent = $('band95').textContent = 'at the open';\n  }\n  const odds = levelOdds(d.levels, q.price, q.high, q.low, variance);\n  const inPlay = odds.filter((o) => !o.touched);\n  const touched = odds.filter((o) => o.touched);\n  const order = `${open}|` + odds.map((o) => o.id + (o.touched ? '*' : o.side === 'above' ? '+' : '-')).join();\n  if (order !== levelOrder) {\n    levelOrder = order;\n    const rows = inPlay.map((o) => `\n      <div class=\"lv ${o.side}\" data-id=\"${o.id}\">\n        <div class=\"lv-top\"><span class=\"lv-name\">${o.name}</span><b class=\"lv-price\">${fmtNum(o.price, d.digits)}</b><em class=\"lv-dist\"></em></div>\n        ${open ? '<div class=\"lv-odds\"><div class=\"lv-bar\"><i></i></div><span class=\"lv-pct\"></span></div>' : ''}\n      </div>`);\n    const at = inPlay.findIndex((o) => o.side === 'below');\n    rows.splice(at < 0 ? rows.length : at, 0, '<div class=\"lv now\"><span>Price now</span><b id=\"lvNow\"></b></div>');\n    $('levels').innerHTML = (open ? '' : '<div class=\"closed-note\">The market is closed: the odds come back at the open.</div>') + rows.join('') +\n      (touched.length ? `<div class=\"touched\"><span class=\"label\">Touched today</span>${touched.map((o) => `<span>${o.name} ${fmtNum(o.price, d.digits)}</span>`).join('')}</div>` : '');\n  }\n  for (const o of inPlay) {\n    const row = $('levels').querySelector(`[data-id=\"${o.id}\"]`);\n    if (!row) continue;\n    row.querySelector('.lv-dist').textContent = signed(o.price - q.price, d.digits);\n    if (!open) continue;\n    const width = `${Math.max(1.5, o.touch * 100)}%`;\n    requestAnimationFrame(() => { row.querySelector('.lv-bar i').style.width = width; });\n    row.querySelector('.lv-pct').textContent = pct(o.touch);\n  }\n  if ($('lvNow')) $('lvNow').textContent = fmtNum(q.price, d.digits);\n}\n\n// ---------------------------------------------------------- market state\nfunction meter(label, value, note, width) {\n  return `<div class=\"meter\"><div class=\"row\"><small>${label}</small><b>${value}</b></div>\n    <div class=\"track\"><i style=\"width:0\" data-w=\"${width}\"></i></div><div class=\"meta\" style=\"margin-top:6px\">${note}</div></div>`;\n}\nconst grow = (root) => requestAnimationFrame(() => requestAnimationFrame(() => {\n  for (const i of root.querySelectorAll('[data-w]')) { i.style.width = `${i.dataset.w}%`; if (i.dataset.l) i.style.left = `${i.dataset.l}%`; }\n}));\nconst volWord = (rank) => (rank < 25 ? 'Quiet' : rank < 60 ? 'Normal' : rank < 85 ? 'Active' : 'Extreme');\nconst trendWord = (eff) => (eff < 20 ? 'Choppy' : eff < 45 ? 'Two-way' : eff < 70 ? 'Trending' : 'Strong trend');\nfunction renderState(d) {\n  const s = d.engine && d.engine.state;\n  if (!s) { $('state').innerHTML = '<div class=\"meta\">The engine needs more history for this market.</div>'; return; }\n  const rank = Math.round(s.volRank * 100);\n  const eff = Math.round(s.efficiency * 100);\n  const mom = [['1h', s.momentum.h1], ['4h', s.momentum.h4], ['24h', s.momentum.h24]].map(([k, z]) => {\n    const c = Math.max(-3, Math.min(3, z || 0));\n    const w = (Math.abs(c) / 3) * 50;\n    return `<div class=\"mom\"><span>${k}</span><div class=\"track mid\"><i class=\"${c >= 0 ? 'pos' : 'neg'}\" style=\"left:50%;width:0\" data-l=\"${c >= 0 ? 50 : 50 - w}\" data-w=\"${w}\"></i></div><em class=\"${c > 0 ? 'up' : c < 0 ? 'down' : ''}\">${c >= 0 ? '+' : '−'}${Math.abs(z || 0).toFixed(1)}σ</em></div>`;\n  }).join('');\n  $('state').innerHTML =\n    meter('Volatility, last 24h', `${volWord(rank)} · ${ordinal(rank)} pct`, 'Ranked against the last two months.', Math.max(3, rank)) +\n    meter('Trend efficiency, last 24h', `${trendWord(eff)} · ${eff}%`, 'Net move ÷ total distance travelled.', Math.max(3, eff)) +\n    `<div class=\"meter\"><div class=\"row\"><small>Momentum</small><b style=\"font-size:12px;color:var(--stone)\">in standard deviations</b></div>${mom}</div>`;\n  grow($('state'));\n}\n\n// ------------------------------------------------------------ volatility\nfunction renderVolatility(d) {\n  $('range').textContent = d.todayRange ? fmtNum(d.todayRange, d.digits) : '—';\n  $('rangePct').textContent = d.rangePct != null && d.todayRange ? `${Math.round(d.rangePct)}%` : '—';\n  $('gaugeFill').style.width = `${Math.min(100, ((d.rangePct || 0) / 150) * 100)}%`;\n  $('atrLine').textContent = d.atr ? `An average day (ATR 14) moves ${fmtNum(d.atr, d.digits)}.` + (d.rangePct > 100 ? ' Today is already bigger than usual.' : '') : '';\n}\n\n// ------------------------------------------------------------ model check\nfunction renderCheck(d) {\n  const c = d.engine && d.engine.check;\n  if (!c) { $('check').innerHTML = '<div class=\"meta\">The model check needs about six weeks of history for this market.</div>'; return; }\n  const W = 320;\n  const H = 180;\n  const x = (p) => 34 + p * (W - 46);\n  const y = (p) => H - 26 - p * (H - 40);\n  const grid = [0, 0.5, 1].map((p) => `<line x1=\"${x(0)}\" x2=\"${x(1)}\" y1=\"${y(p)}\" y2=\"${y(p)}\" stroke=\"#2E2A22\"/><text x=\"${x(0) - 6}\" y=\"${y(p) + 3.5}\" text-anchor=\"end\" fill=\"#8A8274\" font-size=\"9\" font-family=\"JetBrains Mono\">${p * 100}%</text>`).join('');\n  const xs = [0, 0.5, 1].map((p) => `<text x=\"${x(p)}\" y=\"${H - 10}\" text-anchor=\"middle\" fill=\"#8A8274\" font-size=\"9\" font-family=\"JetBrains Mono\">${p * 100}%</text>`).join('');\n  const max = Math.max(...c.bins.map((b) => b.n));\n  const dots = c.bins.map((b) => `<circle cx=\"${x(b.predicted)}\" cy=\"${y(b.observed)}\" r=\"${4 + 7 * Math.sqrt(b.n / max)}\" fill=\"rgba(216,173,78,.22)\" stroke=\"#E3C06D\" stroke-width=\"1.4\"/>`).join('');\n  $('check').innerHTML = `\n    <svg id=\"checkChart\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Forecast against outcome\">\n      ${grid}${xs}\n      <line x1=\"${x(0)}\" y1=\"${y(0)}\" x2=\"${x(1)}\" y2=\"${y(1)}\" stroke=\"#A69D8C\" stroke-dasharray=\"4 4\" stroke-width=\"1\"/>\n      <line x1=\"${x(0.02)}\" x2=\"${x(0.1)}\" y1=\"${y(0.86)}\" y2=\"${y(0.86)}\" stroke=\"#A69D8C\" stroke-dasharray=\"4 4\"/>\n      <text x=\"${x(0.12)}\" y=\"${y(0.86) + 3}\" fill=\"#A69D8C\" font-size=\"9\" font-family=\"JetBrains Mono\">honest line</text>\n      ${dots}\n      <text x=\"${x(0.5)}\" y=\"12\" text-anchor=\"middle\" fill=\"#A69D8C\" font-size=\"9\" font-family=\"JetBrains Mono\">what happened ↑ · what the engine said →</text>\n    </svg>\n    <div class=\"check-stats\">\n      <div><b>${c.n.toLocaleString('en-GB')}</b><span>forecasts</span></div>\n      <div><b>${c.days}</b><span>days replayed</span></div>\n      <div><b>${c.skill > 0 ? '+' : ''}${Math.round(c.skill * 100)}%</b><span>vs guessing</span></div>\n    </div>\n    <div class=\"fine\">Each dot groups forecasts of a touch on the previous day's high or low, made hour by hour on days the engine hadn't seen. Dots on the line mean it said 30% and it happened 30% of the time.${c.skill < 0 ? ' <span class=\"warn\">On this market the engine is currently doing worse than a flat guess, so treat its odds with extra care.</span>' : ''}</div>`;\n}\n\n// ------------------------------------------------------------ sessions\nfunction renderSessions(now) {\n  const list = sessionClock(now);\n  const codes = { sydney: 'SYD', tokyo: 'TKY', london: 'LDN', newyork: 'NY' };\n  const hours = Object.fromEntries(SESSIONS.map((s) => [s.id, s.close - s.open]));\n  $('sessions').innerHTML = list.map((s) => {\n    const progress = s.open ? 100 * (1 - s.closesIn / (hours[s.id] * 3600)) : 0;\n    return `<div class=\"session${s.open ? ' open' : ''}\">\n      <span class=\"code\">${codes[s.id]}</span>\n      <div><b>${s.name}</b><small>${s.open ? `Open · closes in ${fmtDuration(s.closesIn)}` : s.opensIn != null ? `Opens in ${fmtDuration(s.opensIn)}` : 'Closed'}</small></div>\n      <time>${new Date((s.open ? s.until : s.at) * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</time>\n      ${s.open ? `<span class=\"prog\" style=\"width:${progress.toFixed(1)}%\"></span>` : ''}\n    </div>`;\n  }).join('');\n  const open = list.filter((s) => s.open).map((s) => s.name);\n  $('overlap').hidden = open.length < 2;\n  $('overlap').textContent = open.length > 1 ? `${open.join(' and ')} overlap: usually the busiest hours.` : '';\n  $('localTime').textContent = new Date(now * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });\n}\n\n// ------------------------------------------------------------ briefing\n// Plain English from the numbers on this screen. Written by the page, not by AI.\nfunction renderBriefing() {\n  const d = current();\n  const q = quoteOf(state.symbol);\n  if (!d || d.error || !q) { $('briefing').textContent = d && d.error ? d.message : ''; return; }\n  const m = MARKETS[state.symbol];\n  const now = clock();\n  const open = marketStatus(m, now).open;\n  const b = (t) => `<b>${t}</b>`;\n  const parts = [];\n  const change = d.dayOpen != null ? ((q.price - d.dayOpen) / d.dayOpen) * 100 : null;\n  parts.push(change == null\n    ? `${m.name} is at ${b(fmtNum(q.price, d.digits))}, waiting for today's first trade.`\n    : `${m.name} is ${change >= 0 ? 'up' : 'down'} ${b(`${Math.abs(change).toFixed(2)}%`)} today at ${b(fmtNum(q.price, d.digits))}.`);\n  const range = Number.isFinite(q.high) && Number.isFinite(q.low) ? q.high - q.low : d.todayRange;\n  if (d.atr && range) parts.push(`It has covered ${b(`${Math.round((range / d.atr) * 100)}%`)} of an average day's range.`);\n  if (open && d.engine) {\n    const v = varianceBetween(d.engine.profile, now, d.engine.dayEnd);\n    const inPlay = levelOdds(d.levels, q.price, q.high, q.low, v).filter((o) => !o.touched && !o.id.startsWith('round')).sort((x, y) => y.touch - x.touch);\n    if (inPlay[0]) {\n      parts.push(`The likeliest level still in play is the ${inPlay[0].name.toLowerCase()} at ${b(fmtNum(inPlay[0].price, d.digits))}: ` +\n        `a ${b(pct(inPlay[0].touch))} chance of a touch before the close in ${fmtDuration(d.engine.dayEnd - now)}.`);\n    }\n    const [l1, u1] = band(q.price, v, 1);\n    parts.push(`Two times in three, it closes between ${b(fmtNum(l1, d.digits))} and ${b(fmtNum(u1, d.digits))}.`);\n  } else {\n    parts.push('The market is closed, so the odds pick up again at the open.');\n  }\n  const s = d.engine && d.engine.state;\n  if (s) {\n    const trend = { Choppy: 'choppy', 'Two-way': 'two-way', Trending: 'trending', 'Strong trend': 'strongly trending' }[trendWord(Math.round(s.efficiency * 100))];\n    parts.push(`Over the last 24 hours it has been ${trend}, on ${volWord(Math.round(s.volRank * 100)).toLowerCase()} volatility.`);\n  }\n  $('briefing').innerHTML = parts.join(' ');\n}\n\n// --------------------------------------------------- testing a key level\nfunction renderTesting() {\n  const d = current();\n  const q = quoteOf(state.symbol);\n  const el = $('testing');\n  if (!d || d.error || !q || !d.atr || !marketStatus(MARKETS[state.symbol], clock()).open) { el.hidden = true; return; }\n  const touched = (l) => Number.isFinite(q.high) && Number.isFinite(q.low) && l.price <= q.high && l.price >= q.low;\n  const near = d.levels.filter((l) => !touched(l)).map((l) => ({ ...l, gap: Math.abs(l.price - q.price) }))\n    .filter((l) => l.gap <= 0.08 * d.atr).sort((x, y) => x.gap - y.gap)[0];\n  el.hidden = !near;\n  if (near) el.textContent = `⚡ Testing the ${near.name.toLowerCase()} · ${fmtNum(near.gap, d.digits)} away`;\n}\n\n// ------------------------------------------------------ volatility clock\n// The typical move in each hour of the member's day, from the engine's profile.\nfunction renderVolClock(d) {\n  const m = MARKETS[state.symbol];\n  $('vclockTitle').textContent = `When ${m.name.toLowerCase()} moves`;\n  if (!d.engine) { $('vclock').innerHTML = ''; $('vclockNote').textContent = ''; return; }\n  const midnight = new Date();\n  midnight.setHours(0, 0, 0, 0);\n  const t0 = Math.floor(midnight.getTime() / 1000);\n  const hours = Array.from({ length: 24 }, (_, i) => {\n    const t = t0 + i * 3600;\n    const trading = m.day === 'utc' || nyHour(t) !== 17; // gold's daily break\n    return { i, move: trading ? Math.sqrt(d.engine.profile[nyHour(t)]) * d.price : 0 };\n  });\n  const max = Math.max(...hours.map((h) => h.move));\n  const nowHour = new Date().getHours();\n  const w = 320 / 24;\n  const bars = hours.map((h) => {\n    const height = max ? (h.move / max) * 72 : 0;\n    const fill = h.i === nowHour ? 'url(#vcNow)' : 'rgba(166,157,140,.34)';\n    return `<rect x=\"${(h.i * w + 1.5).toFixed(1)}\" y=\"${(78 - height).toFixed(1)}\" width=\"${(w - 3).toFixed(1)}\" height=\"${Math.max(1, height).toFixed(1)}\" rx=\"2\" fill=\"${fill}\"/>`;\n  }).join('');\n  const ticks = [0, 6, 12, 18].map((i) => `<text x=\"${i * w + 2}\" y=\"93\" fill=\"#8A8274\" font-size=\"9\" font-family=\"JetBrains Mono\">${String(i).padStart(2, '0')}:00</text>`).join('');\n  $('vclock').innerHTML = `<defs><linearGradient id=\"vcNow\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#F6E3A3\"/><stop offset=\"1\" stop-color=\"#B0812F\"/></linearGradient></defs>${bars}${ticks}`;\n  const busiest = hours.reduce((a, h) => (h.move > a.move ? h : a), hours[0]);\n  const here = hours[nowHour];\n  $('vclockNote').textContent = `This hour typically moves about ${fmtNum(here.move, d.digits)}. The busiest hour is ${String(busiest.i).padStart(2, '0')}:00 to ${String((busiest.i + 1) % 24).padStart(2, '0')}:00 your time.`;\n}\n\n// ------------------------------------------------------ probability swarm\n// A live Monte Carlo of the engine's own model. Dots launch one after another from\n// the live price and flow to the close, each on its own random path stepping every\n// five minutes with the hour-by-hour volatility; a Brownian-bridge check catches\n// touches between steps. Every finished dot drops into the spread of closing prices\n// and adds to the running share that touched each level, which settles on the\n// engine's analytic odds.\nconst SWARM = { particles: 220, crossMs: 6500, step: 300, bins: 36, window: 700 };\nconst swarm = { raf: 0, visible: true, w: 0, h: 0, ctx: null, model: null, modelAt: 0, lastTs: 0, particles: [], done: [], legendAt: 0 };\nconst reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst LEVEL_COLOR = { pdh: '#D8AD4E', pdl: '#D8AD4E', pwh: '#E3C06D', pwl: '#E3C06D', do: '#F2ECDF', wo: '#F2ECDF' };\nconst SHORT = { pdh: 'PDH', pdl: 'PDL', pwh: 'PWH', pwl: 'PWL', do: 'Open', wo: 'Week open', round_up: 'Round', round_down: 'Round' };\nconst timeLabel = (t) => new Date(t * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });\nconst binOf = (m, x) => Math.max(0, Math.min(SWARM.bins - 1, Math.floor(((x - m.lo) / (m.hi - m.lo)) * SWARM.bins)));\n\nfunction gaussian() {\n  let u = 0;\n  while (!u) u = Math.random();\n  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random());\n}\n\n// The model the dots follow: the variance of each five-minute step to the close,\n// and the levels still in play. Rebuilt every couple of seconds from the live price.\nfunction swarmModel() {\n  const d = current();\n  const q = quoteOf(state.symbol);\n  const now = Date.now() / 1000;\n  if (!d || d.error || !q || !d.engine || !marketStatus(MARKETS[state.symbol], now).open) return null;\n  const steps = [];\n  for (let t = now; t < d.engine.dayEnd;) {\n    const next = Math.min(d.engine.dayEnd, (Math.floor(t / SWARM.step) + 1) * SWARM.step);\n    steps.push(varianceBetween(d.engine.profile, t, next));\n    t = next;\n  }\n  const total = steps.reduce((a, b) => a + b, 0);\n  if (!(total > 0)) return null;\n  const sd = Math.sqrt(total);\n  const x0 = Math.log(q.price);\n  const levels = levelOdds(d.levels, q.price, q.high, q.low, total)\n    .filter((o) => !o.touched && Math.abs(Math.log(o.price / q.price)) < 2.8 * sd)\n    .map((o) => ({ ...o, x: Math.log(o.price) }));\n  return { steps, levels, x0, lo: x0 - 3 * sd, hi: x0 + 3 * sd, end: d.engine.dayEnd, digits: d.digits, symbol: state.symbol };\n}\n\nfunction launch(p, birth, model) {\n  const n = model.steps.length;\n  const xs = new Float64Array(n + 1);\n  xs[0] = model.x0;\n  const hits = {};\n  let above = Infinity;\n  let below = Infinity;\n  for (let k = 0; k < n; k++) {\n    const v = model.steps[k];\n    const a = xs[k];\n    const b = a + Math.sqrt(v) * gaussian();\n    xs[k + 1] = b;\n    for (const l of model.levels) {\n      if (hits[l.id]) continue;\n      // crossed at a step, or between steps (the chance a Brownian bridge reaches the level)\n      if ((a - l.x) * (b - l.x) <= 0 || Math.random() < Math.exp((-2 * (l.x - a) * (l.x - b)) / v)) {\n        hits[l.id] = k + 1;\n        if (l.side === 'above') above = Math.min(above, k + 1);\n        else below = Math.min(below, k + 1);\n      }\n    }\n  }\n  Object.assign(p, { birth, xs, hits, above, below, n });\n}\n\nfunction sizeSwarm() {\n  const c = $('swarm');\n  const w = c.clientWidth;\n  const h = c.clientHeight;\n  if (!w || !h) return false;\n  const dpr = Math.min(2, window.devicePixelRatio || 1);\n  if (c.width !== Math.round(w * dpr) || c.height !== Math.round(h * dpr)) {\n    c.width = Math.round(w * dpr);\n    c.height = Math.round(h * dpr);\n  }\n  swarm.ctx = c.getContext('2d');\n  swarm.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  swarm.w = w;\n  swarm.h = h;\n  return true;\n}\n\nfunction drawSwarm(ts) {\n  const m = swarm.model;\n  const ctx = swarm.ctx;\n  const W = swarm.w;\n  const H = swarm.h;\n  const plotW = W - 62;\n  const top = 18;\n  const bottom = H - 24;\n  const Y = (x) => bottom - ((x - m.lo) / (m.hi - m.lo)) * (bottom - top);\n\n  // Fade the previous frame, which leaves each dot a short trail.\n  ctx.fillStyle = 'rgba(18,17,13,0.2)';\n  ctx.fillRect(0, 0, W, H);\n  ctx.font = '500 9.5px \"JetBrains Mono\", ui-monospace, monospace';\n  ctx.lineWidth = 1;\n\n  // Move the dots; finished ones drop into the closing spread and relaunch from the live price.\n  const landed = [];\n  for (const p of swarm.particles) {\n    let age = (ts - p.birth) / SWARM.crossMs;\n    if (age >= 1) {\n      const bin = binOf(m, p.xs[p.n]);\n      swarm.done.push({ bin, hits: p.hits });\n      landed.push(bin);\n      launch(p, ts, m);\n      age = 0;\n    }\n    p.age = age;\n  }\n  if (swarm.done.length > SWARM.window) swarm.done.splice(0, swarm.done.length - SWARM.window);\n\n  // The spread of closing prices so far, as bars on the right.\n  const counts = new Array(SWARM.bins).fill(0);\n  for (const r of swarm.done) counts[r.bin] += 1;\n  const most = Math.max(1, ...counts);\n  const binH = (bottom - top) / SWARM.bins;\n  ctx.clearRect(plotW + 1, top - 4, W - plotW - 1, bottom - top + 8);\n  counts.forEach((c, i) => {\n    if (!c) return;\n    const y = bottom - (i + 1) * binH;\n    const len = (c / most) * (W - plotW - 10);\n    const g = ctx.createLinearGradient(plotW + 4, 0, plotW + 4 + len, 0);\n    g.addColorStop(0, 'rgba(176,129,47,.55)');\n    g.addColorStop(1, 'rgba(246,227,163,.9)');\n    ctx.fillStyle = g;\n    ctx.fillRect(plotW + 4, y + 0.5, len, Math.max(1, binH - 1));\n  });\n  for (const bin of landed) {\n    ctx.fillStyle = '#FFFFFF';\n    ctx.beginPath();\n    ctx.arc(plotW + 5, bottom - (bin + 0.5) * binH, 2.4, 0, Math.PI * 2);\n    ctx.fill();\n  }\n\n  // Frame, time labels and the live price.\n  ctx.setLineDash([]);\n  ctx.strokeStyle = 'rgba(58,52,41,.9)';\n  ctx.beginPath();\n  ctx.moveTo(plotW + 0.5, top - 8);\n  ctx.lineTo(plotW + 0.5, bottom + 6);\n  ctx.stroke();\n  ctx.fillStyle = '#8A8274';\n  ctx.textAlign = 'left';\n  ctx.fillText('now', 2, H - 7);\n  ctx.fillText('the close', plotW + 5, 11);\n  ctx.textAlign = 'right';\n  ctx.fillText(timeLabel(m.end), plotW - 3, H - 7);\n  ctx.fillStyle = '#35A68C';\n  ctx.beginPath();\n  ctx.arc(1.5, Y(m.x0), 3, 0, Math.PI * 2);\n  ctx.fill();\n\n  // The levels. Labels that would overlap share one line.\n  const placed = [];\n  for (const l of [...m.levels].sort((a, b) => b.x - a.x)) {\n    const y = Math.round(Y(l.x)) + 0.5;\n    const color = LEVEL_COLOR[l.id] || '#8A8274';\n    ctx.strokeStyle = color;\n    ctx.globalAlpha = 0.7;\n    ctx.setLineDash(l.id.startsWith('round') ? [2, 4] : [5, 5]);\n    ctx.beginPath();\n    ctx.moveTo(0, y);\n    ctx.lineTo(plotW, y);\n    ctx.stroke();\n    ctx.globalAlpha = 1;\n    ctx.setLineDash([]);\n    const near = placed.find((q) => Math.abs(q.y - y) < 11);\n    if (near) near.names.push(SHORT[l.id] || l.name);\n    else placed.push({ y, color, names: [SHORT[l.id] || l.name] });\n  }\n  ctx.textAlign = 'left';\n  for (const label of placed) {\n    ctx.fillStyle = label.color;\n    ctx.fillText(label.names.join(' · '), 4, label.y - 4);\n  }\n\n  // The dots, lit once they've touched a level above (gold) or below (violet).\n  for (const p of swarm.particles) {\n    const kf = p.age * p.n;\n    const k = Math.min(p.n - 1, Math.floor(kf));\n    const x = p.xs[k] + (p.xs[k + 1] - p.xs[k]) * (kf - k);\n    const up = p.above <= kf;\n    const down = p.below <= kf;\n    ctx.fillStyle = up && down ? '#FFFFFF' : up ? '#F6E3A3' : down ? '#B7AAF0' : 'rgba(216,173,78,.5)';\n    ctx.beginPath();\n    ctx.arc(p.age * plotW, Y(x), up || down ? 2 : 1.5, 0, Math.PI * 2);\n    ctx.fill();\n  }\n}\n\nfunction drawSwarmMessage(text) {\n  const ctx = swarm.ctx;\n  ctx.clearRect(0, 0, swarm.w, swarm.h);\n  ctx.fillStyle = '#8A8274';\n  ctx.font = '500 12px \"JetBrains Mono\", ui-monospace, monospace';\n  ctx.textAlign = 'center';\n  ctx.fillText(text, swarm.w / 2, swarm.h / 2);\n}\n\nfunction renderSwarmLegend() {\n  const m = swarm.model;\n  if (!m) { $('swarmLegend').innerHTML = ''; return; }\n  const n = swarm.done.length;\n  $('swarmLegend').innerHTML = m.levels.map((l) => {\n    const share = n ? swarm.done.reduce((a, r) => a + (r.hits[l.id] ? 1 : 0), 0) / n : null;\n    return `<div class=\"${l.side}\"><span>${l.name} ${fmtNum(l.price, m.digits)}</span><b>${n ? pct(share) : '…'}</b><em>engine ${pct(l.touch)}</em></div>`;\n  }).join('') || '<div><span>No key level is within reach before the close.</span></div>';\n  $('swarmTag').textContent = `${n.toLocaleString('en-GB')} paths run`;\n}\n\nconst swarmActive = () => !$('markets').hidden && document.visibilityState === 'visible' && swarm.visible;\n\nfunction swarmFrame(ts) {\n  swarm.raf = 0;\n  if (!swarmActive()) return;\n  if (ts - swarm.modelAt > 2000) {\n    const next = swarmModel();\n    swarm.modelAt = ts;\n    if (!next || next.symbol !== swarm.model.symbol) { startSwarm(); return; }\n    swarm.model = next;\n  }\n  drawSwarm(ts);\n  swarm.lastTs = ts;\n  if (ts - swarm.legendAt > 250) {\n    swarm.legendAt = ts;\n    renderSwarmLegend();\n  }\n  swarm.raf = requestAnimationFrame(swarmFrame);\n}\n\n// A fresh swarm: dots spread along the way to the close from the first frame.\nfunction startSwarm() {\n  cancelAnimationFrame(swarm.raf);\n  swarm.raf = 0;\n  if ($('markets').hidden || !sizeSwarm()) return;\n  swarm.model = swarmModel();\n  swarm.done = [];\n  swarm.ctx.clearRect(0, 0, swarm.w, swarm.h);\n  if (!swarm.model) {\n    const d = current();\n    drawSwarmMessage(d && !d.error && d.engine && !marketStatus(MARKETS[state.symbol], clock()).open ? 'The swarm runs while the market is open' : 'Waiting for prices…');\n    $('swarmTag').textContent = 'paths to the close';\n    renderSwarmLegend();\n    return;\n  }\n  const t = performance.now();\n  swarm.modelAt = swarm.lastTs = t;\n  swarm.particles = Array.from({ length: SWARM.particles }, (_, i) => {\n    const p = {};\n    launch(p, t - (i / SWARM.particles) * SWARM.crossMs, swarm.model);\n    return p;\n  });\n  if (reduceMotion) {\n    // No motion: run the paths through once and show where they end.\n    for (const p of swarm.particles) swarm.done.push({ bin: binOf(swarm.model, p.xs[p.n]), hits: p.hits });\n    drawSwarm(t);\n    renderSwarmLegend();\n    return;\n  }\n  swarm.legendAt = 0;\n  if (swarmActive()) swarm.raf = requestAnimationFrame(swarmFrame);\n}\n\nfunction resumeSwarm() {\n  if (!swarm.model) { startSwarm(); return; }\n  if (swarm.raf || !swarmActive() || reduceMotion) return;\n  // Carry on from where the dots stopped, rather than relaunching them all at once.\n  const gap = performance.now() - swarm.lastTs;\n  if (gap > 0) for (const p of swarm.particles) p.birth += gap;\n  swarm.raf = requestAnimationFrame(swarmFrame);\n}\n$('swarm').addEventListener('click', () => { haptic(); startSwarm(); });\nif ('IntersectionObserver' in window) {\n  new IntersectionObserver(([entry]) => { swarm.visible = entry.isIntersecting; if (swarm.visible) resumeSwarm(); }).observe($('swarm'));\n}\nlet resizeTimer = null;\nwindow.addEventListener('resize', () => {\n  clearTimeout(resizeTimer);\n  resizeTimer = setTimeout(() => { startSwarm(); restartOrb(); }, 250);\n});\n\n\n// ------------------------------------------------------------------ AI orb\n// Dots orbiting each other in 3D, linked when they pass close: the AI tab's\n// placeholder while TCP AI is coming.\nconst orb = { raf: 0, dots: null, ctx: null, w: 0, h: 0 };\n\nfunction sizeOrb() {\n  const c = $('orb');\n  const w = c.clientWidth;\n  const h = c.clientHeight;\n  if (!w || !h) return false;\n  const dpr = Math.min(2, window.devicePixelRatio || 1);\n  c.width = Math.round(w * dpr);\n  c.height = Math.round(h * dpr);\n  orb.ctx = c.getContext('2d');\n  orb.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  orb.w = w;\n  orb.h = h;\n  return true;\n}\n\nfunction drawOrb(t) {\n  const ctx = orb.ctx;\n  const cx = orb.w / 2;\n  const cy = orb.h / 2 + 4;\n  ctx.clearRect(0, 0, orb.w, orb.h);\n  const glow = ctx.createRadialGradient(cx, cy, 4, cx, cy, 120);\n  glow.addColorStop(0, 'rgba(246,227,163,.32)');\n  glow.addColorStop(0.35, 'rgba(216,173,78,.1)');\n  glow.addColorStop(1, 'rgba(216,173,78,0)');\n  ctx.fillStyle = glow;\n  ctx.fillRect(0, 0, orb.w, orb.h);\n  const points = orb.dots.map((d) => {\n    const a = d.phase + t * d.speed;\n    let x = Math.cos(a) * d.r;\n    let y = Math.sin(a) * d.r * 0.3;\n    let z = Math.sin(a) * d.r;\n    [y, z] = [y * Math.cos(d.tilt) - z * Math.sin(d.tilt), y * Math.sin(d.tilt) + z * Math.cos(d.tilt)];\n    const spin = d.spin + t * 0.18;\n    [x, z] = [x * Math.cos(spin) + z * Math.sin(spin), -x * Math.sin(spin) + z * Math.cos(spin)];\n    const scale = 240 / (240 + z);\n    return { x: cx + x * scale, y: cy + y * scale, z, scale, size: d.size };\n  });\n  ctx.lineWidth = 0.6;\n  for (let i = 0; i < points.length; i++) {\n    for (let j = i + 1; j < points.length; j++) {\n      const dx = points[i].x - points[j].x;\n      const dy = points[i].y - points[j].y;\n      const d2 = dx * dx + dy * dy;\n      if (d2 > 900) continue;\n      ctx.strokeStyle = `rgba(216,173,78,${(0.2 * (1 - d2 / 900)).toFixed(3)})`;\n      ctx.beginPath();\n      ctx.moveTo(points[i].x, points[i].y);\n      ctx.lineTo(points[j].x, points[j].y);\n      ctx.stroke();\n    }\n  }\n  points.sort((a, b) => b.z - a.z); // far side first\n  for (const p of points) {\n    const alpha = Math.max(0.25, Math.min(1, p.scale - 0.15));\n    ctx.fillStyle = p.z < 0 ? `rgba(246,227,163,${alpha.toFixed(3)})` : `rgba(176,129,47,${alpha.toFixed(3)})`;\n    ctx.beginPath();\n    ctx.arc(p.x, p.y, p.size * p.scale, 0, Math.PI * 2);\n    ctx.fill();\n  }\n}\n\nfunction orbFrame(ts) {\n  orb.raf = 0;\n  if ($('ai').hidden || document.visibilityState !== 'visible') return;\n  drawOrb(ts / 1000);\n  orb.raf = requestAnimationFrame(orbFrame);\n}\n\nfunction startOrb() {\n  if (orb.raf || !sizeOrb()) return;\n  orb.dots ||= Array.from({ length: 90 }, () => ({\n    r: 38 + Math.random() * 58, speed: (0.15 + Math.random() * 0.35) * (Math.random() < 0.5 ? -1 : 1),\n    phase: Math.random() * Math.PI * 2, tilt: (Math.random() - 0.5) * 1.3, spin: Math.random() * Math.PI, size: 0.8 + Math.random() * 1.6,\n  }));\n  if (reduceMotion) drawOrb(0);\n  else orb.raf = requestAnimationFrame(orbFrame);\n}\n\nfunction restartOrb() {\n  cancelAnimationFrame(orb.raf);\n  orb.raf = 0;\n  if (!$('ai').hidden) startOrb();\n}\n\n// ------------------------------------------------------------- notify me\n// Coming-soon features: a tap tells the team who wants what (once per feature).\nconst NOTIFIED = \"✓ You're on the list\";\nfor (const button of document.querySelectorAll('.notify')) {\n  const feature = button.dataset.feature || button.closest('[data-feature]').dataset.feature;\n  if (store.get('notify.' + feature)) { button.disabled = true; button.textContent = NOTIFIED; }\n  button.addEventListener('click', async () => {\n    haptic();\n    button.disabled = true;\n    button.textContent = 'Adding you…';\n    try {\n      if (!demo) await post('/api/interest', { feature });\n      store.set('notify.' + feature, '1');\n      button.textContent = NOTIFIED;\n    } catch {\n      button.disabled = false;\n      button.textContent = 'Try again';\n    }\n  });\n}\n\n// ------------------------------------------------------------ everything\nfunction renderMarket() {\n  const d = current();\n  const m = MARKETS[state.symbol];\n  $('quoteName').textContent = `${m.name} · ${state.symbol === 'XAUUSD' ? 'spot' : 'BTC-USD'}`;\n  const now = clock();\n  renderStatus(now);\n  renderEngine(now);\n  if (!d || d.error) {\n    const message = d ? d.message : 'Loading…';\n    $('price').textContent = '—';\n    $('change').textContent = '';\n    $('spark').innerHTML = '';\n    $('updated').innerHTML = `<span class=\"warn\">${message}</span>`;\n    if ($('chartNote')) $('chartNote').textContent = message;\n    if (series) { series.setData([]); for (const s of coneLines) s.setData([]); }\n    $('levels').innerHTML = `<div class=\"meta\">${message}</div>`;\n    levelOrder = '';\n    for (const id of ['state', 'check', 'vclock']) $(id).innerHTML = '';\n    $('briefing').textContent = d ? message : '';\n    $('testing').hidden = true;\n    cancelAnimationFrame(swarm.raf);\n    swarm.raf = 0;\n    swarm.model = null;\n    if (sizeSwarm()) drawSwarmMessage(d ? 'Prices are unavailable' : 'Waiting for prices…');\n    renderSwarmLegend();\n    return;\n  }\n  renderPrice();\n  $('updated').innerHTML = (d.stale ? '<span class=\"warn\">Showing the last prices we had · </span>' : '') + `Source: ${d.source}`;\n  renderChart(d);\n  levelOrder = '';\n  renderOdds();\n  renderState(d);\n  renderVolatility(d);\n  renderVolClock(d);\n  renderCheck(d);\n  renderBriefing();\n  renderTesting();\n  // A running swarm keeps flowing; its model follows the newest prices every couple of seconds.\n  if (!swarm.model || swarm.model.symbol !== state.symbol) startSwarm();\n  if (!$('entry').value || $('entry').dataset.live === '1') setLiveEntry();\n}\n\nconst inflight = {};\nfunction loadMarket(symbol) {\n  inflight[symbol] ||= (async () => {\n    try {\n      const d = demo ? demoData(symbol) : await call(`/api/markets?symbol=${symbol}`);\n      state.data[symbol] = d;\n      const streamed = live[symbol];\n      if (streamed && streamed.t > d.updated && dayKey(streamed.t, MARKETS[symbol]) === d.day) {\n        live[symbol] = { ...streamed, high: Math.max(streamed.high, d.dayHigh ?? -Infinity), low: Math.min(streamed.low, d.dayLow ?? Infinity) };\n      } else delete live[symbol];\n      if (d.fx) state.fx = d.fx;\n    } catch (err) {\n      if (!state.data[symbol] || state.data[symbol].error) state.data[symbol] = { error: err.code || 'failed', message: err.message };\n    } finally {\n      delete inflight[symbol];\n    }\n    if (symbol === state.symbol) renderMarket();\n    renderRisk();\n  })();\n  return inflight[symbol];\n}\n\nfunction selectSymbol(symbol) {\n  state.symbol = symbol;\n  store.set('symbol', symbol);\n  framedFor = null;\n  for (const b of document.querySelectorAll('.segment button')) b.setAttribute('aria-pressed', String(b.dataset.symbol === symbol));\n  streamBitcoin(symbol === 'BTCUSD');\n  levelOrder = '';\n  renderMarket();\n  loadMarket(symbol);\n}\nfor (const b of document.querySelectorAll('.segment button')) b.addEventListener('click', () => { haptic(); selectSymbol(b.dataset.symbol); });\n\n// The heartbeat: clocks, countdowns and odds move every second, even between prices.\nlet beats = 0;\nfunction heartbeat() {\n  const now = clock();\n  renderEngine(now);\n  renderStatus(now);\n  renderSessions(now);\n  const left = 900 - (now % 900);\n  $('candleTimer').textContent = marketOpen(now, MARKETS[state.symbol])\n    ? `next candle ${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')}`\n    : 'market closed';\n  if (!$('markets').hidden) {\n    renderOdds();\n    renderTesting();\n    if (++beats % 15 === 0) renderCone(now);\n    if (beats % 5 === 0) renderBriefing();\n  }\n  if (!$('signals').hidden) {\n    pbLive();\n    if (now % 45 === 0) { pbLoad(true); pbPrices(); }\n  }\n  if (!$('ai').hidden) {\n    brLive();\n    const reading = br.data && br.data.briefs && br.data.briefs.some((b) => b.status === 'reading');\n    if (now % (reading ? 10 : 60) === 0) brLoad(true);\n  }\n  brReadingTick();\n}\n\n// ------------------------------------------------------------------- risk\nconst risk = { symbol: state.symbol };\nconst num = (id) => parseFloat(String($(id).value).replace(/,/g, ''));\n$('balance').value = store.get('balance') || '';\n$('currency').value = store.get('currency') || 'USD';\n$('riskPct').value = store.get('riskPct') || '1';\n\nfunction setLiveEntry() {\n  const d = state.data[risk.symbol];\n  const q = quoteOf(risk.symbol);\n  if (q && Number.isFinite(q.price)) { $('entry').value = q.price.toFixed(d.digits); $('entry').dataset.live = '1'; }\n}\nfunction selectRiskMarket(symbol) {\n  risk.symbol = symbol;\n  for (const b of document.querySelectorAll('#riskMarket button')) b.setAttribute('aria-pressed', String(b.dataset.symbol === symbol));\n  $('contract').value = store.get('contract.' + symbol) || String(MARKETS[symbol].contract);\n  $('stop').value = '';\n  setLiveEntry();\n  if (!state.data[symbol] && symbol !== state.symbol) loadMarket(symbol);\n  renderRisk();\n}\n\nfunction renderRisk() {\n  const ccy = $('currency').value;\n  const usdPerUnit = state.fx ? state.fx[ccy] : ccy === 'USD' ? 1 : null;\n  $('fxHint').hidden = ccy === 'USD';\n  $('fxHint').textContent = usdPerUnit ? `1 ${ccy} = ${fmtNum(usdPerUnit, 4)} USD (ECB rate)` : `The ${ccy} exchange rate isn't available right now, so use your USD balance.`;\n  for (const b of document.querySelectorAll('#riskChips button')) b.setAttribute('aria-pressed', String(parseFloat(b.dataset.risk) === num('riskPct')));\n  const d = state.data[risk.symbol];\n  const digits = d && d.digits != null ? d.digits : MARKETS[risk.symbol].digits;\n  const r = usdPerUnit && lotSize({ balance: num('balance'), riskPct: num('riskPct'), entry: num('entry'), stop: num('stop'), contract: num('contract'), usdPerUnit });\n  const show = !!r;\n  $('facts').hidden = !show;\n  $('targets').hidden = !show || r.tooSmall;\n  $('oddsNote').hidden = !show || r.tooSmall;\n  if (!show) {\n    $('lots').textContent = '—';\n    $('lotsLine').textContent = !usdPerUnit ? 'Switch the account to USD for now.' : 'Enter your balance, entry and stop loss.';\n    return;\n  }\n  $('lots').textContent = r.tooSmall ? '0.00' : fmtNum(r.lots, 2);\n  $('lotsLine').innerHTML = r.tooSmall\n    ? '<span class=\"warn\">Below the 0.01 minimum: this stop is too wide for this risk.</span>'\n    : `${r.side === 'long' ? 'Buy' : 'Sell'} ${risk.symbol}, risking ${money(r.actualRisk, ccy)}`;\n  $('facts').innerHTML = [\n    ['Risk budget', `${money(r.riskMoney, ccy)} (${fmtNum(num('riskPct'), 2)}%)`],\n    ['Stop distance', fmtNum(r.distance, digits)],\n    ['Each $1 price move', money(r.perPoint, ccy)],\n    ['Loss per 1.00 lot at stop', money(r.riskPerLot, ccy)],\n  ].map(([k, v]) => `<div>${k}<b>${v}</b></div>`).join('');\n  const hourVar = d && d.engine ? d.engine.profile.reduce((a, b) => a + b, 0) / 24 : 0;\n  const odds = r.targets.map((t) => tradeOdds(num('entry'), num('stop'), t.price, hourVar));\n  $('targets').tBodies[0].innerHTML = r.targets.map((t, i) => `<tr><td>${t.r}R</td><td>${fmtNum(t.price, digits)}</td><td>${pct(odds[i] && odds[i].targetFirst)}</td><td class=\"up\">+${money(t.profit, ccy)}</td></tr>`).join('');\n  const first = odds[0];\n  $('oddsNote').innerHTML = `<b>ODDS</b> are the chance the target comes before the stop if the market moves at random. A 2R trade needs to win more than <b>${pct(1 / 3)}</b> of the time to make money; beating those odds is what an edge means.` +\n    (first && first.hours ? ` At this market's usual volatility, a 1R trade like this one is typically decided in about <b>${fmtDuration(first.hours * 3600)}</b>.` : '');\n}\n\nfor (const id of ['balance', 'currency', 'riskPct', 'entry', 'stop', 'contract']) {\n  $(id).addEventListener('input', () => {\n    if (id === 'entry') $('entry').dataset.live = '0';\n    if (['balance', 'currency', 'riskPct'].includes(id)) store.set(id, $(id).value);\n    if (id === 'contract') store.set('contract.' + risk.symbol, $(id).value);\n    renderRisk();\n  });\n}\n$('currency').addEventListener('change', renderRisk);\nfor (const b of document.querySelectorAll('#riskChips button')) b.addEventListener('click', () => { $('riskPct').value = b.dataset.risk; store.set('riskPct', b.dataset.risk); haptic(); renderRisk(); });\nfor (const b of document.querySelectorAll('#riskMarket button')) b.addEventListener('click', () => { haptic(); selectRiskMarket(b.dataset.symbol); });\n$('useLive').addEventListener('click', () => { setLiveEntry(); renderRisk(); });\n\n// ------------------------------------------------------------------- tabs\nfunction showTab(tab) {\n  for (const s of document.querySelectorAll('main > section')) s.hidden = s.id !== tab;\n  for (const b of document.querySelectorAll('nav button')) {\n    if (b.dataset.tab === tab) b.setAttribute('aria-current', 'page');\n    else b.removeAttribute('aria-current');\n  }\n  if (tab === 'markets') { levelOrder = ''; renderOdds(); resumeSwarm(); }\n  if (tab === 'ai') { startOrb(); pbLoad(); brRender(); brLoad(); }\n  if (tab === 'signals') { pbRender(); pbLoad(); pbPrices(); }\n  pbFab();\n  brFab();\n  window.scrollTo(0, 0);\n}\nfor (const b of document.querySelectorAll('nav button')) b.addEventListener('click', () => { haptic(); showTab(b.dataset.tab); });\n\n// ------------------------------------------------------------ sign-in gate\nfunction gate(title, text, cta) {\n  $('gateTitle').textContent = title;\n  $('gateText').textContent = text;\n  const a = $('gateCta');\n  a.hidden = !cta;\n  if (cta) {\n    a.textContent = cta.label;\n    a.href = cta.href;\n    a.onclick = (e) => { if (tg && tg.openTelegramLink) { e.preventDefault(); tg.openTelegramLink(cta.href); } };\n  }\n}\n\nasync function start() {\n  if (!demo) {\n    if (!tg || !tg.initData) {\n      return gate('Open the terminal from Telegram', 'The TCP Quant Terminal opens inside Telegram, for Inner Circle members.', { label: 'OPEN IN TELEGRAM', href: `https://t.me/${BOT}` });\n    }\n    try {\n      const me = await call('/api/me');\n      $('whoName').textContent = me.user.first_name;\n      $('whoInitial').textContent = $('profileInitial').textContent = (me.user.first_name || '?').slice(0, 1).toUpperCase();\n      $('who').hidden = false;\n      $('profileName').textContent = me.user.first_name + (me.user.username ? ` · @${me.user.username}` : '');\n      $('profileRole').textContent = me.role === 'team' ? 'TCP team' : 'TCP Inner Circle member';\n    } catch (err) {\n      if (err.code === 'not_member') {\n        return gate('Members only', 'The Quant Terminal is part of the TCP Inner Circle. Join, and it unlocks here.', { label: 'JOIN THE INNER CIRCLE', href: `https://t.me/${BOT}?start=terminal` });\n      }\n      return gate(\"Couldn't sign you in\", 'Close the terminal and open it again from the bot.', null);\n    }\n  } else {\n    $('whoName').textContent = $('profileName').textContent = 'Demo';\n    $('whoInitial').textContent = $('profileInitial').textContent = 'D';\n    $('profileRole').textContent = 'Demo mode: made-up prices';\n    $('who').hidden = false;\n    window.tcpDemo = { price: (p) => { demoWalk[state.symbol].price = p; onTick(state.symbol, p, Date.now() / 1000); } }; // for previews\n  }\n  $('gate').hidden = true;\n  pbInit();\n  brInit();\n  selectSymbol(state.symbol);\n  selectRiskMarket(state.symbol);\n  heartbeat();\n  setInterval(heartbeat, 1000);\n  setInterval(() => document.visibilityState === 'visible' && !demo && loadMarket(state.symbol), 60e3);\n  if (demo) setInterval(demoTick, 1500);\n  document.addEventListener('visibilitychange', () => {\n    if (document.visibilityState === 'visible') {\n      loadMarket(state.symbol);\n      streamBitcoin(state.symbol === 'BTCUSD');\n      resumeSwarm();\n      restartOrb();\n    }\n    else streamBitcoin(false);\n  });\n}\nstart();\n\n</script>\n</body>\n</html>\n";
